import type { Combinaison } from '@/lib/combinaisons';

/*
 * Combinaisons rapportées par les candidats, mois par mois (2026, hors novembre).
 * Situations et thèmes des candidats ; consignes et documents réécrits pour la plateforme.
 */
const T3 = (title: string) => `${title} Vous écrivez un texte pour le site d’un journal. Dans une première partie (40 à 60 mots), présentez les deux points de vue des documents. Dans une seconde partie (80 à 120 mots), donnez votre opinion en l’argumentant.`;

export const reportedCombinaisons: Combinaison[] = [
  { id: '2026-10-100', theme: 'Cuisinier amateur ou professionnel ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Votre ami Cédric a accepté votre invitation à votre mariage au Château de Chombony, mais il ne sait pas où se trouve ce lieu ni à quoi il ressemble. Écrivez-lui pour le lui présenter : cadre, emplacement, accès, transports, etc.' },
    { prompt: 'Sur votre blog, racontez comment vous avez appris une langue étrangère et ce que cette expérience vous a apporté.' },
    { prompt: T3('Cuisinier amateur ou professionnel ?'), documents: ['Document 1 : Les cuisiniers amateurs peuvent réussir de très belles recettes, mais la vraie maîtrise demande une formation solide et de l’expérience. Sans technique ni savoir-faire, il est difficile de devenir un véritable professionnel de la cuisine.', 'Document 2 : Certains chefs se sont formés grâce à internet et font aujourd’hui le buzz sur les réseaux sociaux. L’exemple d’une passionnée devenue professionnelle montre aussi qu’un amateur peut évoluer, jusqu’à écrire plusieurs livres de cuisine destinés au grand public.'] },
  ] } },
  { id: '2026-10-101', theme: 'La colocation : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez organiser une journée avec votre ami(e). Écrivez-lui pour l’inviter et lui présenter le déroulement prévu : moment du rendez-vous, endroit choisi, activités envisagées, etc.' },
    { prompt: 'Dans le cadre de votre travail, vous avez participé à une formation professionnelle. Votre entreprise vous demande d’en faire un article pour vos collègues : présentez cette journée et donnez votre avis dessus.' },
    { prompt: T3('La colocation : pour ou contre ?'), documents: ['Document 1 : La colocation plaît à ceux qui aiment partager les repas, discuter ou jouer à des jeux de société. Elle facilite aussi les tâches du quotidien et permet de découvrir d’autres modes de vie, de créer des liens et de s’entraider au jour le jour.', 'Document 2 : Vivre à plusieurs peut devenir compliqué quand on recherche du calme ou de l’intimité. Il faut accepter les invités des autres, respecter les tâches ménagères et faire preuve de diplomatie. Tout dépend finalement du colocataire rencontré.'] },
  ] } },
  { id: '2026-10-102', theme: 'Vivre chez ses parents : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Pendant votre voyage, un ami va loger chez vous dans votre appartement. Envoyez-lui un message pour lui expliquer à quoi ressemble le logement et comment y accéder : immeuble, appartement, entrée, accès, etc.' },
    { prompt: 'Rédigez un article de blog consacré au voyage dont vous gardez le meilleur souvenir.' },
    { prompt: T3('Vivre chez ses parents : pour ou contre ?'), documents: ['Document 1 : Vivre chez ses parents pendant les études permet d’économiser sur le loyer et la nourriture, tout en profitant de repas faits maison, d’un logement entretenu et d’une certaine tranquillité. Pour beaucoup de jeunes, c’est aussi un bon moyen de mettre de l’argent de côté pour l’avenir.', 'Document 2 : Cette solution enlève une part de liberté et d’indépendance. Certains jeunes s’ennuient, car leurs parents décident pour eux. Un témoignage souligne même qu’un retour chez ses parents peut être vécu comme un pas en arrière, surtout quand on perd son espace personnel.'] },
  ] } },
  { id: '2026-10-103', theme: 'Les nouvelles technologies pour les enfants', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Vous préparez votre anniversaire et vous souhaitez convier vos amis. Écrivez-leur un message pour les inviter et expliquer comment la fête va s’organiser.' },
    { prompt: 'Partir étudier dans un autre pays présente des côtés positifs, mais aussi des difficultés. Qu’en pensez-vous ?' },
    { prompt: T3('Les nouvelles technologies pour les enfants.'), documents: ['Document 1 : À l’école primaire, les enfants peuvent utiliser la technologie pour revoir des vidéos sur les notions étudiées ou s’exercer avec des jeux éducatifs. Ces outils peuvent aussi les aider en mathématiques, en lecture et dans l’apprentissage de la saisie au clavier.', 'Document 2 : Les nouvelles technologies risquent de rendre les enfants trop sédentaires, ce qui inquiète beaucoup de parents. Elles laissent moins de place au jeu libre, aux échanges en face à face et à l’activité physique. Mieux vaut donc proposer d’autres activités pour les éloigner des écrans.'] },
  ] } },
  { id: '2026-10-104', theme: 'Les jeux vidéo : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Le journal « Bienvenue » prépare un numéro sur les habitants de la ville. Rédigez un message à publier : présentez-vous, puis décrivez les endroits que vous aimez le plus dans cette ville.' },
    { prompt: 'Vous venez d’aller voir en concert l’artiste que vous aimez le plus. Rédigez un article pour votre blog personnel afin de raconter ce moment et de donner envie à vos amis ainsi qu’aux lecteurs d’assister au prochain spectacle.' },
    { prompt: T3('Les jeux vidéo : pour ou contre ?'), documents: ['Document 1 : Chez les enfants et les adolescents, la pratique régulière des jeux vidéo peut entraîner des pensées négatives et des attitudes agressives. Une étude menée auprès de joueurs de 9 à 18 ans montre que les jeux violents favorisent nettement ce comportement.', 'Document 2 : On insiste souvent sur les effets nocifs des jeux vidéo, mais ils peuvent aussi stimuler le cerveau et apporter des bénéfices pour la santé. Ils amélioreraient notamment la concentration, la créativité et les capacités d’analyse, car il faut sans cesse réfléchir et résoudre des problèmes.'] },
  ] } },
  { id: '2026-10-105', theme: 'Égalité entre hommes et femmes au travail', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Votre amie Jeanne pense à venir découvrir votre pays. Écrivez-lui un message personnalisé en lui suggérant un parcours de visite. Indiquez plusieurs étapes, comme des villes, des lieux touristiques et des monuments connus, en précisant à chaque fois pourquoi vous les recommandez.' },
    { prompt: 'Racontez un souvenir personnel lié à votre participation à une émission de télévision. Expliquez dans quel cadre vous avez été invité, quel était votre rôle pendant l’émission et ce que cette expérience vous a appris ou laissé comme impression.' },
    { prompt: T3('Égalité entre hommes et femmes au travail.'), documents: ['Document 1 : Dans le monde du travail, certains emplois restent surtout occupés par des hommes. Pourtant, au Québec, les femmes peuvent exercer les mêmes fonctions qu’eux, y compris des postes de responsabilité. L’égalité entre les sexes y est reconnue, ce qui montre que ces métiers ne devraient pas être réservés à un seul genre.', 'Document 2 : Même si l’on parle beaucoup de parité dans les entreprises et les collectivités, la réalité est différente : certains métiers sont surtout exercés par des femmes, comme celui de sage-femme. Par ailleurs, les femmes ne devraient pas faire les métiers des hommes, car leur priorité doit être de s’occuper de leurs enfants.'] },
  ] } },
  { id: '2026-10-106', theme: 'La gratuité des transports en commun : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Vous lisez cette annonce : « Je cherche un vélo d’occasion en bon état et pas cher. Écrivez-moi à mathieu@courriel.com. » Vous vendez un vélo : écrivez à Mathieu pour le présenter, indiquer votre prix et proposer un rendez-vous pour l’essayer.' },
    { prompt: 'Rédigez un message à vos amis pour leur raconter votre emploi temporaire pendant les vacances d’été, en décrivant ce que vous avez fait et ce que vous avez retenu de cette expérience.' },
    { prompt: T3('La gratuité des transports en commun : pour ou contre ?'), documents: ['Document 1 : Rendre les transports publics gratuits serait une excellente décision. Moins de voitures circuleraient en ville, ce qui réduirait les embouteillages et la pollution. Dans ma ville, cette mesure existe déjà : les habitants empruntent davantage bus et tramways, et les commerces du centre-ville en profitent aussi, car les clients y reviennent plus volontiers.', 'Document 2 : Je ne pense pas que cette idée soit pertinente. Elle coûterait trop cher aux villes, alors qu’il y a sans doute d’autres priorités, comme l’aménagement des espaces verts à Toulouse. Il vaudrait mieux améliorer le réseau existant, surtout dans les quartiers éloignés. Enfin, payer son billet incite à respecter davantage les transports publics.'] },
  ] } },
  { id: '2026-10-107', theme: 'Les animaux de compagnie au travail : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Vous terminez une mission professionnelle à l’étranger et vous souhaitez marquer votre départ. Rédigez un courriel à vos collègues pour les inviter au restaurant, en précisant votre projet et en donnant toutes les informations utiles, comme la date, l’heure et le lieu.' },
    { prompt: 'Vous avez démarré un nouveau sport et, sur votre blog, vous racontez cette découverte. Vous expliquez aussi en quoi cette activité pourrait plaire au plus grand nombre.' },
    { prompt: T3('Les animaux de compagnie au travail : pour ou contre ?'), documents: ['Document 1 : Autoriser les chiens ou les chats au bureau peut vraiment aider les salariés à se sentir mieux. Leur présence apaise l’atmosphère, réduit le stress et diminue les tensions entre collègues. Elle peut aussi renforcer la motivation au travail. D’après certaines études, cela pourrait même avoir un effet positif important sur la santé des employés.', 'Document 2 : Dans mon entreprise, les salariés peuvent venir avec leur animal, mais je n’apprécie pas cette idée. Les animaux peuvent être imprévisibles, et cela peut gêner certaines personnes. Il y a aussi des risques pour la santé, notamment pour les allergiques. Sans compter que cela peut distraire les employés et nuire à leur efficacité. — Iris, 34 ans'] },
  ] } },
  { id: '2026-10-108', theme: 'Que pensez-vous des maisons de retraite ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Thomas vous a écrit pour mieux connaître la culture de votre pays : il souhaite découvrir une grande fête traditionnelle. Répondez-lui en présentant une célébration importante chez vous et en expliquant ce qu’elle représente.' },
    { prompt: 'Vous avez assisté à un festival de cinéma et découvert plusieurs films. Sur votre site personnel, racontez celui que vous avez préféré et expliquez clairement pourquoi il vous a marqué davantage que les autres.' },
    { prompt: T3('Que pensez-vous des maisons de retraite ?'), documents: ['Document 1 : Dans mon pays, les maisons de retraite sont très peu nombreuses. Lorsqu’une personne âgée ne peut plus vivre seule, elle reste généralement avec les plus jeunes de sa famille, et cela se passe plutôt bien. Nous trouvons étrange de confier nos parents ou nos grands-parents à des inconnus.', 'Document 2 : Beaucoup critiquent les maisons de retraite, mais elles rendent pourtant de grands services aux personnes âgées. Elles leur évitent l’isolement, car elles vivent avec d’autres personnes du même âge. Elles offrent aussi des soins adaptés et rassurent les enfants comme les petits-enfants. Seul problème : leur coût reste trop élevé pour certains.'] },
  ] } },
  { id: '2026-10-109', theme: 'Les cours de langue en ligne', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Ali vous a écrit pour savoir comment se passe votre nouveau travail. Répondez-lui en décrivant votre poste, votre lieu de travail, vos collègues et les premières impressions que vous avez eues.' },
    { prompt: 'Le site « Infos familles » recherche des témoignages sur la vie avec une personne âgée. Vous avez partagé le quotidien d’un senior : racontez cette expérience et ce qu’elle vous a apporté.' },
    { prompt: T3('Les cours de langue en ligne.'), documents: ['Document 1 : Apprendre une langue sur Internet est tout à fait possible et cela peut donner de très bons résultats. Les cours sont accessibles à toute heure, ce qui facilite l’organisation de la journée. En plus, on évite les déplacements vers une école de langues et l’on peut suivre les leçons depuis chez soi, son bureau ou un café. C’est aussi plus économique.', 'Document 2 : Même si cela paraît pratique, l’apprentissage en ligne ne convient pas à tout le monde. Il faut une bonne connexion et un appareil adapté pour suivre les cours. Il faut aussi être très autonome, car apprendre seul chez soi demande de la discipline. Sans l’encadrement d’un professeur, on peut vite perdre sa motivation et abandonner.'] },
  ] } },
  { id: '2026-10-110', theme: 'Les produits faits maison : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Un ami vous écrit pour vous parler d’une salle de sport qu’il trouve superbe et vous demande des détails. Répondez-lui en lui donnant vos impressions et les informations que vous avez sur cet endroit.' },
    { prompt: 'Sur un forum, vous avez découvert une discussion sur les formations à distance. Racontez votre propre expérience, par exemple pour un cours de langue ou une formation professionnelle, et expliquez ce que vous avez apprécié ainsi que ce qui vous a déplu.' },
    { prompt: T3('Les produits faits maison : pour ou contre ?'), documents: ['Document 1 : Préparer soi-même ses produits biologiques permet de choisir chaque ingrédient et d’obtenir des formules plus saines, adaptées à ses besoins. C’est aussi une bonne façon de limiter les emballages plastiques grâce à des contenants réutilisables. À long terme, cela peut revenir moins cher et développer la créativité.', 'Document 2 : Faire ses produits à la maison n’est pas sans danger. Une mauvaise recette peut donner un résultat inefficace ou provoquer des irritations. Il faut aussi du temps pour réunir les ingrédients. Sans contrôle fiable, la conservation reste incertaine, avec un risque de contamination. Le budget de départ peut également être élevé.'] },
  ] } },
  { id: '2026-10-111', theme: 'Les parcs zoologiques : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Cela fait un mois que vous vivez dans une nouvelle ville. Rédigez un courriel à votre ami Léo pour lui donner de vos nouvelles et lui parler de votre logement, de votre quartier, de la ville et de vos activités.' },
    { prompt: 'Sur votre blog, racontez une célébration typique à laquelle vous avez pris part, dans votre pays ou ailleurs, et expliquez pour quelles raisons cette expérience vous a plu.' },
    { prompt: T3('Les parcs zoologiques : pour ou contre ?'), documents: ['Document 1 : On ne devrait pas enfermer des animaux sauvages dans des zoos, car ils ne vivent pas dans leur milieu naturel. Pour eux, c’est comme une prison. Voir des ours polaires dans un espace où il fait 15 degrés montre bien que leurs besoins ne sont pas respectés. Ils ont besoin d’espace, de nature et de liberté.', 'Document 2 : Les zoos ont aussi des atouts importants. Ils assurent des soins aux animaux et jouent un rôle utile pour les espèces menacées. Grâce à eux, les programmes de reproduction ont progressé, ce qui augmente les naissances et peut même contribuer à sauver certains animaux.'] },
  ] } },
  { id: '2026-10-112', theme: 'Le vélo en ville : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Vous envoyez un message à votre ami pour lui présenter le programme prévu pour vos prochaines vacances.' },
    { prompt: 'Pour votre blog, faites le récit d’un événement récent auquel vous avez participé, comme une soirée ou une manifestation culturelle, et décrivez ce qui s’est passé.' },
    { prompt: T3('Le vélo en ville : pour ou contre ?'), documents: ['Document 1 : Le vélo n’est pas seulement un sport ou un loisir : en ville, c’est aussi un vrai moyen de transport, pratique pour les trajets personnels et professionnels. Il permet d’aller vite, d’éviter les bouchons et de se déplacer sans stress. Aller au travail à vélo, c’est aussi combiner activité physique et utilité.', 'Document 2 : Se déplacer à vélo en ville peut être risqué. La circulation est dense, beaucoup d’automobilistes ne respectent pas le Code de la route et les pistes cyclables sont souvent insuffisantes. En plus, les cyclistes respirent des gaz d’échappement nocifs, comme le monoxyde de carbone, ce qui peut nuire à leur santé.'] },
  ] } },
  { id: '2026-10-113', theme: 'L’uniforme à l’école : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Vous écrivez à un(e) ami(e) pour lui proposer de pratiquer une activité sportive avec vous. Présentez votre idée en donnant des précisions sur les sports envisagés, l’endroit et le matériel utile.' },
    { prompt: 'Après avoir passé six mois dans une université hors de votre pays, vous envoyez un message à vos amis pour raconter cette période et préciser ce qui vous a particulièrement plu. Écrivez entre 120 et 150 mots.' },
    { prompt: T3('L’uniforme à l’école : pour ou contre ?'), documents: ['Document 1 : Aujourd’hui, la mode influence beaucoup les enfants, et les parents doivent souvent acheter sans cesse de nouveaux vêtements. L’uniforme aide à limiter ces dépenses. Il renforce aussi le sentiment d’appartenance à l’école et la fierté des élèves. Enfin, il réduit les différences sociales et les jugements liés à l’apparence.', 'Document 2 : Au Québec, de plus en plus d’écoles publiques imposent un uniforme, pas seulement les établissements privés. Pourtant, beaucoup d’adolescents n’aiment pas cette idée : ils le trouvent inconfortable, peu esthétique et trop chaud en été. En outre, porter tous les mêmes vêtements empêche, selon eux, d’affirmer sa personnalité.'] },
  ] } },
  { id: '2026-10-114', theme: 'Voyage seul ou voyage accompagné ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Adressez une lettre à votre ami pour l’inviter à venir à un festival de musique organisé dans votre ville. Indiquez les renseignements essentiels : endroit, moment, artistes présents et informations utiles pour participer.' },
    { prompt: 'Dans votre blog, racontez votre plus récente sortie au restaurant : décrivez le lieu, les plats, l’accueil et expliquez ce que vous avez le plus apprécié.' },
    { prompt: T3('Voyage seul ou voyage accompagné ?'), documents: ['Document 1 : Partir seul en voyage offre une liberté totale : on choisit son itinéraire, ses activités et son rythme sans devoir s’adapter à un groupe. Cela permet aussi de mieux profiter des lieux et de faire des rencontres enrichissantes avec les habitants ou d’autres voyageurs, ce qui favorise l’ouverture d’esprit et le développement personnel.', 'Document 2 : Le voyage en solo a aussi ses limites. La solitude peut parfois peser, et l’absence de compagnon de route complique la gestion des imprévus. Pour certaines excursions, surtout dans des endroits isolés ou difficiles, être plusieurs est plus prudent. Enfin, voyager avec un proche permet de partager ses émotions et ses souvenirs.'] },
  ] } },
  { id: '2026-10-115', theme: 'La consommation de viande : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Vous répondez à votre ami Paul pour lui parler de votre centre de langues-cultures. Décrivez les locaux, le matériel utilisé et la qualité de l’enseignement.' },
    { prompt: 'Vous rédigez un article pour le journal de votre entreprise à propos d’un pique-nique entre collègues. Racontez le déroulement de cette sortie en précisant le lieu, les plats, le temps qu’il faisait et l’ambiance.' },
    { prompt: T3('La consommation de viande : pour ou contre ?'), documents: ['Document 1 : Quentin, 45 ans : Je me suis demandé pendant longtemps s’il était vraiment nécessaire de manger de la viande tous les jours. Aujourd’hui, j’en consomme seulement de temps en temps, au restaurant ou chez des amis, et jamais à la maison. Je trouve ce choix plus sain, car mon alimentation est moins riche en gras. Et, à mon avis, cela profite aussi à l’environnement.', 'Document 2 : Vanessa, 24 ans : Réduire sa consommation de viande est un sujet très actuel, mais, pour moi, il est difficile de m’en passer. J’aime découvrir la cuisine de mes amis végétariens, pourtant chez moi, préparer des repas sans viande me paraît compliqué. Je me demande aussi si ce choix n’a pas des conséquences sur la santé : quand j’ai essayé, je me suis sentie fatiguée. Je crois qu’il faut manger de tout pour rester en forme.'] },
  ] } },
  { id: '2026-10-116', theme: 'La chasse : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Vous écrivez à votre ami(e) pour l’inviter à venir passer ses vacances dans votre ville, en indiquant les sites et les lieux à découvrir.' },
    { prompt: 'Dans le cadre d’un concours sur le thème de votre artiste préféré, vous rédigez un billet de blog pour présenter cet artiste et expliquer pourquoi il vous plaît.' },
    { prompt: T3('La chasse : pour ou contre ?'), documents: ['Document 1 : Gala, 29 ans : Je ne comprends pas qu’on puisse prendre du plaisir à abattre des animaux. Pour moi, il est incohérent de dire que l’on aime la nature tout en contribuant à sa destruction.', 'Document 2 : David, journaliste de la FRM : La chasse répond à plusieurs objectifs : se nourrir, vendre, gérer et protéger la faune, défendre des biens ou encore se détendre. Elle peut aussi servir de loisir, d’entraînement ou de symbole de prestige.'] },
  ] } },
  { id: '2026-10-117', theme: 'Les objets connectés : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Vous allez bientôt vous installer dans un nouveau logement. Écrivez à votre ami(e) pour lui expliquer votre organisation de déménagement et lui demander un coup de main, en précisant la date, l’adresse et le déroulement prévu.' },
    { prompt: 'Dans le cadre d’un concours consacré à votre artiste préféré, vous rédigez un article de blog pour le présenter et dire pourquoi vous l’appréciez.' },
    { prompt: T3('Les objets connectés : pour ou contre ?'), documents: ['Document 1 : Les objets connectés simplifient la vie de tous les jours. Reliés au téléphone ou à Internet, ils permettent de piloter à distance le chauffage ou les portes, par exemple. Avec une montre ou un bracelet connecté, on peut aussi suivre ses activités et compter ses pas. Ils sont également utiles pour la santé, car certains rappellent des rendez-vous médicaux ou la prise de médicaments.', 'Document 2 : On estime à 50 milliards le nombre d’objets connectés dans le monde : alarmes, téléviseurs, caméras, volets ou détecteurs de fumée. Cette évolution soulève de vraies inquiétudes en matière de sécurité. Un pirate peut détourner un appareil en quelques minutes, un cambrioleur peut surveiller une maison à distance, et même une voiture connectée peut être prise en main sans autorisation.'] },
  ] } },
  { id: '2026-10-118', theme: 'Les consultations médicales à distance', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Un centre de loisirs a ouvert dans votre quartier. Vous écrivez à un(e) ami(e) pour lui proposer d’y aller avec vous, en présentant le lieu, les activités qui vous attirent et les détails pratiques de la sortie.' },
    { prompt: 'Après une journée d’échanges d’objets et de services entre habitants de votre quartier, vous racontez cette expérience sur votre blog. Dites ce que vous avez donné ou reçu et expliquez ce que vous pensez de cette initiative.' },
    { prompt: T3('Les consultations médicales à distance.'), documents: ['Document 1 : Camille, 38 ans : Depuis que je peux consulter mon médecin à distance, tout est plus simple au quotidien. Pour renouveler une ordonnance ou parler de résultats d’examens, je n’ai plus à me déplacer ni à poser une demi-journée de congé. C’est aussi très pratique pour les personnes qui habitent loin d’un cabinet. Quand la situation s’y prête, je trouve que cela facilite vraiment l’accès aux soins.', 'Document 2 : Laurent, 56 ans : Je reste attaché aux consultations en cabinet. Derrière un écran, le médecin n’examine pas toujours son patient correctement. Certaines personnes ont aussi des difficultés à expliquer leurs symptômes ou à utiliser les outils numériques. De plus, les échanges me semblent moins humains à distance. À mes yeux, la consultation doit d’abord se faire en face à face.'] },
  ] } },
  { id: '2026-10-119', theme: 'Le covoiturage : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Pendant votre absence, un(e) ami(e) va utiliser votre logement. Écrivez-lui un message pour lui indiquer la manière d’obtenir les clés, décrire ce qu’il y a sur place et ajouter quelques recommandations pour bien profiter du séjour.' },
    { prompt: 'Lors d’une balade, vous êtes tombé(e) sur une activité imprévue et vous avez choisi d’y prendre part. Sur votre blog, racontez ce moment et dites pourquoi il vous a laissé un souvenir fort.' },
    { prompt: T3('Le covoiturage : pour ou contre ?'), documents: ['Document 1 : Sarah, 34 ans : Depuis plusieurs mois, je fais du covoiturage avec deux collègues qui travaillent près de mon entreprise. Nous partageons les frais, ce qui me permet d’économiser. Le trajet est aussi plus agréable, car nous échangeons pendant le voyage. Et comme une seule voiture circule au lieu de trois, cela réduit aussi le trafic. Pour moi, c’est une très bonne solution au quotidien.', 'Document 2 : Thomas, 42 ans : J’ai essayé le covoiturage pour aller au travail, mais j’ai fini par arrêter. Il fallait suivre des horaires rigides et parfois faire des détours pour récupérer les autres passagers. Quand quelqu’un annulait à la dernière minute, tout était chamboulé. Je ne pouvais plus faire mes courses ou prolonger ma journée de travail sans prévenir. Je préfère rester libre, même si cela me revient plus cher.'] },
  ] } },
  { id: '2026-10-120', theme: 'Le travail : favorable ou défavorable ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Le mois prochain, vous aimeriez organiser un week-end avec vos amis. Écrivez-leur pour exposer votre projet en donnant des détails sur la destination, le moyen de transport et les loisirs prévus.' },
    { prompt: 'Sur le site « voyage.internaute.fr », un lecteur demande s’il est bon ou non de tout quitter pour voyager pendant un an. Écrivez un message pour donner votre avis en vous appuyant sur des exemples tirés de votre expérience personnelle.' },
    { prompt: T3('Le travail : favorable ou défavorable ?'), documents: ['Document 1 : Le travail prend une place immense dans nos vies. On nous interroge très tôt sur notre futur métier, comme si tout devait tourner autour de cela. Pourtant, il rime souvent avec pression, fatigue et manque de temps pour les proches. Pour beaucoup, réduire son temps de travail permettrait enfin de mieux profiter de sa vie et de ses relations.', 'Document 2 : Renoncer au travail n’efface pas son importance. À la question « Que faites-vous dans la vie ? », on voit bien qu’un emploi participe à l’identité. Selon Jean-Daniel Remond, l’entreprise apporte des liens, un sentiment d’utilité, des amitiés et même des épreuves qui forgent la personnalité. C’est une expérience essentielle.'] },
  ] } },
  { id: '2026-10-121', theme: 'La lecture pour les enfants.', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Votre ami veut se mettre au sport. Vous lui envoyez un message pour lui conseiller une salle de sport de votre quartier en donnant des informations utiles : emplacement, prix, activités proposées, etc.' },
    { prompt: 'Racontez un événement auquel vous avez pris part et qui vous a beaucoup marqué, comme une fête d’anniversaire ou un mariage, en expliquant ce qui vous a le plus impressionné.' },
    { prompt: T3('La lecture pour les enfants..'), documents: ['Document 1 : Avec les nouvelles technologies, beaucoup d’enfants passent plus de temps sur les écrans que dans les livres. Jeux vidéo, réseaux sociaux, sport ou musique attirent davantage leur attention. Face à cela, pourquoi les pousser à lire ? Le goût des livres ne s’impose pas : il vaut mieux laisser chaque enfant choisir ses lectures et ne pas le forcer.', 'Document 2 : La passion de la lecture peut se transmettre dès le plus jeune âge. Même si les livres sont moins présents qu’avant, lire souvent aide l’enfant à enrichir son langage, à mieux écouter et à rester concentré. Lire dix minutes par jour avec ses parents peut aussi créer un moment agréable et renforcer le lien familial.'] },
  ] } },
  { id: '2026-10-122', theme: 'Les salaires des sportifs professionnels : pour ou contre ?', created_at: '2026-10-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 10, source: 'candidats', tasks: [
    { prompt: 'Karim fête bientôt son anniversaire et vous préparez une surprise pour lui. Envoyez un message à vos amis pour les inviter et leur expliquer le déroulement de la soirée, la date, le lieu, le cadeau et le rôle de chacun.' },
    { prompt: 'Sur votre blog, racontez votre participation à un concours artistique, par exemple en peinture, en photo, en chant ou en danse. Expliquez le déroulement, vos émotions et ce que vous avez retiré de cette expérience.' },
    { prompt: T3('Les salaires des sportifs professionnels : pour ou contre ?'), documents: ['Document 1 : Les rémunérations des sportifs de haut niveau choquent parfois, mais elles s’expliquent. Leur carrière dure peu de temps et peut s’interrompre à cause d’une blessure. Pour atteindre ce niveau, ils s’entraînent depuis l’enfance et font de gros sacrifices. En plus, ils génèrent des revenus considérables pour leur club grâce aux ventes, aux droits télévisés et aux sponsors.', 'Document 2 : Il est choquant qu’un footballeur touche en un mois ce qu’un enseignant ou une infirmière ne gagnera jamais en une vie. Pourtant, ces professions sont indispensables. Ces fortunes envoient aussi un mauvais message aux jeunes, qui risquent de privilégier la richesse et la célébrité. Cet argent serait plus utile pour soutenir le sport amateur et les clubs en difficulté.'] },
  ] } },
  { id: '2026-09-100', theme: 'Vivre chez ses parents : avantage ou inconvénient ?', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Vous allez partir en voyage et un ami souhaite rester dans votre appartement pendant votre absence. Envoyez-lui un message pour lui présenter le logement : l’immeuble, l’appartement et les conditions d’accès.' },
    { prompt: 'Écrivez sur votre blog un article consacré au voyage qui vous a laissé votre plus beau souvenir.' },
    { prompt: T3('Vivre chez ses parents : avantage ou inconvénient ?'), documents: ['Document 1 : Vivre chez ses parents pendant les études peut être très avantageux. Les jeunes économisent le loyer et les repas, mangent souvent mieux et vivent dans un cadre rassurant. Comme les dépenses sont réduites, ils peuvent mettre de l’argent de côté pour leurs projets, sans parler du confort et de la tranquillité au quotidien.', 'Document 2 : Vivre avec ses parents limite l’autonomie. Beaucoup de jeunes se sentent dépendants, car leurs parents prennent les décisions à leur place. Un homme de 25 ans raconte qu’après avoir perdu son emploi, il a dû revenir chez ses parents et a perdu son intimité. Pour lui, retourner vivre chez eux, c’est faire marche arrière.'] },
  ] } },
  { id: '2026-09-101', theme: 'Les animaux de compagnie pour les enfants', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Vous avez publié une annonce pour louer votre appartement à Montréal. Répondez par courriel à une personne intéressée en lui donnant des informations sur le logement, le quartier, le loyer et ses caractéristiques.' },
    { prompt: 'Vous débutez à l’Université de Montréal. Écrivez à un ami pour lui parler de vos premiers jours sur le campus et pour dire ce que vous pensez de l’établissement ainsi que des enseignements.' },
    { prompt: T3('Les animaux de compagnie pour les enfants.'), documents: ['Document 1 : Donner un animal à un enfant présente plusieurs avantages. Pour ceux qui n’ont ni frère ni sœur, il devient un compagnon précieux qui aide à éviter la solitude. Il renforce aussi la confiance en soi et apprend à l’enfant qu’un être vivant mérite attention et respect. Avec lui, l’enfant gagne en sécurité et en autonomie.', 'Document 2 : Même si cela peut faire plaisir à un enfant, adopter un animal demande une vraie réflexion. Chien ou chat, il devient un membre de la famille pour longtemps. Son entretien coûte cher et c’est une grande responsabilité. Un animal n’est pas un jouet que l’on abandonne dès que l’enfant s’en lasse.'] },
  ] } },
  { id: '2026-09-102', theme: 'Voyager seul ou accompagné ?', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Adressez une lettre à votre ami afin de l’inviter à un festival de musique organisé dans votre ville. Indiquez les renseignements essentiels, notamment l’endroit, la date, les artistes présents et les informations utiles pour participer.' },
    { prompt: 'Dans un article de blog, racontez votre plus récente sortie au restaurant : le lieu, les plats, l’accueil, entre autres. Expliquez ce que vous avez vécu et précisez ce qui vous a particulièrement plu.' },
    { prompt: T3('Voyager seul ou accompagné ?'), documents: ['Document 1 : Partir seul en voyage offre une liberté totale. On choisit son itinéraire, ses activités et son rythme sans devoir suivre un groupe. Cela permet aussi de découvrir les lieux plus intensément et de sortir de sa zone de confort. En voyageant en solo, on fait souvent des rencontres enrichissantes avec les habitants ou d’autres voyageurs.', 'Document 2 : Voyager seul a aussi ses limites. La solitude peut peser, et l’absence d’un compagnon est un vrai désavantage en cas de problème. Certaines destinations, surtout les régions isolées ou difficiles, sont plus sûres à plusieurs. De plus, voyager accompagné permet de partager ses émotions et ses découvertes avec un proche.'] },
  ] } },
  { id: '2026-09-103', theme: 'Cuisinier amateur ou professionnel ?', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Votre ami Cédric viendra à votre mariage au Château de Chombony, mais il ne sait pas où se trouve ce lieu. Écrivez-lui pour lui présenter le château, sa situation et les moyens d’y accéder.' },
    { prompt: 'Sur un forum internet, racontez votre expérience de l’apprentissage d’une langue étrangère et expliquez comment vous avez vécu cet apprentissage.' },
    { prompt: T3('Cuisinier amateur ou professionnel ?'), documents: ['Document 1 : Les cuisiniers amateurs peuvent réussir de bonnes recettes, mais cela ne suffit pas pour être un vrai professionnel. Sans technique ni véritable savoir-faire, on reste limité. Pour bien exercer ce métier, il faut donc suivre une formation sérieuse et acquérir de l’expérience.', 'Document 2 : Certains cuisiniers ont appris grâce à Internet et sont devenus populaires sur les réseaux sociaux. Une femme passionnée, d’abord simple amatrice, est ensuite devenue professionnelle. Elle a même publié plusieurs livres de cuisine destinés aux personnes qui aiment cuisiner chez elles.'] },
  ] } },
  { id: '2026-09-104', theme: 'Les jeux vidéo : pour ou contre ?', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Vous préparez des vacances entre amis et vous avez repéré un hôtel. Écrivez-leur un message pour présenter cet hébergement, avec sa situation, son tarif, ses services et ses équipements, puis suggérez de le réserver.' },
    { prompt: 'Vous travaillez désormais dans un autre pays. Écrivez un message à vos amis pour leur parler de cette expérience de travail et préciser ce qui vous a particulièrement plu.' },
    { prompt: T3('Les jeux vidéo : pour ou contre ?'), documents: ['Document 1 : Des recherches montrent que les jeux vidéo peuvent stimuler certaines zones du cerveau chez l’adulte. Ils aident notamment à développer l’analyse, la prise de décision et la rapidité de réaction. Comme la majorité des joueurs sont adultes, cela peut sembler positif. Toutefois, il faut rester prudent, car tous les jeux n’ont pas le même effet.', 'Document 2 : Une étude menée pendant trois ans auprès d’enfants de 8 à 17 ans révèle que ceux qui jouent beaucoup aux jeux vidéo sont plus nerveux, plus stressés et parfois plus violents que les autres. Ils obtiennent aussi de moins bons résultats scolaires. Les parents doivent donc surveiller et limiter le temps de jeu.'] },
  ] } },
  { id: '2026-09-105', theme: 'La restauration rapide : pour ou contre ?', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Pendant votre absence, Cédric, votre ami, a accepté de s’occuper de votre maison et de votre jardin. Écrivez-lui un message pour lui indiquer les tâches à faire.' },
    { prompt: 'Après un récent séjour réservé auprès d’une agence de voyages, vous n’êtes pas satisfait(e) des services fournis. Écrivez un courriel de réclamation pour faire part de votre déception, expliquer les difficultés rencontrées et demander une solution à l’agence.' },
    { prompt: T3('La restauration rapide : pour ou contre ?'), documents: ['Document 1 : Les fast-foods peuvent proposer des repas variés et équilibrés. Ils respectent aussi les règles d’hygiène. En plus, c’est au client de composer son menu, ce qui lui laisse la responsabilité de ses choix alimentaires.', 'Document 2 : Selon les spécialistes, aller souvent dans des restaurants rapides nuit à la santé. Les menus se ressemblent, avec des frites, des hamburgers et des boissons sucrées, trop riches en calories. En outre, les emballages plastiques y sont très utilisés, ce qui aggrave la pollution et la production de déchets.'] },
  ] } },
  { id: '2026-09-106', theme: 'L’art urbain : pour ou contre ?', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Un auteur vient prochainement à la bibliothèque de votre ville pour une rencontre. Écrivez à votre ami(e) afin de lui proposer de vous accompagner à cet événement.' },
    { prompt: 'Rédigez un article pour votre blog afin de raconter votre participation à un événement appelé « La semaine du goût ».' },
    { prompt: T3('L’art urbain : pour ou contre ?'), documents: ['Document 1 : L’art dans la ville éveille la curiosité des passants. Une fresque ou une animation de rue crée une ambiance passagère qui met en contact des artistes souvent peu connus et un public varié, parfois peu familier de ces formes d’expression. Les villes évoluent aussi grâce à cette diversité et au street art, qui colorent les murs et améliorent le cadre de vie en respectant davantage la nature.', 'Document 2 : Pourtant, à grande échelle, ces pratiques ne font pas l’unanimité. Les graffitis sont souvent vus comme une atteinte à la communauté, une pollution visuelle ou un signe de fracture sociale. Beaucoup les considèrent comme du vandalisme qui abîme les espaces publics, ce qui alimente un vif débat entre artistes, autorités et habitants.'] },
  ] } },
  { id: '2026-09-107', theme: 'Les nouvelles technologies à l’école : pour ou contre ?', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Après un séjour de deux jours à la campagne, vous écrivez à votre ami(e). Racontez-lui ce que vous y avez vécu pendant ce week-end.' },
    { prompt: 'Votre direction cherche une salle pouvant accueillir 100 personnes pour la fête de fin d’année. Rédigez-lui un message pour proposer le local idéal que vous avez trouvé, en précisant l’endroit, le prix et les services disponibles.' },
    { prompt: T3('Les nouvelles technologies à l’école : pour ou contre ?'), documents: ['Document 1 : Jean : Je pense que les technologies doivent faire partie de l’école, car elles préparent les élèves à un monde de plus en plus numérique. Tablettes et ordinateurs rendent les cours plus motivants et enrichissent l’apprentissage grâce à un accès rapide à de nombreuses ressources. Ils encouragent aussi la créativité et l’autonomie des élèves.', 'Document 2 : Sara : Je reste réservée face à une utilisation trop importante des technologies en classe. À mon avis, elles risquent de diminuer les échanges humains indispensables et de créer une dépendance excessive aux écrans. Les méthodes traditionnelles et la relation directe entre professeurs et élèves demeurent, selon moi, essentielles à un bon équilibre éducatif.'] },
  ] } },
  { id: '2026-09-108', theme: 'Le végétarisme en Europe', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Vous êtes allé(e) manger dans un restaurant récemment ouvert. Écrivez un message à votre ami pour lui présenter ce lieu en parlant de l’atmosphère, du décor, des plats et de la qualité du service.' },
    { prompt: 'Sur un blog ou un forum, racontez votre expérience d’apprentissage d’une langue étrangère.' },
    { prompt: T3('Le végétarisme en Europe.'), documents: ['Document 1 : Le végétarisme offre plusieurs bénéfices. Il contribue d’abord à la santé, car une alimentation riche en fruits et légumes réduit les risques de maladies, notamment cardiaques. Il participe aussi à la protection de l’environnement en limitant la pollution liée à l’élevage. Enfin, il respecte les animaux, un principe de plus en plus apprécié en Europe.', 'Document 2 : Toutefois, ce mode d’alimentation ne convient pas à tout le monde. Certaines personnes ont besoin de viande pour couvrir leurs besoins en fer et en protéines. De plus, les traditions culinaires européennes reposent souvent sur la viande, et modifier ces habitudes peut être difficile. Enfin, composer des repas végétariens équilibrés demande parfois du temps et des connaissances.'] },
  ] } },
  { id: '2026-09-109', theme: 'L’organisation des événements sportifs', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Vous venez de vous installer dans une autre ville. Écrivez à votre amie pour l’inviter à passer ses vacances chez vous.' },
    { prompt: 'Donnez votre point de vue, dans un article de blog, sur l’installation d’une télévision dans une chambre.' },
    { prompt: T3('L’organisation des événements sportifs.'), documents: ['Document 1 : L’État devrait accueillir de grands rendez-vous sportifs, comme les Jeux olympiques, la Coupe du monde ou la Coupe d’Afrique. Ces compétitions font rayonner la culture du pays et attirent l’attention internationale. Elles stimulent aussi l’économie grâce à la création d’emplois et à la modernisation des infrastructures, au bénéfice durable de la population.', 'Document 2 : À l’inverse, ces manifestations coûtent très cher aux finances publiques. Je pense qu’il vaudrait mieux consacrer cet argent à des priorités comme la santé et l’éducation. De plus, plusieurs pays organisateurs ont fini endettés, sans retombées positives réelles pour leurs habitants.'] },
  ] } },
  { id: '2026-09-110', theme: 'Les menus sans viande à la cantine', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Vous préparez une fête. Écrivez un message à vos amis pour les convier et leur demander un coup de main pour l’organisation, par exemple pour l’endroit, le moment ou le style de la soirée.' },
    { prompt: 'Sur un site web, vous racontez la compétition sportive à laquelle vous avez pris part et vous donnez votre opinion sur cette expérience. Dans votre texte, précisez où et quand elle s’est déroulée, ainsi que la manière dont elle était organisée.' },
    { prompt: T3('Les menus sans viande à la cantine.'), documents: ['Document 1 : De plus en plus d’établissements scolaires proposent un repas sans viande à la cantine, au moins deux fois par semaine. Cette solution répond à un enjeu de santé, car les enfants mangent souvent trop de protéines animales. À la place, on sert du soja, des céréales ou des légumes, meilleurs pour l’équilibre alimentaire et moins coûteux pour les familles.', 'Document 2 : Supprimer la viande des cantines ne fait pas l’unanimité. Pour certains, c’est injuste, car la cantine permet à des enfants de familles modestes de manger à moindre coût. Les éleveurs locaux y perdent aussi une part de leurs ventes. Enfin, beaucoup d’enfants trouvent les steaks de soja moins savoureux que ceux de bœuf.'] },
  ] } },
  { id: '2026-09-111', theme: 'La chasse aux animaux : pour ou contre ?', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Vous écrivez à votre ami(e) pour lui proposer de venir passer ses congés dans votre ville. Dans votre message, présentez les lieux à découvrir et les visites que vous lui conseillez.' },
    { prompt: 'À la suite d’un concours permettant de remporter quinze jours dans la ville que vous aimez le plus, dont le sujet est « Mon artiste préféré », vous rédigez un billet de blog consacré à cet artiste que vous admirez.' },
    { prompt: T3('La chasse aux animaux : pour ou contre ?'), documents: ['Document 1 : Pour moi, il est incompréhensible de trouver amusant le fait d’abattre des bêtes. J’ai aussi du mal à accepter qu’on dise respecter l’environnement tout en lui causant du tort. À mes yeux, ces comportements sont totalement contradictoires et ne montrent aucun véritable amour de la nature.', 'Document 2 : La chasse répond à plusieurs objectifs : se nourrir, vendre, gérer la faune, protéger des biens, s’entraîner, se divertir ou encore rechercher du prestige. C’est une activité motivée par des raisons très diverses. David, journaliste de la FRM'] },
  ] } },
  { id: '2026-09-112', theme: 'Le travail : avantage ou inconvénient ?', created_at: '2026-09-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 9, source: 'candidats', tasks: [
    { prompt: 'Vous envoyez un message à votre ami(e) afin de lui proposer de passer avec vous le week-end de la semaine prochaine. Précisez ce que vous comptez faire, l’endroit prévu et toute autre information utile.' },
    { prompt: 'Vous choisissez de tout quitter pour partir voyager pendant une année entière. Rédigez un article de blog pour raconter cette expérience hors du commun.' },
    { prompt: T3('Le travail : avantage ou inconvénient ?'), documents: ['Document 1 : Stéphane, entrepreneur. Je suis persuadé que le travail profite à la fois à la personne et à la société. Il assure un revenu, soutient l’économie et développe l’autonomie. Il renforce aussi la confiance en soi, le sens des responsabilités et peut devenir une source d’épanouissement. Il aide enfin à construire son identité et sa place dans le monde.', 'Document 2 : Laura, sociologue. Tel qu’il existe aujourd’hui, le travail peut aussi avoir des effets négatifs. Il rime souvent avec pression, horaires contraignants et difficulté à concilier vie privée et vie professionnelle. Il peut conduire à l’épuisement, surtout quand les tâches sont lourdes et la reconnaissance insuffisante. Certaines activités deviennent même aliénantes quand on ne se sent ni impliqué ni valorisé.'] },
  ] } },
  { id: '2026-08-100', theme: 'La publicité et les enfants : un danger ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Vous cherchez une personne pour partager votre logement, qui est spacieux. Présentez la formule de colocation que vous proposez et décrivez votre appartement.' },
    { prompt: 'Une compagnie théâtrale est venue s’installer dans votre commune, et vous êtes allé voir une représentation. Écrivez un billet de blog pour raconter et décrire ce moment.' },
    { prompt: T3('La publicité et les enfants : un danger ?'), documents: ['Document 1 : Les enfants sont exposés en permanence à la publicité, à la télévision, dans les magazines ou sur Internet, souvent à des moments où ils sont plus vulnérables. Ils sont particulièrement visés par les annonces pour des aliments peu sains, des jouets ou des jeux vidéo, ce qui influence leurs envies et leurs choix de consommation.', 'Document 2 : Des recherches montrent que les enfants comprennent mal le fonctionnement persuasif de la publicité, car leurs capacités de réflexion restent limitées. Pourtant, l’éducation donnée par les parents, ainsi que l’environnement social et culturel, pèsent souvent davantage que les messages publicitaires dans leurs décisions d’achat.'] },
  ] } },
  { id: '2026-08-101', theme: 'L’autorité parentale : trop sévère ou nécessaire ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Votre ami(e) va bientôt célébrer son anniversaire. Rédigez un message à vos amis pour proposer d’acheter un cadeau commun.' },
    { prompt: 'La direction d’une école de musique cherche un lieu pour une fête réunissant 100 personnes. Rédigez un courriel pour annoncer que vous avez trouvé une salle adaptée, en précisant l’emplacement, les prix et les services proposés.' },
    { prompt: T3('L’autorité parentale : trop sévère ou nécessaire ?'), documents: ['Document 1 : J’ai bientôt 22 ans et je vis toujours chez mes parents, qui restent très stricts avec moi. Quand j’étais mineure, je n’avais pas le droit de rentrer tard ni de dormir dehors. Aujourd’hui, cela a peu changé : ma mère continue de m’appeler sans arrêt jusqu’à mon retour à la maison.', 'Document 2 : Beaucoup de parents redoutent d’être trop sévères et pensent qu’une autorité excessive peut freiner l’épanouissement de leurs enfants. Pourtant, leur dire oui à tout n’est pas une solution. À l’âge adulte, il faut savoir respecter des règles pour vivre en société et s’intégrer dans un groupe.'] },
  ] } },
  { id: '2026-08-102', theme: 'Les nouvelles technologies à l’école : une bonne idée ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Vous avez passé quelques jours à la campagne. Écrivez un message à votre ami(e) pour raconter votre séjour et expliquer ce que vous avez vécu.' },
    { prompt: 'Votre direction cherche une salle pour la fête de fin d’année, capable d’accueillir 100 invités. Écrivez un message pour dire que vous avez trouvé un lieu idéal, avec les informations utiles sur l’emplacement, les tarifs et les services.' },
    { prompt: T3('Les nouvelles technologies à l’école : une bonne idée ?'), documents: ['Document 1 : Jean estime que les technologies doivent faire partie de l’école, car elles préparent les élèves à un monde de plus en plus numérique. Selon lui, tablettes et ordinateurs rendent les cours plus motivants, facilitent l’accès à de nombreuses ressources et développent à la fois la créativité et l’autonomie des élèves.', 'Document 2 : Sara se méfie de l’usage trop important des technologies en classe. À ses yeux, cela diminue les échanges humains essentiels et peut créer une dépendance aux écrans. Elle pense que l’enseignement traditionnel, avec un contact direct entre professeurs et élèves, reste indispensable pour un développement complet.'] },
  ] } },
  { id: '2026-08-103', theme: 'Cuisinier amateur ou cuisinier professionnel ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Vous avez invité votre ami Cédric à votre mariage, organisé au Château de Chombony. Comme il ne connaît pas cet endroit, écrivez-lui pour le lui présenter en donnant des détails sur le site, son emplacement et les moyens d’y aller.' },
    { prompt: 'Sur votre blog, racontez comment vous avez appris une langue étrangère. Vous écrivez sur un forum en ligne pour partager votre expérience personnelle.' },
    { prompt: T3('Cuisinier amateur ou cuisinier professionnel ?'), documents: ['Document 1 : Les cuisiniers amateurs réussissent parfois de très bonnes recettes, mais cela ne suffit pas pour devenir un véritable chef. Sans formation solide ni expérience, il manque toujours des compétences et des techniques essentielles pour exercer ce métier correctement.', 'Document 2 : L’auteur évoque des personnes qui ont appris à cuisiner en ligne et sont devenues célèbres sur les réseaux sociaux. Il raconte aussi l’histoire d’une amatrice qui a fini par devenir professionnelle et a publié plusieurs livres destinés aux passionnés de cuisine à la maison.'] },
  ] } },
  { id: '2026-08-104', theme: 'Les distributeurs automatiques à l’école : pour ou contre ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Votre amie Anna va passer un week-end dans votre ville. Écrivez-lui un message pour lui présenter les moyens de transport qui lui permettront de la découvrir.' },
    { prompt: 'Vous avez participé à une soirée entre habitants de votre quartier. Rédigez un article de blog pour expliquer pourquoi cet événement vous a plu.' },
    { prompt: T3('Les distributeurs automatiques à l’école : pour ou contre ?'), documents: ['Document 1 : Je soutiens l’installation de distributeurs de boissons dans les lycées, car ils sont pratiques pour les élèves qui n’ont pas toujours le temps d’aller à la cafétéria pendant la pause. Bien gérés, ils peuvent aussi proposer des boissons plus saines, comme de l’eau, du jus pur ou des boissons sans sucre ajouté, tout en apportant des revenus à l’établissement.', 'Document 2 : Je suis opposé aux distributeurs de boissons dans les lycées, surtout pour des raisons de santé. Beaucoup contiennent des sodas et des boissons trop sucrées, liés à l’obésité et à d’autres problèmes comme le diabète. Même les jus de fruits ne sont pas toujours innocents, et l’école devrait encourager de meilleures habitudes alimentaires.'] },
  ] } },
  { id: '2026-08-105', theme: 'Les jeux vidéo : pour ou contre ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Le journal « Bienvenue » prépare un article sur les habitants de la ville. Rédigez un message destiné à cette publication. Vous vous êtes installé récemment ici : présentez-vous, puis décrivez les endroits de la ville que vous préférez.' },
    { prompt: 'Vous venez d’assister au concert de votre artiste préféré. Rédigez un texte pour votre blog afin de raconter cette soirée et d’encourager vos amis, ainsi que les autres lecteurs, à aller à son prochain spectacle.' },
    { prompt: T3('Les jeux vidéo : pour ou contre ?'), documents: ['Document 1 : Les jeux vidéo peuvent rendre les enfants et les adolescents plus agressifs. Une étude récente menée auprès de jeunes de 9 à 18 ans a montré que les jeux violents favorisent nettement ce type de comportement. D’après Diego Gentil, ce risque existe presque toujours, même lorsque les parents restent très attentifs.', 'Document 2 : On insiste souvent sur leurs défauts, pourtant les jeux vidéo ont aussi des effets positifs. Ils peuvent stimuler le cerveau en améliorant la concentration, la créativité et l’esprit d’analyse. Cela s’explique facilement : pour progresser, le joueur doit sans cesse réfléchir, chercher des solutions et prendre des décisions.'] },
  ] } },
  { id: '2026-08-106', theme: 'L’interdiction des voitures dans les centres-villes', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Vous avez trouvé sur Internet une annonce proposant de l’aide aux personnes qui veulent apprendre le français, ainsi que des partenaires de conversation pour progresser. Répondez à cette annonce par courriel en vous présentant et en expliquant pourquoi vous souhaitez pratiquer cette langue.' },
    { prompt: 'Vous écrivez à vos amis pour leur parler d’une célébration familiale à laquelle vous avez assisté. Dans votre message, racontez ce moment et dites ce qui vous a le plus plu.' },
    { prompt: T3('L’interdiction des voitures dans les centres-villes.'), documents: ['Document 1 : Face à une pollution préoccupante dans de nombreuses régions du monde, plusieurs villes ont pris une décision radicale : bannir les voitures de leurs centres urbains. Oslo, la capitale norvégienne, a fait ce choix et s’en dit satisfaite. À terme, cette mesure devrait réduire les accidents, limiter la dépendance au pétrole et améliorer nettement la qualité de l’air.', 'Document 2 : Certaines villes interdisent les voitures en centre-ville sans préparer suffisamment la transition. Certes, il y aurait moins d’embouteillages, de stress et de pollution, mais il faut aussi prévoir de grands parkings, renforcer les transports en commun et accorder des dérogations à certains métiers indispensables, comme les policiers, les secours ou les livreurs.'] },
  ] } },
  { id: '2026-08-107', theme: 'La gratuité des transports en commun : pour ou contre ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Vous cherchez un vélo en bon état à petit prix. Écrivez un courriel à mathieu@gmail.com pour proposer votre vélo, en le décrivant et en indiquant son prix. Fixez également un rendez-vous pour qu’il puisse l’essayer.' },
    { prompt: 'Pendant les vacances d’été, vous avez occupé un emploi saisonnier. Écrivez un message à vos amis pour leur raconter cette expérience professionnelle.' },
    { prompt: T3('La gratuité des transports en commun : pour ou contre ?'), documents: ['Document 1 : Les transports publics gratuits constituent, selon moi, une excellente initiative. Ils réduisent le nombre de voitures en circulation, limitent les embouteillages et contribuent à faire baisser la pollution, donc les risques de maladies respiratoires. Dans ma ville, cette mesure a déjà changé les habitudes : davantage de personnes prennent les transports en commun, et les commerçants du centre-ville en profitent aussi.', 'Document 2 : Cette idée me semble mauvaise. Elle coûterait très cher aux municipalités, alors que Toulouse a d’autres priorités. Il vaudrait mieux d’abord améliorer les espaces verts, puis réorganiser le réseau au lieu de le rendre gratuit. Enfin, garder un ticket payant inciterait les usagers à respecter davantage les équipements qu’ils financent.'] },
  ] } },
  { id: '2026-08-108', theme: 'La vie à la campagne : pour ou contre ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez faire découvrir à vos amis un site touristique que vous aimez particulièrement. Dans un message amical, présentez ce lieu, expliquez ce qui vous plaît chez lui et proposez une date, une heure ainsi qu’un hébergement pour cette sortie.' },
    { prompt: 'Sur votre blog, racontez votre déception après votre visite à un festival (musique, cinéma, cuisine, etc.). Expliquez clairement ce qui vous a déplu.' },
    { prompt: T3('La vie à la campagne : pour ou contre ?'), documents: ['Document 1 : Vivre en ville offre, selon moi, beaucoup d’occasions de se divertir. On peut aller facilement au cinéma, manger au restaurant ou faire du shopping, sans avoir à parcourir de longues distances. Il suffit souvent de marcher un peu, ou de prendre un taxi si nécessaire. En plus, la ville propose une offre culturelle très riche : musées, théâtres, opéras, il y a de quoi satisfaire tout le monde.', 'Document 2 : J’ai quitté la ville pour m’installer à la campagne, car j’avais besoin de calme et de nature. Désormais, je préfère recevoir mes amis sur la terrasse de ma maison ou organiser un barbecue dans mon jardin, plutôt que de sortir souvent en ville. Le prix des logements a aussi pesé dans ma décision : à la campagne, ils sont bien plus accessibles.'] },
  ] } },
  { id: '2026-08-109', theme: 'La chasse aux animaux : pour ou contre ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Écrivez à votre ami(e) pour lui proposer de venir passer ses congés dans votre ville. Présentez les sites et les endroits intéressants à découvrir.' },
    { prompt: 'Vous avez pris part à un concours dont le prix était un voyage de quinze jours dans la ville que vous aimez le plus. Le sujet était « Mon artiste préféré ». Rédigez un article de blog pour présenter cet artiste que vous admirez.' },
    { prompt: T3('La chasse aux animaux : pour ou contre ?'), documents: ['Document 1 : À 29 ans, Gala dit qu’elle ne parvient pas à admettre qu’on puisse trouver agréable de faire mourir des bêtes. Selon elle, il est incohérent d’affirmer qu’on respecte le monde naturel tout en participant à sa destruction.', 'Document 2 : « Les personnes qui chassent le font pour des motifs variés : se nourrir, vendre, gérer la faune, protéger les propriétés, faire du sport, se distraire ou encore gagner en prestige. » David, journaliste à la FRM'] },
  ] } },
  { id: '2026-08-110', theme: 'Les produits faits maison : pour ou contre ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Un ami vous parle d’une salle de sport qu’il aimerait découvrir. Répondez-lui par message en présentant celle que vous fréquentez : ambiance, équipements, tarifs et autres détails utiles.' },
    { prompt: 'Vous avez lu une discussion sur un forum à propos des cours en ligne. Écrivez un message pour parler d’une expérience personnelle, par exemple une formation de langue ou professionnelle, et expliquez ce que vous avez aimé ainsi que ce qui vous a moins satisfait.' },
    { prompt: T3('Les produits faits maison : pour ou contre ?'), documents: ['Document 1 : Préparer chez soi ses produits bio permet de choisir soi-même chaque ingrédient, donc d’obtenir des recettes plus saines et mieux adaptées à ses besoins. C’est aussi une bonne façon de réduire les emballages plastiques grâce à des contenants réutilisables. En plus, on fait des économies avec le temps et on apprend des gestes utiles, tout en adoptant une manière de vivre plus écologique.', 'Document 2 : Fabriquer des produits bio à la maison a aussi ses limites. Une recette mal réalisée peut être inefficace, voire provoquer des irritations. Il faut du temps pour trouver et mélanger les ingrédients, et rien ne garantit toujours leur conservation ou leur sécurité. Enfin, le coût de départ peut être élevé, ce qui freine certains consommateurs.'] },
  ] } },
  { id: '2026-08-111', theme: 'La lecture pour les enfants', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Votre ami souhaite commencer une activité sportive. Envoyez-lui un message pour lui recommander une salle de sport de votre quartier, en précisant son emplacement, ses prix et les activités proposées.' },
    { prompt: 'Pensez à une occasion importante à laquelle vous avez pris part, comme une fête d’anniversaire ou un mariage, et racontez ce souvenir marquant.' },
    { prompt: T3('La lecture pour les enfants.'), documents: ['Document 1 : Avec la technologie qui occupe de plus en plus la vie quotidienne, les enfants s’éloignent du livre et passent davantage de temps sur les jeux vidéo, les réseaux sociaux ou le sport. Alors, pourquoi leur imposer la lecture ? Le goût des livres ne se force pas : mieux vaut laisser l’enfant choisir ses lectures, sans le contraindre lorsqu’il n’en a pas envie.', 'Document 2 : L’amour de la lecture se transmet et doit être encouragé dès l’enfance, même si les tablettes et les smartphones prennent aujourd’hui beaucoup de place. Lire régulièrement aide l’enfant à mieux parler, à rester concentré et à écouter plus facilement. De plus, partager dix minutes de lecture chaque jour renforce la complicité entre parents et enfants.'] },
  ] } },
  { id: '2026-08-112', theme: 'Voyage seul ou voyage accompagné ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Vous écrivez à un ami pour l’inviter à un festival de musique organisé dans votre ville. Donnez-lui les informations essentielles : lieu, date, artistes présents et renseignements pratiques.' },
    { prompt: 'Sur votre blog, racontez votre dernière sortie au restaurant : le lieu, les plats, le service et tout ce qui a rendu l’expérience agréable.' },
    { prompt: T3('Voyage seul ou voyage accompagné ?'), documents: ['Document 1 : Partir seul en voyage offre une liberté totale : on choisit son itinéraire, ses activités et son rythme sans devoir tenir compte d’un groupe. C’est aussi l’occasion de vivre les lieux plus intensément et de faire des rencontres inattendues avec des habitants ou d’autres voyageurs. Voyager en solo aide à sortir de sa routine et enrichit vraiment l’expérience personnelle.', 'Document 2 : Le voyage en solo a aussi ses difficultés. La solitude peut parfois peser, et l’absence d’un compagnon devient gênante en cas d’imprévu. Pour certaines destinations isolées ou difficiles, être plusieurs est plus rassurant et plus sûr. Enfin, voyager accompagné permet de partager ses émotions et ses découvertes, ce qui rend souvent l’expérience plus agréable.'] },
  ] } },
  { id: '2026-08-113', theme: 'L’art urbain : pour ou contre ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Envoyez un message à un ami pour lui proposer de vous accompagner à une rencontre avec un auteur, prévue à la bibliothèque de votre ville.' },
    { prompt: 'Sur votre blog, racontez votre participation à l’événement « La Semaine du Goût » et décrivez ce que vous y avez vécu.' },
    { prompt: T3('L’art urbain : pour ou contre ?'), documents: ['Document 1 : L’art dans la rue éveille la curiosité des habitants et transforme l’espace urbain. Une fresque ou une performance crée un moment vivant entre des artistes parfois peu connus et un public varié. Les villes évoluent aussi : elles deviennent plus ouvertes, plus accueillantes et plus colorées grâce au street art, aux espaces verts et à une meilleure harmonie avec l’environnement.', 'Document 2 : Pourtant, à grande échelle, l’art urbain ne fait pas l’unanimité. Les graffitis sont souvent vus comme une dégradation, une nuisance visuelle ou un signe de désordre social. Beaucoup les considèrent comme du vandalisme, car ils abîment les lieux publics. Le débat reste vif entre artistes, autorités et habitants.'] },
  ] } },
  { id: '2026-08-114', theme: 'L’aide aux personnes pauvres', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Annoncez à votre ami(e) francophone que vous venez d’être embauché(e). Dans votre message, présentez votre fonction, les personnes avec qui vous travaillez et l’endroit où vous exercez.' },
    { prompt: '« Chers internautes, j’ai 19 ans et je pars bientôt à l’étranger pour poursuivre mes études. J’aimerais lire les témoignages d’étudiants qui ont déjà étudié loin de chez eux. Merci pour vos réponses. Julie » Vous avez étudié à l’étranger pendant un an. Répondez sur le forum en racontant votre séjour, en disant si cette expérience vous a plu et en expliquant pourquoi.' },
    { prompt: T3('L’aide aux personnes pauvres.'), documents: ['Document 1 : Chaque hiver, je consacre un peu de temps et d’argent à aider les personnes sans abri qui souffrent du froid. Il me semble essentiel de penser à ceux qui manquent de tout. Donner quelques dollars ou soutenir des associations est, selon moi, un geste simple et utile, accessible à chacun. En plus, cela me donne le sentiment d’agir concrètement.', 'Document 2 : Pierre, 65 ans : Au lieu de donner de l’argent aux personnes pauvres, il vaudrait mieux changer notre manière de vivre. Pour ma part, je préfère m’investir chaque jour dans une association de quartier où je suis bénévole. Les sans-abri ont surtout besoin d’un logement et d’un travail pour devenir autonomes. Donner de l’argent ne règle rien, cela sert seulement à calmer sa conscience.'] },
  ] } },
  { id: '2026-08-115', theme: 'Vivre en colocation : avantage ou inconvénient ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Votre ami Mehdi vient de s’installer dans votre ville et souhaite obtenir des informations sur les transports. Rédigez-lui un message en lui présentant les différents moyens de déplacement, les abonnements possibles et les tarifs.' },
    { prompt: 'Dans un article de blog, présentez une personnalité que vous admirez, connue ou non. Appuyez-vous sur des actions précises pour montrer ce qu’elle a accompli et expliquez pourquoi elle vous inspire.' },
    { prompt: T3('Vivre en colocation : avantage ou inconvénient ?'), documents: ['Document 1 : La colocation plaît à ceux qui apprécient la vie collective. Elle permet de partager des repas, de discuter souvent et même d’organiser des jeux entre colocataires. Les tâches quotidiennes, comme la vaisselle ou le ménage, sont aussi réparties. On apprend ainsi à mieux connaître les autres, à découvrir d’autres habitudes et à créer des liens solides.', 'Document 2 : La colocation n’est pas toujours simple. Il faut parfois accepter de ne pas être tranquille quand on en a besoin, supporter les invités des autres et respecter des règles de ménage strictes. Cela demande de la diplomatie au quotidien. Bien sûr, tout devient plus facile si l’on tombe sur un colocataire idéal.'] },
  ] } },
  { id: '2026-08-116', theme: 'Cuisinier amateur ou cuisinier professionnel ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Votre ami Cédric vous a répondu qu’il ne connaît pas le Château de Chombony, où aura lieu votre mariage. Décrivez-lui ce lieu, sa localisation et les moyens d’y accéder.' },
    { prompt: 'Sur un forum en ligne, racontez comment vous avez appris une langue étrangère et partagez votre expérience personnelle.' },
    { prompt: T3('Cuisinier amateur ou cuisinier professionnel ?'), documents: ['Document 1 : Les recettes réussies des amateurs ne suffisent pas pour faire un vrai cuisinier. Sans technique solide ni expérience, il est difficile d’aller plus loin. C’est pourquoi une formation sérieuse reste indispensable pour acquérir les compétences nécessaires à ce métier.', 'Document 2 : Ce texte évoque des cuisiniers autodidactes qui ont appris grâce à internet et ont ensuite connu le succès sur les réseaux sociaux. Il raconte aussi le parcours d’une passionnée devenue professionnelle, qui a publié plusieurs ouvrages destinés aux cuisiniers amateurs à la maison.'] },
  ] } },
  { id: '2026-08-117', theme: 'Les distributeurs automatiques à l’école : pour ou contre ?', created_at: '2026-08-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 8, source: 'candidats', tasks: [
    { prompt: 'Votre ami(e) vous écrit : « Salut ! J’arrive bientôt dans ta ville pour un week-end. Comment je peux me déplacer ? » Répondez-lui en présentant les moyens de transport (métro, tramway, vélo, tarifs).' },
    { prompt: 'Après avoir participé à la fête des voisins dans votre quartier, vous écrivez un article sur votre blog pour raconter comment l’événement s’est déroulé et dire pour quelles raisons cette expérience vous a plu.' },
    { prompt: T3('Les distributeurs automatiques à l’école : pour ou contre ?'), documents: ['Document 1 : De plus en plus de collèges et de lycées retirent les distributeurs de snacks et de boissons sucrées. L’idée est de préserver la santé des élèves, alors que l’obésité progresse chez les adolescents. L’école doit aussi jouer un rôle éducatif et décourager la consommation de sodas et de bonbons entre les cours.', 'Document 2 : Certains défendent le maintien des distributeurs dans les établissements scolaires. Selon eux, ces machines offrent des avantages concrets : elles proposent des boissons chaudes en hiver, évitent aux élèves de sortir acheter à manger et rendent service à ceux qui n’ont pas eu le temps de prendre un petit déjeuner.'] },
  ] } },
  { id: '2026-07-100', theme: 'La sévérité envers les enfants', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Vous apprenez qu’un(e) de vos proches va bientôt célébrer son anniversaire. Écrivez à vos amis pour leur proposer de participer ensemble à l’achat d’un présent commun.' },
    { prompt: 'La direction d’une école de musique recherche un lieu pour accueillir une fête destinée à 100 invités. Rédigez un courriel pour lui signaler que vous avez trouvé un local et préciser l’emplacement, les prix, les services proposés, etc.' },
    { prompt: T3('La sévérité envers les enfants.'), documents: ['Document 1 : Je vais avoir 22 ans et je vis toujours chez mes parents. Même si je suis majeure, ils restent très stricts avec moi. Quand j’étais adolescente et que je sortais avec mes amies, il m’était interdit de rentrer tard ou de dormir ailleurs. Aujourd’hui, les règles ont peu changé : je peux seulement veiller un peu plus longtemps, mais ma mère m’appelle sans cesse jusqu’à mon retour.', 'Document 2 : Certains parents redoutent d’être trop durs avec leurs enfants. Ils pensent qu’une autorité excessive peut freiner leur épanouissement et nuire à leur personnalité plus tard. Pourtant, tout accepter par amour peut aussi avoir des conséquences négatives à l’âge adulte. Pour vivre avec les autres, il faut apprendre à respecter des règles.'] },
  ] } },
  { id: '2026-07-101', theme: 'Le festival de cinéma', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Un festival consacré au cinéma aura lieu prochainement dans votre ville et vous aimeriez y aller. Écrivez à votre ami(e) pour l’inviter à vous accompagner, en précisant les renseignements utiles sur cet événement : programmation, jours et heures, prix des billets, etc.' },
    { prompt: 'Vous avez hébergé chez vous, pendant une semaine, un(e) étudiant(e) venu(e) de l’étranger. Pour votre blog, racontez cette expérience et dites pour quelles raisons elle vous a plu.' },
    { prompt: T3('Le festival de cinéma.'), documents: ['Document 1 : Les restaurants rapides se distinguent par leur volonté de proposer des repas variés et équilibrés, tout en respectant des règles d’hygiène très strictes. En laissant chaque client composer son menu, ils le rendent acteur de ses choix alimentaires, tout en répondant à ses goûts et à ses préférences.', 'Document 2 : Des spécialistes estiment qu’aller souvent dans des fast-foods est mauvais pour la santé. On y sert surtout les mêmes aliments : frites, hamburgers et sodas, très riches en calories. En plus, ces produits sont souvent emballés en plastique, ce qui augmente les déchets et abîme l’environnement.'] },
  ] } },
  { id: '2026-07-102', theme: 'La lecture pour les enfants', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Votre ami veut se mettre au sport. Écrivez-lui un message pour lui conseiller un club de sport près de chez vous, en donnant des informations précises : emplacement, prix, activités proposées, etc.' },
    { prompt: 'Vous avez pris part à une occasion importante dont vous gardez un souvenir fort, comme une fête d’anniversaire ou un mariage. Racontez cet événement en expliquant ce qui vous a le plus impressionné.' },
    { prompt: T3('La lecture pour les enfants.'), documents: ['Document 1 : Avec la technologie et les objets high-tech qui occupent de plus en plus notre quotidien, beaucoup d’enfants se détournent des livres au profit des jeux vidéo, du sport ou de la musique. Entre les réseaux sociaux et le gaming, ils lisent de moins en moins. Mieux vaut donc ne pas les obliger à lire : l’envie de lire doit venir d’eux-mêmes.', 'Document 2 : L’amour des livres se transmet souvent de génération en génération, même si les enfants ont aujourd’hui davantage de smartphones et de tablettes que de romans. Lire régulièrement aide à enrichir le langage, à améliorer l’attention et la concentration. Les parents peuvent aussi partager ce plaisir en lisant dix minutes par jour avec leurs enfants, ce qui renforce leur complicité.'] },
  ] } },
  { id: '2026-07-103', theme: 'Limiter les voitures dans les centres-villes', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Vous écrivez un message pour convier vos amis à une soirée de fin d’année.' },
    { prompt: 'Vous êtes parti au Canada avec une agence de voyages pour vos vacances. Rédigez un avis dans lequel vous racontez comment ce séjour s’est déroulé et ce que vous avez vécu.' },
    { prompt: T3('Limiter les voitures dans les centres-villes.'), documents: ['Document 1 : Face à des niveaux de pollution très inquiétants dans de nombreuses villes, certaines ont réussi à bannir les voitures du centre urbain. Oslo, la capitale norvégienne, a récemment adopté cette mesure et s’en dit satisfaite. À terme, les accidents devraient diminuer, la dépendance au pétrole reculer et l’air devenir plus sain.', 'Document 2 : Plusieurs villes lancent des projets pour interdire les voitures en centre-ville sans prévoir les équipements nécessaires. Réduire la circulation peut certes diminuer la pollution, mais il faut aussi organiser de grands parkings, renforcer les transports en commun et autoriser certains véhicules, notamment ceux de la police, des secours ou des livreurs.'] },
  ] } },
  { id: '2026-07-104', theme: 'Les animaux de compagnie pour les enfants, pour ou contre ?', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Un(e) ami(e) aimerait apprendre une langue dans votre établissement scolaire. Écrivez-lui pour l’aider à choisir en lui donnant des renseignements concrets : situation de l’école, coût, formules de cours, etc.' },
    { prompt: 'Vous faites du bénévolat dans une association au service des seniors. Rédigez un article de blog pour partager ce que vous y vivez et donner envie à d’autres de s’engager à leur tour.' },
    { prompt: T3('Les animaux de compagnie pour les enfants, pour ou contre ?'), documents: ['Document 1 : Offrir un animal de compagnie à un enfant a de nombreux bénéfices, comme le rappellent plusieurs psychologues. Pour un enfant sans frère ni sœur, l’animal devient un véritable compagnon et l’aide à ne pas se sentir seul. Il lui permet aussi de gagner en confiance, d’apprendre le respect et de devenir plus autonome en se sentant en sécurité à ses côtés.', 'Document 2 : Beaucoup d’enfants réclament un chien ou un chat à leurs parents. Pourtant, avant d’en adopter un, il faut bien réfléchir. Un animal devient un membre de la famille pour longtemps, demande de l’argent et implique une vraie responsabilité. On ne peut pas le considérer comme un jouet à abandonner quand l’enfant s’en lasse.'] },
  ] } },
  { id: '2026-07-105', theme: 'Les caméras de surveillance à l’école : utiles ou non ?', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Vous voulez célébrer votre anniversaire dans un restaurant. Rédigez un courriel à vos amis pour leur communiquer les informations importantes : adresse du lieu, date, heure, formule de repas et tarif, puis demandez-leur de vous répondre.' },
    { prompt: 'Vous avez quitté la ville pour vivre à la campagne. Sur un forum, expliquez les raisons de ce changement et décrivez les avantages de votre nouvelle vie. Votre message doit contenir entre 120 et 150 mots.' },
    { prompt: T3('Les caméras de surveillance à l’école : utiles ou non ?'), documents: ['Document 1 : À Montréal, dans l’école où j’enseigne, des caméras ont été installées dans de nombreux endroits. Elles rappellent aux élèves que tout acte violent peut être sanctionné. Cette mesure est bien acceptée par les parents, les professeurs et une grande partie des jeunes, car elle renforce le sentiment de sécurité. Seuls quelques élèves dénoncent une atteinte à leur vie privée.', 'Document 2 : Je suis opposé à l’installation de caméras dans les écoles montréalaises. Dans plusieurs pays, ce dispositif n’a pas donné de résultats convaincants. Comme les appareils sont visibles, il reste possible de contourner la surveillance. Pour améliorer la discipline, il vaut mieux renforcer le dialogue et faire respecter clairement le règlement intérieur.'] },
  ] } },
  { id: '2026-07-106', theme: 'L’uniforme à l’école : pour ou contre ?', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez faire du sport avec un(e) ami(e). Envoyez-lui un message pour présenter votre projet en précisant le type d’activités, le lieu et le matériel nécessaire.' },
    { prompt: 'Vous avez passé six mois dans une université à l’étranger. Écrivez à vos amis pour leur raconter cette expérience et expliquer ce que vous avez particulièrement apprécié. Votre message doit faire entre 120 et 150 mots.' },
    { prompt: T3('L’uniforme à l’école : pour ou contre ?'), documents: ['Document 1 : Les enfants sont très influencés par la mode, et les parents doivent souvent acheter de nouveaux vêtements. L’uniforme aide donc à réduire les dépenses. Il renforce aussi le sentiment d’appartenance à l’école et donne aux élèves une vraie fierté. Enfin, il atténue les différences sociales et limite les jugements liés à l’apparence.', 'Document 2 : Au Québec, de plus en plus d’écoles publiques choisissent l’uniforme, et cela ne plaît pas à tous les adolescents. Beaucoup le trouvent inconfortable, peu esthétique et trop chaud en été. Ils estiment aussi qu’une tenue imposée ne leur permet pas d’exprimer leur personnalité.'] },
  ] } },
  { id: '2026-07-107', theme: 'Les outils électroniques : pour ou contre ?', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Dans un message adressé à vos amis, vous les invitez à votre fête d’anniversaire du soir et vous expliquez de quelle manière vous comptez l’organiser.' },
    { prompt: 'Sur votre blog, racontez comment se sont passées vos études dans un autre pays.' },
    { prompt: T3('Les outils électroniques : pour ou contre ?'), documents: ['Document 1 : Les outils électroniques occupent une place importante dans notre quotidien. Avec le téléphone, l’ordinateur ou la tablette, on communique vite, on cherche des informations et on apprend plus facilement. Ils facilitent aussi les études en ligne et permettent d’accéder à de nombreuses ressources. En plus, ils font gagner du temps dans bien des situations.', 'Document 2 : Les outils électroniques ont aussi des effets négatifs. Lorsqu’ils sont utilisés sans modération, ils peuvent créer une dépendance et réduire les échanges avec la famille ou les amis. Ils entraînent parfois de la fatigue visuelle ou des problèmes de sommeil. Les élèves, eux, passent souvent trop de temps sur les jeux et les réseaux sociaux.'] },
  ] } },
  { id: '2026-07-108', theme: 'Le travail : favorable ou défavorable ?', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Le mois prochain, vous aimeriez partir deux jours avec vos amis. Écrivez-leur un message pour présenter votre idée de séjour : destination, moyen de transport, programme d’activités, etc.' },
    { prompt: 'COURRIER DES LECTEURS Tout quitter pour partir en voyage pendant un an : bonne ou mauvaise idée ? Répondez sur notre site Internet « voyage.internaute.fr » en donnant votre opinion et en vous appuyant sur des exemples personnels.' },
    { prompt: T3('Le travail : favorable ou défavorable ?'), documents: ['Document 1 : Le travail prend une place centrale dans nos vies. Dès l’enfance, on nous demande souvent ce que nous voulons devenir plus tard. Pourtant, il est fréquemment associé à la fatigue, à la contrainte et à un manque de liberté. Beaucoup estiment aussi que l’on consacre trop peu de temps à sa famille et à ses amis. Il faudrait donc repenser la place du travail et envisager de travailler moins pour vivre mieux.', 'Document 2 : Certaines personnes choisissent d’arrêter de travailler pour changer de vie. Pourtant, le travail reste essentiel pour exister socialement. La question « Qu’est-ce que tu fais dans la vie ? » revient souvent lors d’une rencontre, car l’emploi participe à notre identité. Selon Jean-Daniel Remond, l’entreprise apporte des contacts, un réseau, un sentiment d’utilité et des difficultés qui construisent la personnalité.'] },
  ] } },
  { id: '2026-07-109', theme: 'La livraison des repas au bureau : pour ou contre ?', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Votre ami(e) aimerait visiter la région où vous vivez. Écrivez-lui un message pour lui suggérer plusieurs endroits intéressants à découvrir.' },
    { prompt: 'Pour votre blog, racontez votre récente séance dans un centre sportif de votre ville et partagez ce que vous pensez de cet endroit.' },
    { prompt: T3('La livraison des repas au bureau : pour ou contre ?'), documents: ['Document 1 : Commander un repas livré au bureau permet de gagner du temps, car on peut rester sur place pendant la pause déjeuner et terminer plus tôt sa journée. Chacun peut aussi choisir exactement ce qu’il souhaite manger, sans contrainte. Enfin, ce service est très pratique, puisque certains restaurants livrent à toute heure.', 'Document 2 : Ce système a aussi ses inconvénients. Lorsque les commandes se multiplient, les livreurs peuvent être débordés, ce qui provoque des retards et du stress. Pour les salariés, déjeuner devant son écran sans vraie pause risque aussi d’augmenter la fatigue. Il vaut mieux s’accorder un court moment de repos pour rester performant.'] },
  ] } },
  { id: '2026-07-110', theme: 'La restauration rapide', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Envoyez un message électronique à vos amis pour les convier à la fête d’anniversaire surprise de votre meilleur ami. Précisez les informations pratiques comme l’endroit, le jour et l’heure.' },
    { prompt: 'Après avoir pris part à une réunion familiale, écrivez à vos amis pour raconter ce moment et dire ce qui vous a plu davantage.' },
    { prompt: T3('La restauration rapide.'), documents: ['Document 1 : Les fast-foods sont souvent accusés de nuire à la santé, car ils servent surtout des plats très caloriques comme des hamburgers, des frites et des boissons sucrées. En plus, ces repas sont fréquemment emballés dans du plastique, ce qui augmente les déchets et aggrave la pollution de l’environnement.', 'Document 2 : Plutôt que de condamner la restauration rapide, il faut reconnaître son côté pratique. On y trouve un repas chaud en quelques minutes, ce qui est précieux quand on manque de temps. Ces restaurants, très répandus, offrent aussi des conditions d’hygiène généralement satisfaisantes.'] },
  ] } },
  { id: '2026-07-111', theme: 'L’aide aux personnes pauvres', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Vous annoncez à votre amie francophone que vous venez d’être embauché(e). Dans votre message, présentez votre emploi, l’équipe avec qui vous travaillez et l’endroit où vous exercez.' },
    { prompt: 'Une étudiante de 19 ans souhaite partir à l’étranger pour étudier. Sur un forum, elle demande des témoignages. Racontez-lui votre année à l’étranger et les activités que vous y avez faites.' },
    { prompt: T3('L’aide aux personnes pauvres.'), documents: ['Document 1 : Marie, 58 ans : Depuis longtemps, je consacre un peu de mon temps et de mon argent aux personnes dans une grande précarité, surtout aux sans-abri pendant l’hiver. Pour moi, aider les autres est un devoir. Soutenir les pauvres ou les associations, c’est aussi une façon de se sentir utile dans une société de plus en plus dure.', 'Document 2 : Paul, 63 ans : Pour venir en aide aux personnes en difficulté, il faut surtout s’engager davantage dans des associations. C’est mon cas : je suis bénévole dans un organisme de mon quartier qui aide les sans-abri à trouver un logement et un emploi. À long terme, cette démarche les rend plus autonomes.'] },
  ] } },
  { id: '2026-07-112', theme: 'Le vélo en ville', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Rédigez un message à votre ami(e) pour présenter le déroulement de vos prochaines vacances en indiquant la destination, la période et les activités prévues.' },
    { prompt: 'Sur votre blog, racontez un évènement récent auquel vous avez assisté, par exemple un festival, une célébration ou une cérémonie.' },
    { prompt: T3('Le vélo en ville.'), documents: ['Document 1 : On associe souvent le vélo au sport ou aux loisirs, alors qu’il sert aussi à se déplacer, pour les trajets personnels comme professionnels. En ville, il permet d’aller vite et d’éviter les embouteillages. C’est une solution agréable qui permet de faire du sport tout en se rendant au travail.', 'Document 2 : Se déplacer à vélo en ville peut être dangereux. Entre la circulation dense, le non-respect du Code de la route et le manque de pistes cyclables, le risque d’accident est réel. À cela s’ajoutent les gaz d’échappement, mauvais pour la santé. Le vélo urbain n’est donc pas sans danger.'] },
  ] } },
  { id: '2026-07-113', theme: 'La gratuité des transports en commun : pour ou contre ?', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Près de votre domicile, un établissement de restauration vient d’être lancé. Écrivez à un(e) ami(e) pour l’inviter à vous y accompagner et décrivez-lui ce lieu : spécialités, tarifs, ambiance, décoration, etc.' },
    { prompt: 'Sur un forum en ligne, racontez comment vous avez vécu l’apprentissage d’une langue étrangère en partageant votre parcours et votre expérience personnelle.' },
    { prompt: T3('La gratuité des transports en commun : pour ou contre ?'), documents: ['Document 1 : Rendre les transports en commun gratuits est une excellente mesure. Cela incite les habitants à laisser leur voiture, ce qui réduit les bouchons et la pollution. Dans ma ville, cette décision a augmenté la fréquentation des transports publics. Elle a aussi aidé les commerces du centre, plus fréquenté qu’auparavant.', 'Document 2 : Cette idée coûterait trop cher aux villes, qui ont déjà d’autres priorités. À Toulouse, par exemple, il faudrait d’abord réaménager les espaces verts. Il serait aussi plus utile d’améliorer le réseau que de le rendre gratuit, car certains quartiers sont encore mal desservis. Enfin, un service payant est souvent mieux respecté.'] },
  ] } },
  { id: '2026-07-114', theme: 'Les animaux de compagnie au travail', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Près de chez vous, un restaurant a récemment commencé son activité. Dans un message à un(e) ami(e), proposez une sortie ensemble et présentez les caractéristiques du lieu : type de plats, coût, cadre, décoration, etc.' },
    { prompt: 'Vous avez pris part à un tournoi sportif. Rédigez un article pour un blog ou un magazine en donnant des informations sur le lieu, la date et l’organisation de cet évènement.' },
    { prompt: T3('Les animaux de compagnie au travail.'), documents: ['Document 1 : Amener son animal de compagnie au bureau est devenu tendance. Cela aide surtout à réduire le stress des salariés. Un chien ou un chat rend l’ambiance plus détendue et limite les tensions entre collègues. Selon une enquête, un quart des employés pensent même que cela les motive davantage au travail.', 'Document 2 : Dans mon entreprise, certains viennent avec leur chat ou leur chien, mais cela ne me plaît pas. Les animaux peuvent être imprévisibles, et cela pose aussi des problèmes de santé, notamment pour les personnes allergiques. Sans compter que leur présence distrait les employés et ne favorise pas la productivité. Iris, 34 ans'] },
  ] } },
  { id: '2026-07-115', theme: 'La restauration rapide', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Cédric va s’occuper de votre maison et de votre jardin pendant votre absence. Écrivez-lui un message pour expliquer clairement les tâches à faire.' },
    { prompt: 'À la suite d’un séjour mal préparé, vous adressez une plainte à une agence de voyages au sujet de services insatisfaisants. Faites part clairement de votre mécontentement.' },
    { prompt: T3('La restauration rapide.'), documents: ['Document 1 : Les restaurants rapides misent sur une offre variée et des plats plutôt équilibrés, tout en respectant des règles d’hygiène strictes. En plus, le client peut choisir lui-même la composition de son repas, ce qui lui laisse une grande liberté et l’encourage à faire ses propres choix alimentaires selon ses goûts.', 'Document 2 : Selon les spécialistes, aller souvent dans un fast-food nuit à la santé. On y sert presque toujours les mêmes produits, comme des frites, des hamburgers et des sodas, très riches en calories. En outre, beaucoup d’emballages sont en plastique, ce qui favorise les déchets et pollue l’environnement.'] },
  ] } },
  { id: '2026-07-116', theme: 'Les achats en ligne', created_at: '2026-07-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 7, source: 'candidats', tasks: [
    { prompt: 'Un rendez-vous sportif va bientôt se tenir dans votre ville. Envoyez un message à vos amis pour leur proposer d’y assister, en précisant la date, l’endroit et les modalités d’inscription.' },
    { prompt: 'Rédigez pour votre blog un texte sur le cours de cuisine que vous avez suivi, en racontant cette expérience et en donnant des précisions.' },
    { prompt: T3('Les achats en ligne.'), documents: ['Document 1 : Acheter sur Internet fait gagner du temps, car on trouve rapidement ce que l’on cherche, à n’importe quelle heure. Les produits sont accessibles en permanence et les clients peuvent commander facilement depuis chez eux, ce qui simplifie beaucoup leurs achats au quotidien.', 'Document 2 : Les magasins physiques offrent un contact direct avec les vendeurs et permettent de voir, de toucher et de comparer les articles avant d’acheter. Ils laissent aussi la possibilité d’échanger plus simplement un produit qui ne convient pas et favorisent les discussions avec le personnel.'] },
  ] } },
  { id: '2026-06-100', theme: 'Les produits faits maison : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Un ami vous a dit avoir découvert une salle de sport superbe et souhaite en savoir davantage. Rédigez-lui un message pour lui donner des détails sur cet endroit.' },
    { prompt: 'Sur un forum, un débat porte sur les formations en ligne. Vous devez écrire un message pour raconter votre propre expérience, qu’il s’agisse d’un cours de langue, d’une formation professionnelle ou d’un autre apprentissage à distance, puis dire ce que vous avez apprécié et ce qui vous a moins plu.' },
    { prompt: T3('Les produits faits maison : pour ou contre ?'), documents: ['Document 1 : Préparer soi-même des produits biologiques à la maison permet de choisir exactement les ingrédients et d’obtenir des formules plus saines, adaptées à ses besoins. C’est aussi une bonne façon de limiter les emballages jetables, donc de produire moins de déchets. À long terme, cette pratique peut faire économiser de l’argent tout en développant des gestes plus créatifs et plus responsables.', 'Document 2 : Faire ses produits à domicile n’est pas sans inconvénients. Une mauvaise préparation peut rendre le produit inefficace ou irritant. Il faut aussi investir du temps pour réunir les ingrédients et les travailler. Sans oublier les questions de conservation, de sécurité et le risque de contamination. Le coût de départ peut également être élevé.'] },
  ] } },
  { id: '2026-06-101', theme: 'Les écoles privées ou publiques ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'France Télévisions prépare un sujet consacré au sport amateur. Présentez le type de sportif que vous êtes en envoyant votre témoignage sur francetelevision.fr.' },
    { prompt: 'Vous revenez d’un séjour dans une magnifique région de votre pays. Dans un message à vos amis, racontez ce que vous avez vécu et expliquez les raisons pour lesquelles ces vacances vous ont tant plu.' },
    { prompt: T3('Les écoles privées ou publiques ?'), documents: ['Document 1 : À chaque rentrée, les écoles privées attirent davantage d’élèves en France. Leur succès ne vient pas seulement des résultats scolaires, mais surtout de leur image. Beaucoup de parents les jugent plus encadrées, plus surveillées et plus rassurantes, notamment parce que les classes y sont souvent composées d’élèves de milieux favorisés. Les frais de scolarité expliquent aussi cette sélection.', 'Document 2 : Les collèges privés accueillent peu d’élèves issus de familles modestes, car leur accès est payant. Cette situation limite la rencontre entre jeunes de milieux différents et nuit à la mixité sociale. En séparant ainsi les élèves, le système scolaire entretient les inégalités et peut accentuer le sentiment d’exclusion chez certains adolescents.'] },
  ] } },
  { id: '2026-06-102', theme: 'Les devoirs à la maison', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous avez reçu un colis commandé sur Internet, mais l’objet est arrivé cassé. Écrivez un courriel au service client pour signaler le problème, décrire les dégâts et indiquer la solution que vous attendez.' },
    { prompt: 'Écrivez pour votre blog un article sur votre visite à une exposition consacrée à votre artiste favori. Décrivez les œuvres observées et exprimez vos impressions.' },
    { prompt: T3('Les devoirs à la maison.'), documents: ['Document 1 : D’après des associations de parents d’élèves, les devoirs à la maison aident les enfants à apprendre à mieux gérer leur temps et à devenir plus autonomes. Pour les familles, ils créent aussi un lien régulier avec l’école. Même si ce suivi peut être fatigant après le travail, beaucoup de parents apprécient ce moment partagé avec leurs enfants.', 'Document 2 : Nous sommes opposés aux devoirs à la maison depuis longtemps. Leur utilité n’a jamais été démontrée pour améliorer les résultats. De plus, tous les parents n’ont ni le temps ni les compétences pour aider leurs enfants. Les élèves qui ont compris en classe perdent du temps, tandis que les autres restent pénalisés chez eux. Il faut donc les supprimer.'] },
  ] } },
  { id: '2026-06-103', theme: 'Les nouvelles technologies à l’école : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous écrivez à un(e) ami(e) après avoir passé quelques jours à la campagne. Dans votre message, racontez le déroulement de ce séjour et ce que vous y avez vécu.' },
    { prompt: 'La direction cherche une salle pouvant accueillir 100 invités pour la fête de fin d’année. Rédigez un message pour proposer un lieu qui convient parfaitement en précisant l’emplacement, les prix et les services disponibles.' },
    { prompt: T3('Les nouvelles technologies à l’école : pour ou contre ?'), documents: ['Document 1 : Jean pense que les technologies doivent occuper une place importante à l’école afin de préparer les élèves au monde numérique. Selon lui, les tablettes et les ordinateurs rendent les cours plus vivants, donnent accès à de nombreuses ressources et encouragent à la fois la créativité et l’autonomie des élèves.', 'Document 2 : Sara estime au contraire que l’usage excessif des technologies en classe pose problème. À ses yeux, il risque de réduire les échanges humains et de créer une dépendance aux écrans. Elle considère que l’enseignement traditionnel et le contact direct entre professeurs et élèves restent essentiels pour former les jeunes de manière équilibrée.'] },
  ] } },
  { id: '2026-06-104', theme: 'Les publicités : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous envoyez un message à un(e) ami(e) après votre arrivée dans une nouvelle ville. Présentez le lieu où vous vivez désormais en parlant du quartier, des habitants autour de vous, des commerces et de l’ambiance générale.' },
    { prompt: 'Vous avez participé à une opération de nettoyage lors de la Journée mondiale du nettoyage de notre planète. Avec d’autres personnes, vous avez ramassé des déchets dans un lieu public. Racontez cette expérience à vos amis et expliquez pourquoi ce type d’action est important.' },
    { prompt: T3('Les publicités : pour ou contre ?'), documents: ['Document 1 : Beaucoup de personnes trouvent la publicité fatigante, mais je la considère utile pour les commerces et les entreprises. Elle sert à faire connaître un produit ou un service, et certaines annonces sont même amusantes. En voiture, j’aime parfois les écouter. Elles m’informent aussi des nouveautés et des promotions, ce qui me permet de comparer et d’économiser. Quentin, 28 ans', 'Document 2 : La publicité envahit notre quotidien, que ce soit dans les journaux, à la radio, à la télévision, sur Internet ou sur nos téléphones. À la télévision, elle interrompt souvent les programmes, ce qui agace. De plus, les prospectus déposés en grande quantité dans les boîtes aux lettres nuisent à l’environnement. Il faudrait donc limiter ces pratiques par une loi. Estelle, 35 ans'] },
  ] } },
  { id: '2026-06-105', theme: 'Les vols à bas prix', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous préparez une fête surprise pour l’anniversaire de votre meilleur(e) ami(e). Rédigez un courriel à vos amis pour les convier, en donnant les informations pratiques comme l’endroit, le jour et l’heure.' },
    { prompt: 'Sur votre blog, racontez votre expérience dans une brocante organisée dans votre ville. Expliquez ce que vous y avez fait, entre achats et ventes d’objets d’occasion, et dites pour quelles raisons cette activité vous a plu.' },
    { prompt: T3('Les vols à bas prix.'), documents: ['Document 1 : Je prends souvent l’avion avec des compagnies low-cost, car leurs tarifs sont bien plus avantageux que ceux des compagnies classiques. Parfois, cela revient même moins cher qu’un trajet en voiture ou en train. En revanche, il faut accepter l’absence de services à bord : pas de repas ni de boissons. À mon avis, ce type de vol convient mal aux longs trajets.', 'Document 2 : J’ai décidé de ne plus choisir les compagnies aériennes à bas prix. Après avoir réfléchi, j’ai compris que le confort était insuffisant, que les conditions de travail du personnel étaient difficiles et que certains avions semblaient trop anciens, ce qui m’inquiète pour la sécurité. Désormais, pour certains déplacements, je préfère la voiture ou le train, qui permet aussi d’admirer de beaux paysages.'] },
  ] } },
  { id: '2026-06-106', theme: 'Les cours de langue en ligne', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Un ami, Ali, vous écrit pour savoir comment se passe votre nouveau travail et si vous vous y sentez bien. Répondez-lui en décrivant votre poste, votre lieu de travail, vos collègues et vos impressions.' },
    { prompt: 'Un site d’informations familiales recherche des témoignages sur la vie avec une personne âgée. Racontez l’expérience que vous avez vécue avec elle.' },
    { prompt: T3('Les cours de langue en ligne.'), documents: ['Document 1 : Apprendre une langue sur Internet est tout à fait possible et donne souvent de bons résultats. L’avantage principal est la liberté : on étudie quand on veut, car les leçons restent accessibles en permanence. On évite aussi les déplacements. Depuis chez soi, au bureau ou dans un café, on peut travailler tout en faisant des économies.', 'Document 2 : L’apprentissage en ligne paraît simple, mais il ne convient pas à tout le monde. Il faut d’abord disposer d’une bonne connexion et d’un appareil adapté. Ensuite, il faut beaucoup d’autonomie pour travailler seul, sans professeur ni camarades. Sans encadrement, certains perdent vite leur motivation et finissent par abandonner.'] },
  ] } },
  { id: '2026-06-107', theme: 'Que pensez-vous des maisons de retraite ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Thomas vous a écrit pour en savoir plus sur une grande fête de votre pays. Répondez-lui en présentant une célébration importante et en expliquant ses traditions.' },
    { prompt: 'Vous avez assisté à un festival de cinéma et vu plusieurs films. Sur votre site personnel, racontez quel film vous avez préféré et justifiez votre choix.' },
    { prompt: T3('Que pensez-vous des maisons de retraite ?'), documents: ['Document 1 : Dans mon pays, les maisons de retraite sont rares. Lorsqu’une personne âgée ne peut plus vivre seule, elle reste généralement auprès des plus jeunes de la famille, et cela se passe sans grandes difficultés. Il nous semble même surprenant de confier nos parents ou nos grands-parents à des inconnus.', 'Document 2 : Beaucoup critiquent les maisons de retraite, mais elles peuvent être très utiles. Elles permettent d’éviter l’isolement, car les résidents vivent avec des personnes du même âge. Elles offrent aussi des soins médicaux et rassurent les familles. Le seul vrai problème reste leur coût, souvent trop élevé pour certains ménages.'] },
  ] } },
  { id: '2026-06-108', theme: 'La chasse aux animaux : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez proposer à votre ami(e) de venir passer les vacances chez vous. Rédigez un message pour l’inviter et présentez les lieux intéressants ainsi que les sites à découvrir dans votre ville.' },
    { prompt: 'Vous avez participé à un concours sur le thème « Mon artiste préféré » pour gagner un séjour de deux semaines dans votre ville préférée. Rédigez un article de blog pour présenter votre artiste favori.' },
    { prompt: T3('La chasse aux animaux : pour ou contre ?'), documents: ['Document 1 : À mes yeux, il est incompréhensible d’éprouver du plaisir en ôtant la vie à des bêtes. De la même manière, affirmer qu’on aime le monde naturel tout en participant à sa destruction me paraît profondément contradictoire. Je partage donc entièrement cette opinion, car elle dénonce une attitude incohérente et choquante.', 'Document 2 : La chasse répond à plusieurs objectifs : se nourrir, commercer, gérer et préserver la faune, protéger les biens, s’entraîner, se divertir ou encore gagner en prestige. Ces motivations sont différentes, mais elles expliquent pourquoi cette pratique existe encore aujourd’hui.'] },
  ] } },
  { id: '2026-06-109', theme: 'Les produits faits maison : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Un ami vous dit qu’il fréquente une salle de sport magnifique et veut en savoir plus. Répondez-lui par message au sujet de cette salle.' },
    { prompt: 'Sur un forum, vous avez lu un débat sur les formations en ligne. Décrivez votre expérience, qu’il s’agisse d’un cours de langue ou d’une formation professionnelle, puis dites ce que vous avez aimé et ce que vous avez moins apprécié.' },
    { prompt: T3('Les produits faits maison : pour ou contre ?'), documents: ['Document 1 : Préparer soi-même ses produits biologiques permet de contrôler entièrement les ingrédients et d’obtenir des solutions plus saines, adaptées à ses besoins. C’est aussi un bon moyen de réduire les déchets plastiques grâce à des contenants réutilisables. À long terme, on fait des économies tout en développant sa créativité et un mode de vie plus durable.', 'Document 2 : Fabriquer des produits biologiques à la maison présente aussi des inconvénients. Une mauvaise préparation peut donner un résultat inefficace ou irritant. Il faut par ailleurs du temps pour choisir et préparer les ingrédients. Sans bonne conservation, la sécurité n’est pas garantie et le risque de contamination augmente. Enfin, le coût de départ peut être élevé.'] },
  ] } },
  { id: '2026-06-110', theme: 'Livraison des repas au bureau : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Dans un message à votre ami(e), conseillez-lui plusieurs endroits à voir dans la région où vous habitez, puisqu’il ou elle souhaite la visiter.' },
    { prompt: 'Vous avez suivi un cours de sport dans une salle. Écrivez un billet sur votre blog pour raconter cette séance et donner aussi votre opinion sur cet établissement.' },
    { prompt: T3('Livraison des repas au bureau : pour ou contre ?'), documents: ['Document 1 : Commander les repas directement au bureau fait gagner un temps précieux. Plus besoin de chercher un restaurant loin du travail : on économise de l’argent et de l’énergie, tout en restant plus efficace. Le repas peut même être livré sans interrompre une réunion ou une conférence. C’est une solution idéale pour les entreprises très actives.', 'Document 2 : Ce service présente aussi des défauts. Quand les commandes se multiplient, les livreurs prennent du retard et l’attente devient stressante. De leur côté, les salariés restent trop longtemps devant leur écran et se fatiguent davantage. Il vaut mieux prévoir de vraies pauses, même pendant les périodes de travail intense.'] },
  ] } },
  { id: '2026-06-111', theme: 'Caméras de surveillance : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous allez vous installer à Nice, en France. Rédigez un message pour un site d’agence immobilière en précisant vos critères de logement : surface, budget, nombre de pièces, et autres informations utiles.' },
    { prompt: 'Vous venez d’entrer dans une école de langues. Écrivez à vos amis pour raconter le déroulement de votre première semaine et donner votre avis sur l’établissement ainsi que sur les cours.' },
    { prompt: T3('Caméras de surveillance : pour ou contre ?'), documents: ['Document 1 : Dans les villes, les caméras de surveillance sont de plus en plus nombreuses. Beaucoup de Français y voient un moyen de se sentir plus en sécurité : selon un sondage, 75 % soutiennent leur développement. Ils acceptent d’être filmés dans les lieux publics comme les rues, les commerces ou les transports, mais refusent la surveillance par l’employeur.', 'Document 2 : Plusieurs études soulignent que la vidéosurveillance coûte cher et reste peu efficace. Les caméras se repèrent facilement, ce qui limite leur utilité contre les vols, la drogue ou la violence. En plus, leur exploitation demande beaucoup de moyens humains : une recherche allemande indique qu’il faut sept personnes pour analyser les images d’une seule caméra.'] },
  ] } },
  { id: '2026-06-112', theme: 'Jeux vidéo : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Votre anniversaire approche et vos amis vous demandent ce qui vous ferait plaisir. Vous aimeriez recevoir des vêtements : écrivez-leur un message en décrivant précisément ceux que vous souhaitez.' },
    { prompt: 'Vous avez vu une annonce sur le site « www.manger-international.com » qui cherche des témoignages sur les habitudes alimentaires à travers le monde. Rédigez un article pour les lecteurs de ce site afin de présenter la manière de manger dans votre pays, puis indiquez les pratiques que vous appréciez ou que vous aimez moins, en expliquant pourquoi.' },
    { prompt: T3('Jeux vidéo : pour ou contre ?'), documents: ['Document 1 : Les jeux vidéo, qu’ils soient sur console ou sur ordinateur, à la maison, en salle, seul ou en ligne, peuvent entraîner une dépendance chez certaines personnes. On parle d’addiction lorsqu’ils deviennent l’intérêt principal, voire unique, au détriment des études, du travail, des relations ou du sport. Ce problème est particulièrement inquiétant à l’adolescence.', 'Document 2 : On entend souvent que les jeux vidéo rendent moins intelligents, mais les recherches disent le contraire. Certaines montrent qu’ils améliorent l’orientation, la mémoire et la précision des gestes, notamment avec les jeux de course. D’autres prouvent qu’ils développent la rapidité et la concentration. Même pour les personnes âgées, certains jeux servent à entretenir la mémoire et la vivacité d’esprit.'] },
  ] } },
  { id: '2026-06-113', theme: 'Les parcs zoologiques : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Un mois après votre installation, vous écrivez un courriel à votre ami Léo pour lui raconter votre nouvelle vie. Parlez de votre logement, de votre quartier, de la ville où vous habitez maintenant et des activités que vous y pratiquez.' },
    { prompt: 'Sur votre blog, racontez une fête traditionnelle à laquelle vous avez assisté, dans votre pays ou ailleurs, et expliquez ce qui vous a plu dans cet événement.' },
    { prompt: T3('Les parcs zoologiques : pour ou contre ?'), documents: ['Document 1 : Il ne faut pas enfermer les animaux sauvages dans les zoos, car ils ne vivent pas dans leur milieu naturel. Pour eux, c’est comme une prison. On peut même voir des ours polaires dans des enclos où il fait 15 degrés. Les animaux ont besoin de liberté et d’un environnement naturel.', 'Document 2 : Les zoos offrent aussi des avantages importants. Ils prennent soin des animaux, y compris de certaines espèces menacées. Les recherches montrent que les naissances y sont plus nombreuses, et que ces lieux peuvent contribuer à sauver des vies animales.'] },
  ] } },
  { id: '2026-06-114', theme: 'La lecture pour les enfants', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Votre ami veut commencer une activité sportive. Rédigez-lui un message pour lui conseiller une salle de sport dans votre quartier, en précisant son emplacement, ses prix, les activités proposées, etc.' },
    { prompt: 'Racontez un évènement important auquel vous avez pris part, comme un anniversaire ou un mariage, en décrivant le souvenir qui vous a le plus marqué.' },
    { prompt: T3('La lecture pour les enfants.'), documents: ['Document 1 : Avec les technologies modernes et les appareils numériques omniprésents, beaucoup d’enfants délaissent les livres au profit des jeux vidéo, des réseaux sociaux, de la musique ou du sport. Dans ce contexte, pourquoi leur imposer la lecture ? Comme le dit le proverbe, « le goût de la lecture ne s’impose pas » : il vaut mieux laisser l’enfant choisir ses lectures.', 'Document 2 : Même si les écrans occupent aujourd’hui beaucoup de place, la lecture reste essentielle et se transmet de génération en génération. Lire régulièrement aide l’enfant à mieux maîtriser la langue, à renforcer sa concentration et son écoute. Les parents peuvent aussi partager dix minutes de lecture par jour avec leur enfant pour créer un moment de complicité.'] },
  ] } },
  { id: '2026-06-115', theme: 'Vivre en colocation', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Votre ami Mehdi vient d’emménager dans votre ville et souhaite se renseigner sur les transports disponibles. Rédigez-lui un message pour lui expliquer les différents moyens de transport, les abonnements possibles et les tarifs.' },
    { prompt: 'Rédigez un article de blog dans lequel vous exprimez votre admiration pour une personnalité, célèbre ou non. Appuyez-vous sur des actions précises pour montrer ce qu’elle a accompli et expliquez pourquoi cette personne vous inspire.' },
    { prompt: T3('Vivre en colocation.'), documents: ['Document 1 : La colocation présente plusieurs atouts. Elle permet d’alléger les frais du quotidien, comme le loyer, les charges ou les dépenses courantes. Elle crée aussi un cadre convivial, propice aux échanges et aux rencontres. Partager un appartement avec d’autres personnes offre l’occasion de découvrir des cultures différentes et de tisser des liens durables.', 'Document 2 : Pourtant, vivre à plusieurs n’est pas toujours simple. Les habitudes et les caractères peuvent provoquer des désaccords, surtout pour le partage des tâches. L’absence d’espace personnel peut également peser. Pour que la cohabitation se passe bien, il faut dialoguer clairement et établir des règles communes dès le début.'] },
  ] } },
  { id: '2026-06-116', theme: 'Cuisinier amateur ou professionnel ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Votre ami Cédric a reçu votre invitation à votre mariage au Château de Chombony, mais il ne sait pas où se trouve ce lieu ni à quoi il ressemble. Écrivez-lui pour lui présenter ce château, sa situation et les moyens d’y aller.' },
    { prompt: 'Sur votre blog ou sur un forum internet, racontez votre expérience de l’apprentissage d’une langue étrangère.' },
    { prompt: T3('Cuisinier amateur ou professionnel ?'), documents: ['Document 1 : Les passionnés de cuisine réussissent parfois de très bonnes recettes, mais le talent seul ne suffit pas. Sans méthode ni savoir-faire, il est difficile d’atteindre un vrai niveau professionnel. Pour exercer ce métier, une formation solide et de l’expérience restent indispensables.', 'Document 2 : L’auteur s’intéresse à ces cuisiniers autodidactes qui ont appris grâce à Internet et sont devenus populaires sur les réseaux sociaux. Il évoque aussi le parcours d’une passionnée passée du statut d’amatrice à celui de professionnelle, qui a ensuite écrit plusieurs ouvrages destinés aux cuisiniers du quotidien.'] },
  ] } },
  { id: '2026-06-117', theme: 'Le grossissement des villes', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous pratiquez un sport dans un club et vous avez gagné récemment une compétition. Écrivez un courriel à vos amis pour raconter cette épreuve sportive et annoncer votre victoire.' },
    { prompt: 'Le site « colocation.com » recueille des témoignages sur la vie en colocation. Vous avez déjà vécu avec des amis ; partagez votre expérience avec les internautes et dites ce que vous pensez de ce mode de logement.' },
    { prompt: T3('Le grossissement des villes.'), documents: ['Document 1 : Aujourd’hui, les villes ne cessent de s’étendre, et cela nuit fortement à l’environnement. Plus elles grandissent, plus les conséquences sur la nature, puis sur l’être humain, deviennent importantes. La déforestation en est l’exemple le plus frappant : en supprimant les espaces verts pour construire des routes ou des immeubles, on réduit aussi la capacité de la planète à absorber le carbone.', 'Document 2 : La majorité de la population mondiale vit désormais en ville, et dans les pays développés, cette proportion est encore plus élevée. La question urbaine est donc essentielle sur le plan écologique. Même si l’on critique souvent les villes comme étant peu respectueuses de l’environnement, il faut nuancer : un citadin consomme parfois moins d’énergie qu’une personne vivant à la campagne.'] },
  ] } },
  { id: '2026-06-118', theme: 'Vivre chez ses parents, pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous partez en voyage et vous laissez votre appartement à un ami qui souhaite y séjourner pendant vos vacances. Envoyez-lui un message pour lui présenter le logement, l’immeuble et les conditions d’accès.' },
    { prompt: 'Sur votre blog, racontez le voyage dont vous gardez le meilleur souvenir.' },
    { prompt: T3('Vivre chez ses parents, pour ou contre ?'), documents: ['Document 1 : Vivre chez ses parents pendant ses études comporte de nombreux avantages. Cela permet d’économiser le loyer et les frais de nourriture, tout en profitant d’un cadre rassurant, de repas préparés à la maison et d’un logement entretenu. Certains jeunes peuvent ainsi mettre leur argent de côté pour leurs projets et éviter l’isolement. Des témoignages montrent aussi que le coût d’un logement loin du domicile est souvent trop élevé.', 'Document 2 : En revanche, cette solution limite l’autonomie. Quand les parents décident de tout, les jeunes ont moins de liberté et peuvent avoir l’impression de stagner. Un homme de 25 ans explique qu’après avoir perdu son emploi, il a dû retourner chez ses parents et a perdu son intimité. Pour lui, ce retour représente une régression.'] },
  ] } },
  { id: '2026-06-119', theme: 'Le vélo en ville, pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Écrivez à votre ami pour lui présenter le programme de vos prochaines vacances.' },
    { prompt: 'Rédigez un article de blog sur une manifestation récente à laquelle vous avez assisté, comme une fête ou un festival.' },
    { prompt: T3('Le vélo en ville, pour ou contre ?'), documents: ['Document 1 : On associe souvent le vélo au sport ou aux loisirs, alors qu’il s’agit aussi d’un moyen de transport très pratique. En ville, il permet de gagner du temps, d’éviter les bouchons et de se déplacer sans stress. C’est également une façon simple de faire de l’exercice tout en allant travailler.', 'Document 2 : Circuler à vélo en milieu urbain comporte pourtant des dangers. La circulation dense, le non-respect du code de la route et le manque d’aménagements adaptés augmentent les risques d’accident. À cela s’ajoute l’exposition aux gaz d’échappement, notamment au monoxyde de carbone, qui peut nuire à la santé.'] },
  ] } },
  { id: '2026-06-120', theme: 'L’uniforme scolaire : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous écrivez à un(e) ami(e) pour lui proposer de faire du sport avec vous. Présentez votre idée en donnant des précisions sur les activités prévues, l’endroit et le matériel nécessaire.' },
    { prompt: 'Vous avez passé six mois dans une université hors de votre pays. Vous écrivez à vos amis pour raconter cette période et expliquer ce que vous avez particulièrement apprécié. Écrivez un texte de 120 à 150 mots.' },
    { prompt: T3('L’uniforme scolaire : pour ou contre ?'), documents: ['Document 1 : L’uniforme aide les parents à faire des économies, car les enfants suivent moins les effets de la mode. Il crée aussi un fort sentiment d’appartenance à l’école et renforce la fierté des élèves. Enfin, une tenue commune atténue les écarts sociaux et limite les jugements liés aux vêtements.', 'Document 2 : Au Québec, même les écoles publiques choisissent de plus en plus l’uniforme. Pourtant, beaucoup d’adolescents le vivent mal : ils le trouvent peu confortable, peu esthétique et trop chaud en été. Ils regrettent aussi de ne pas pouvoir affirmer leur personnalité à travers leurs vêtements.'] },
  ] } },
  { id: '2026-06-121', theme: 'La restauration rapide : atout ou menace ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Pendant votre absence, votre ami Cédric s’est proposé pour s’occuper de votre maison et de votre jardin. Écrivez-lui un message pour lui expliquer les tâches à faire.' },
    { prompt: 'Après un voyage mal organisé, vous souhaitez porter réclamation contre une agence de voyages dont les services vous ont déçu. Exprimez clairement votre mécontentement.' },
    { prompt: T3('La restauration rapide : atout ou menace ?'), documents: ['Document 1 : Les restaurants rapides proposent des plats variés, équilibrés et préparés dans le respect des règles d’hygiène. Ils laissent aussi aux clients la possibilité de composer leur repas selon leurs goûts. Cette liberté rend chacun plus responsable de ses choix alimentaires tout en répondant à ses préférences.', 'Document 2 : Les fast-foods sont souvent accusés de nuire à la santé, car ils servent surtout des frites, des hamburgers et des boissons sucrées, très riches en calories. En plus, les emballages plastiques qu’ils utilisent produisent beaucoup de déchets, ce qui pose un vrai problème pour l’environnement.'] },
  ] } },
  { id: '2026-06-122', theme: 'La consommation de viande : pour ou contre ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Paul vous a demandé si le centre de langues-cultures pour tous est une bonne école. Répondez-lui en décrivant les salles, le matériel, les professeurs et tout ce qui vous semble important.' },
    { prompt: 'Après avoir pris part à un pique-nique avec vos collègues, vous rédigez un article pour le journal de l’entreprise. Vous y racontez le déroulement de ce moment en précisant le lieu, le repas et le temps qu’il faisait.' },
    { prompt: T3('La consommation de viande : pour ou contre ?'), documents: ['Document 1 : Quentin, 45 ans : Je me suis longtemps demandé s’il était vraiment nécessaire de manger de la viande chaque jour. Finalement, j’en ai réduit la consommation, tout comme celle du poisson. J’en mange seulement de temps en temps, au restaurant ou chez des amis, et jamais à la maison. Je me sens mieux ainsi, car mon alimentation est plus équilibrée et moins grasse. Je pense aussi que c’est bénéfique pour la planète.', 'Document 2 : Vanessa, 24 ans : Réduire la viande est un sujet très actuel, mais, pour ma part, je ne pourrais pas m’en passer. J’aime la cuisine de mes amis végétariens, pourtant, chez moi, préparer des repas sans viande me paraît difficile. Je me demande aussi si l’on peut vraiment s’en priver sans conséquence pour la santé. Quand j’ai essayé, j’étais plus fatiguée. Selon moi, il faut manger de tout pour rester en forme.'] },
  ] } },
  { id: '2026-06-123', theme: 'Voyager seul ou à plusieurs ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous voulez inviter un ami à un festival de musique organisé dans votre ville. Écrivez-lui une lettre en donnant les informations utiles : lieu, date, artistes présents et détails pratiques.' },
    { prompt: 'Sur votre blog, racontez votre plus récente sortie au restaurant. Décrivez le lieu, les plats, la qualité du service et expliquez ce qui vous a particulièrement plu.' },
    { prompt: T3('Voyager seul ou à plusieurs ?'), documents: ['Document 1 : Voyager seul offre une liberté totale : on choisit son itinéraire, ses activités et son rythme sans dépendre d’un groupe. Cela permet de profiter pleinement des lieux visités. C’est aussi une belle façon de sortir de sa zone de confort, de faire des rencontres enrichissantes et de développer son ouverture d’esprit.', 'Document 2 : Le voyage en solo a aussi ses limites. La solitude peut parfois peser, et l’absence d’un compagnon complique les imprévus. Pour certaines excursions difficiles ou dans des régions isolées, partir à plusieurs est plus rassurant. Enfin, voyager accompagné permet de partager ses découvertes et ses émotions, ce qui est très agréable.'] },
  ] } },
  { id: '2026-06-124', theme: 'Le travail : bénéfique ou nocif ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez inviter un ami à passer le week-end prochain chez vous. Rédigez-lui un message en précisant les activités prévues et le lieu.' },
    { prompt: 'Pour votre blog, racontez votre projet de partir douze mois sur les routes en laissant votre vie habituelle de côté. Présentez cette expérience exceptionnelle à vos lecteurs.' },
    { prompt: T3('Le travail : bénéfique ou nocif ?'), documents: ['Document 1 : Stéphane, entrepreneur : À mes yeux, le travail est bénéfique à la fois pour la personne et pour la société. Il permet de gagner sa vie, mais aussi de participer à la croissance économique. Il développe l’autonomie, la confiance en soi et le sens des responsabilités. Il peut également conduire à l’épanouissement et aider chacun à trouver sa place dans la société.', 'Document 2 : Laura, sociologue : Aujourd’hui, le travail peut aussi avoir des effets négatifs. Il est souvent source de stress, d’horaires contraignants et d’un déséquilibre entre vie privée et vie professionnelle. Quand la charge est trop lourde et la reconnaissance insuffisante, il peut mener à l’épuisement. Certaines tâches sont même aliénantes si les salariés ne se sentent ni reconnus ni impliqués.'] },
  ] } },
  { id: '2026-06-125', theme: 'Interdire les voitures en ville ?', created_at: '2026-06-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 6, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez échanger en français dans une ambiance simple et chaleureuse. Rédigez un courriel à l’adresse indiquée afin que l’on vous mette en relation avec quelqu’un qui partage vos centres d’intérêt. Présentez-vous brièvement dans votre message.' },
    { prompt: 'Envoyez un texte à vos amis pour leur décrire une célébration à laquelle vous avez participé avec votre famille.' },
    { prompt: T3('Interdire les voitures en ville ?'), documents: ['Document 1 : Beaucoup de villes veulent bannir les voitures du centre sans avoir encore prévu tout ce qu’il faut pour que la mesure fonctionne. Pourtant, réduire le trafic est utile contre la pollution. Il faut aussi organiser de grands parkings, renforcer les bus et les métros, et prévoir des dérogations pour les policiers, les secours ou les livreurs.', 'Document 2 : Dans plusieurs régions du monde, la pollution est devenue si forte que certaines villes ont choisi de fermer leurs centres aux voitures. Oslo, en Norvège, a adopté cette politique et s’en félicite. À long terme, cette décision devrait faire baisser les accidents, limiter la consommation de pétrole et améliorer l’air que respirent les habitants.'] },
  ] } },
  { id: '2026-05-100', theme: 'Les vols à bas prix', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Envoyez un courriel à vos amis pour les convier à l’anniversaire surprise de votre meilleur ami. Donnez les informations utiles comme l’endroit, le jour et l’heure.' },
    { prompt: 'Sur votre blog personnel, racontez votre participation à un vide-greniers dans votre ville, que ce soit pour acheter ou vendre des objets déjà utilisés. Expliquez pour quelles raisons cette expérience vous a plu.' },
    { prompt: T3('Les vols à bas prix.'), documents: ['Document 1 : Je voyage souvent avec des compagnies low-cost, car leurs billets sont bien moins chers que ceux des lignes classiques. Parfois, je paie même moins qu’en train ou en voiture. En revanche, il faut accepter l’absence de services à bord. Pour moi, ce type de vol convient mal aux longs trajets.', 'Document 2 : J’ai décidé d’abandonner les compagnies aériennes à bas prix. Les sièges y sont peu confortables, les conditions de travail me semblent difficiles et certains avions paraissent trop anciens pour inspirer confiance. Pour certains déplacements, je préfère désormais le train ou la voiture, et pour les longues distances, un vol classique reste plus rassurant.'] },
  ] } },
  { id: '2026-05-101', theme: 'Petits commerces ou supermarchés ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous avez envie de refaire l’intérieur de votre appartement. Dans un message adressé à un(e) ami(e), présentez vos idées pour les meubles, les couleurs ou les objets décoratifs, puis demandez-lui un coup de main.' },
    { prompt: 'Vous avez participé à l’évènement « École de musique ! Cours gratuits, concerts, jeux. Rendez-vous vendredi à partir de 9 heures ». Écrivez à vos amis pour leur raconter cette journée et donner votre avis sur l’expérience.' },
    { prompt: T3('Petits commerces ou supermarchés ?'), documents: ['Document 1 : Le supermarché est très pratique : tout est regroupé au même endroit et le choix est vaste. On peut s’y rendre facilement en voiture, parcourir les rayons et acheter aussi bien des fruits que des produits laitiers, de la viande ou des boissons. Les promotions sont fréquentes, tout comme les remises sur de nombreuses marques.', 'Document 2 : Association pour la sauvegarde des petits commerces. L’opération « Février sans supermarché » vise à limiter la domination des grandes surfaces et à soutenir les commerces de proximité. Pendant un mois, les clients font leurs achats dans les épiceries du quartier. Ils y trouvent des produits plus frais et de meilleure qualité, tout en échangeant davantage avec les voisins.'] },
  ] } },
  { id: '2026-05-102', theme: 'La sévérité des parents envers les enfants', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous vendez un vélo en bon état et à petit prix. Rédigez un courriel à la personne intéressée pour décrire votre vélo, proposer un prix et fixer un rendez-vous afin qu’elle puisse l’essayer.' },
    { prompt: 'Vous avez passé une journée à la campagne avec vos amis. À votre retour, écrivez un message sur votre forum pour raconter cette sortie et expliquer ce que vous avez le plus apprécié, notamment les activités, le lieu et les animaux.' },
    { prompt: T3('La sévérité des parents envers les enfants.'), documents: ['Document 1 : J’ai bientôt 22 ans et je vis encore chez mes parents, qui restent très stricts avec moi malgré mon âge. Quand j’étais adolescente, je n’avais pas le droit de sortir tard ni de dormir dehors. Aujourd’hui, les règles ont peu changé : ma mère m’appelle sans arrêt jusqu’à mon retour à la maison.', 'Document 2 : Certains parents redoutent d’être trop autoritaires. Ils craignent qu’un excès de sévérité empêche leurs enfants de s’épanouir et de développer leur personnalité. Pourtant, même lorsque l’on cède à tout par amour, cela peut nuire plus tard. Pour vivre en société, il faut apprendre à respecter certaines règles.'] },
  ] } },
  { id: '2026-05-103', theme: 'Les jeux vidéo : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Le journal « Bienvenue » prépare un article sur les habitants de la ville. Rédigez un message destiné à ce numéro : présentez-vous, puis décrivez les endroits que vous préférez dans cette ville depuis votre récente installation.' },
    { prompt: 'Vous êtes allé(e) au concert de votre artiste préféré. Écrivez un article pour votre blog afin de raconter cette expérience et d’encourager vos amis ainsi que les autres lecteurs à assister au prochain concert.' },
    { prompt: T3('Les jeux vidéo : pour ou contre ?'), documents: ['Document 1 : Chez les enfants et les adolescents, une pratique régulière des jeux vidéo peut favoriser des idées négatives et des attitudes agressives. Une étude menée auprès de jeunes de 9 à 18 ans jouant souvent à des jeux violents a montré une hausse nette des comportements agressifs. Selon Diego Gentil, ce risque existe même lorsque les parents surveillent attentivement.', 'Document 2 : On insiste souvent sur les effets négatifs des jeux vidéo, alors qu’ils peuvent aussi être utiles pour le cerveau et la santé en général. Ils améliorent notamment la concentration, la créativité et les capacités d’analyse. Cela paraît logique, puisqu’en jouant, il faut constamment réfléchir, résoudre des problèmes et prendre des décisions.'] },
  ] } },
  { id: '2026-05-104', theme: 'L’interdiction des voitures dans les centres-villes', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous avez trouvé sur Internet une annonce proposant d’aider les personnes qui veulent apprendre le français et de les mettre en relation avec des partenaires pour pratiquer la langue. Répondez par courriel en vous présentant et en expliquant pourquoi vous souhaitez progresser en français.' },
    { prompt: 'Après avoir participé à une réunion de famille, vous écrivez à vos amis pour leur raconter comment la fête s’est passée et préciser ce que vous y avez préféré.' },
    { prompt: T3('L’interdiction des voitures dans les centres-villes.'), documents: ['Document 1 : Face à une pollution alarmante dans de nombreuses villes, plusieurs métropoles ont choisi d’interdire la circulation des voitures en centre-ville. Oslo, la capitale norvégienne, a adopté cette mesure avec satisfaction. Selon les autorités, elle réduit les accidents, diminue la dépendance au pétrole et améliore nettement la qualité de l’air.', 'Document 2 : Certaines villes veulent bannir les voitures du centre sans préparer correctement cette transition. Réduire la circulation apporte certes moins d’embouteillages, moins de stress et un air plus sain, mais il faut aussi prévoir des parkings de grande capacité, renforcer les transports publics et autoriser l’accès à certains professionnels comme les policiers, les secours ou les livreurs.'] },
  ] } },
  { id: '2026-05-105', theme: 'La gratuité des transports en commun : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous êtes à la recherche d’un vélo en bon état à petit prix. Rédigez un courriel à la personne intéressée pour décrire votre vélo, indiquer combien vous en voulez et fixer un rendez-vous pour qu’elle puisse l’essayer.' },
    { prompt: 'Rédigez un message à vos amis pour leur raconter le travail saisonnier que vous avez fait pendant les vacances d’été et partager votre expérience.' },
    { prompt: T3('La gratuité des transports en commun : pour ou contre ?'), documents: ['Document 1 : Les transports publics gratuits sont une excellente initiative. Ils réduisent la circulation en ville, limitent les embouteillages et contribuent à diminuer la pollution, donc les problèmes de santé respiratoire. Là où cette mesure existe déjà, on voit davantage de voyageurs dans les bus et les tramways. En plus, les commerces du centre-ville en profitent, car les clients reviennent plus facilement y faire leurs achats.', 'Document 2 : Cette mesure me paraît coûteuse pour les municipalités, qui ont souvent d’autres priorités plus urgentes, comme l’aménagement d’espaces verts. Il vaudrait mieux améliorer l’offre de transport dans les quartiers mal desservis plutôt que de la rendre gratuite. Enfin, si les usagers payaient leur trajet, ils prendraient davantage soin du matériel et respecteraient plus les transports collectifs.'] },
  ] } },
  { id: '2026-05-106', theme: 'La vie à la campagne : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous voulez faire découvrir à vos amis un endroit touristique que vous aimez beaucoup. Écrivez-leur un message amical pour présenter ce lieu, expliquer ce qui vous plaît et proposer une date, une heure ainsi qu’un hébergement pour cette sortie.' },
    { prompt: 'Vous êtes allé(e) à un festival, par exemple de musique, de cinéma ou de gastronomie, et l’expérience ne vous a pas satisfait(e). Écrivez un billet de blog pour expliquer ce qui vous a déplu.' },
    { prompt: T3('La vie à la campagne : pour ou contre ?'), documents: ['Document 1 : À mon avis, la ville offre bien plus d’occasions de sortie que la campagne. On peut facilement aller au cinéma, au théâtre, au restaurant ou faire du shopping, tout est à proximité. Les activités culturelles y sont aussi beaucoup plus nombreuses : musées, opéras, concerts, expositions ou festivals s’y déroulent souvent. Tiffany, 28 ans', 'Document 2 : J’ai choisi la campagne pour retrouver le calme et vivre au contact de la nature. Ici, je reçois mes amis sur la terrasse plutôt que d’aller dans un bar, et l’été, les repas se transforment en barbecues dans le jardin. En plus, les loyers sont moins chers et j’ai pu acheter une maison avec jardin, idéale pour ma famille. Youssef, 34 ans'] },
  ] } },
  { id: '2026-05-107', theme: 'Le travail des jeunes pendant les vacances', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous préparez la célébration de votre anniversaire. Écrivez à vos amis pour les inviter, présenter le déroulement de la soirée et leur demander un coup de main pour l’organisation.' },
    { prompt: 'Vous avez pris part à une compétition culinaire. Publiez sur votre site un petit article pour raconter le déroulement de cette journée et dire les raisons pour lesquelles cette expérience vous a plu ou non.' },
    { prompt: T3('Le travail des jeunes pendant les vacances.'), documents: ['Document 1 : Les vacances servent normalement aux étudiants à se reposer après plusieurs mois d’études, à voyager et à profiter de la belle saison. Pourtant, certains préfèrent travailler : garde d’enfants, service en restauration, récolte de fruits… Même si ces emplois ont des avantages, ils réduisent le temps libre. Les jeunes ont alors moins l’occasion de se reposer, de sortir ou de voir leurs proches, et ces petits boulots sont parfois pénibles, mal rémunérés ou monotones.', 'Document 2 : Beaucoup d’étudiants choisissent de travailler l’été pour plusieurs raisons. D’abord, c’est une première expérience utile dans le monde professionnel : ils gagnent en autonomie et découvrent un métier. Ensuite, le salaire les motive. Enfin, ce travail peut leur offrir une indépendance financière, leur permettre de voyager ou de se faire plaisir. Pour certains, c’est même indispensable afin de payer leurs études ou leur logement.'] },
  ] } },
  { id: '2026-05-108', theme: 'Le travail : favorable ou défavorable ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Le mois prochain, vous souhaitez organiser un week-end avec vos amis. Écrivez-leur pour présenter votre idée en donnant des précisions sur la destination, le moyen de transport et les activités envisagées.' },
    { prompt: 'COURRIER DES LECTEURS — Partir voyager pendant un an en laissant tout derrière soi : bonne ou mauvaise idée ? Publiez votre réponse sur le site « voyage.internaute.fr » en vous appuyant sur des exemples tirés de votre expérience personnelle.' },
    { prompt: T3('Le travail : favorable ou défavorable ?'), documents: ['Document 1 : Le travail occupe une place centrale dans nos vies. Dès l’enfance, on demande souvent ce que l’on veut faire plus tard. Il devrait être associé à la réussite et à l’épanouissement, pourtant il rime trop souvent avec fatigue et sentiment d’enfermement. Beaucoup regrettent aussi de ne pas passer assez de temps avec leurs proches. Il devient donc nécessaire de repenser la place du travail dans la société et de réduire peut-être le temps de travail pour mieux vivre.', 'Document 2 : Certains choisissent d’abandonner leur emploi pour changer de vie, mais travailler reste essentiel pour exister dans la société. Lors d’une rencontre, la question « Que fais-tu dans la vie ? » montre bien que le métier fait partie de l’identité. Selon Jean-Daniel Remond, la vie en entreprise apporte des échanges, des contacts, des amitiés, un sentiment d’utilité, mais aussi des difficultés qui participent à construire la personnalité.'] },
  ] } },
  { id: '2026-05-109', theme: 'Égalité homme-femme', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Sur un forum, rédigez votre réponse en présentant votre pays et ses traditions. Donnez aux internautes l’envie de venir le découvrir. Votre texte doit contenir entre 60 et 120 mots.' },
    { prompt: 'Vous venez de commencer un nouvel emploi. Écrivez un courriel à vos amis pour leur raconter votre première semaine et leur dire ce que vous pensez de ce poste. Votre message doit contenir entre 120 et 150 mots.' },
    { prompt: T3('Égalité homme-femme.'), documents: ['Document 1 : L’égalité entre les femmes et les hommes fait partie des valeurs essentielles du Québec. Ils disposent des mêmes droits et des mêmes devoirs. Les femmes peuvent choisir librement leur profession et occupent aujourd’hui des postes de responsabilité : députées, maires, conseillères, dirigeantes ou administratrices. Beaucoup exercent aussi des métiers autrefois réservés aux hommes.', 'Document 2 : Louis a 27 ans et commence ses cours comme seul homme de sa promotion. Une fois diplômé, il deviendra le premier sage-femme masculin au Québec. Après avoir travaillé comme masseur auprès de femmes enceintes, il a compris que cette voie lui convenait. Même si ce métier reste traditionnellement féminin et peut encore étonner certaines patientes, sa présence dans la formation est une bonne chose.'] },
  ] } },
  { id: '2026-05-110', theme: 'La chasse aux animaux : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Rédigez un message pour inviter votre ami(e) à venir passer ses vacances dans votre ville. Présentez les lieux intéressants à découvrir et les endroits à visiter pendant son séjour.' },
    { prompt: 'Vous avez participé à un concours dont le premier prix était un séjour de deux semaines dans votre ville préférée, sur le thème « Mon artiste préféré ». Écrivez un article de blog pour parler de l’artiste que vous admirez le plus.' },
    { prompt: T3('La chasse aux animaux : pour ou contre ?'), documents: ['Document 1 : Je ne comprends pas qu’on puisse trouver du plaisir à tuer des animaux. Je ne comprends pas non plus comment certains prétendent aimer la nature tout en contribuant à sa destruction. Gala, 29 ans.', 'Document 2 : La chasse peut avoir plusieurs objectifs : se nourrir, vendre, gérer la faune, protéger les biens, s’exercer, se divertir ou encore chercher du prestige. Elle répond donc à des motivations très diverses. David, journaliste à la FRM.'] },
  ] } },
  { id: '2026-05-111', theme: 'Les produits faits maison : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Un ami vous a dit qu’il fréquentait une très bonne salle de sport. Répondez-lui par message pour lui présenter cet endroit : ambiance, matériel, tarifs et autres renseignements utiles.' },
    { prompt: 'Vous avez suivi un débat sur Internet à propos des formations en ligne. Rédigez un message pour raconter votre propre expérience, qu’il s’agisse d’un cours de langue ou d’une formation professionnelle. Précisez ce que vous avez aimé et ce qui vous a moins convaincu.' },
    { prompt: T3('Les produits faits maison : pour ou contre ?'), documents: ['Document 1 : Préparer soi-même des produits biologiques chez soi permet de choisir précisément les ingrédients et d’utiliser des formules plus saines. On réduit aussi les emballages en plastique grâce à des contenants réutilisables. En plus, cette pratique peut faire économiser de l’argent sur le long terme et développe des compétences utiles, tout en encourageant un mode de vie plus responsable.', 'Document 2 : Fabriquer des produits bio à la maison a aussi ses limites. Une recette mal suivie peut donner un résultat inefficace, voire provoquer des réactions. La préparation prend du temps et demande de l’énergie. Sans garantie de conservation ni de sécurité, ces produits peuvent favoriser les bactéries, et les ingrédients de qualité coûtent souvent cher au départ.'] },
  ] } },
  { id: '2026-05-112', theme: 'Livraison des repas au bureau : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Un(e) ami(e) veut visiter la région dans laquelle vous vivez. Écrivez-lui un message pour lui conseiller plusieurs lieux intéressants à découvrir.' },
    { prompt: 'Vous avez testé récemment un cours de sport dans une salle de votre ville. Rédigez un billet sur votre blog personnel pour raconter cette expérience et donner votre opinion sur cet établissement.' },
    { prompt: T3('Livraison des repas au bureau : pour ou contre ?'), documents: ['Document 1 : Commander son déjeuner au bureau permet de gagner du temps, car on reste sur place pendant la pause et l’on termine sa journée plus vite. Chacun peut aussi choisir le plat qui lui plaît, que ce soit italien, japonais ou autre. Enfin, ce service est souvent disponible à toute heure, puisque certains restaurants travaillent 24 heures sur 24.', 'Document 2 : Cette solution a aussi ses inconvénients. Quand les commandes sont nombreuses, les livreurs accusent du retard, ce qui crée du stress. De leur côté, les employés restent assis sans vraie coupure, ce qui peut fatiguer. Il vaut donc mieux faire une pause, même brève, pour rester performant au travail.'] },
  ] } },
  { id: '2026-05-113', theme: 'Les vêtements de grandes marques', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Lucas vous a écrit pour découvrir les nouveaux bureaux de votre société. Répondez-lui en présentant ces locaux : où ils se trouvent, comment les espaces sont organisés et quels matériels ou installations on y trouve.' },
    { prompt: 'Vous avez pris part à l’opération « Une semaine sans voiture ». Rédigez un texte pour raconter ce que vous avez vécu et dire ce que vous pensez de cette action. Présentez aussi l’organisation de l’événement : quand il a eu lieu, où il s’est déroulé et ce qui était proposé.' },
    { prompt: T3('Les vêtements de grandes marques.'), documents: ['Document 1 : Les vêtements de marque occupent une place importante chez les enfants et les adolescents. Ils servent à affirmer son style et à appartenir à un groupe. Chez les jeunes en pleine construction personnelle, les marques sont souvent un moyen d’exprimer leur personnalité. Les plus petits aiment aussi porter des habits ornés de leurs dessins animés ou de logos qu’ils apprécient.', 'Document 2 : Les enfants grandissent vite, donc leurs vêtements ne durent pas longtemps. Ils deviennent rapidement trop petits. En plus, pendant les jeux dehors, à l’aire de jeux ou dans l’herbe, les habits s’abîment facilement. Ils se salissent vite et finissent souvent troués.'] },
  ] } },
  { id: '2026-05-114', theme: 'L’uniforme à l’école : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous avez envie de faire de l’exercice avec un(e) ami(e). Écrivez-lui un message pour lui présenter votre idée en précisant les activités prévues, l’endroit choisi et le matériel nécessaire.' },
    { prompt: 'Pendant un semestre, vous avez suivi des cours dans une université hors de votre pays. Vous envoyez un message à vos amis pour leur raconter cette période et leur dire ce que vous avez particulièrement apprécié. Vous écrivez entre 120 et 150 mots.' },
    { prompt: T3('L’uniforme à l’école : pour ou contre ?'), documents: ['Document 1 : Aujourd’hui, les enfants sont très influencés par la mode, et les parents doivent souvent acheter de nouveaux vêtements. L’uniforme aide à limiter ces dépenses. Il renforce aussi le sentiment d’appartenance à l’école et la fierté des élèves. Enfin, porter la même tenue pour tous réduit les différences sociales et la discrimination liée à l’apparence.', 'Document 2 : Au Québec, l’uniforme ne concerne plus seulement les écoles privées : de plus en plus d’établissements publics l’adoptent. Pourtant, beaucoup d’adolescents le refusent. Ils le jugent peu confortable, peu esthétique à cause du manque de couleurs et trop chaud en été. Ils estiment aussi qu’il empêche chacun d’exprimer sa personnalité.'] },
  ] } },
  { id: '2026-05-115', theme: 'Les caméras de surveillance à l’école : sont-elles utiles ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez organiser votre anniversaire dans un restaurant. Invitez vos amis par courriel en leur donnant toutes les informations nécessaires : lieu, date, horaires, menu, prix, et demandez-leur de vous répondre.' },
    { prompt: 'Après avoir quitté la ville, vous vivez désormais à la campagne. Sur un forum, expliquez les raisons de cette décision et décrivez les points positifs de votre quotidien actuel. Vous écrivez entre 120 et 150 mots.' },
    { prompt: T3('Les caméras de surveillance à l’école : sont-elles utiles ?'), documents: ['Document 1 : À Montréal, dans l’école où j’enseigne, des caméras ont été installées dans de nombreux endroits. Elles rappellent aux élèves que tout acte de violence sera sanctionné. Parents, enseignants et majorité des élèves acceptent bien ce système. Les parents se sentent rassurés, les professeurs y gagnent en sécurité, tandis que quelques jeunes dénoncent une atteinte à leur vie privée.', 'Document 2 : Je suis opposé à l’installation de caméras de surveillance dans nos écoles montréalaises. Dans les endroits où ce système existe déjà, les effets semblent décevants. Comme les caméras sont visibles, des intrus peuvent contourner la surveillance en passant par des zones non contrôlées. Pour résoudre les problèmes de discipline, il vaudrait mieux renforcer la communication et faire respecter clairement le règlement intérieur.'] },
  ] } },
  { id: '2026-05-116', theme: 'Location de courte durée : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous voulez aller au concert de votre artiste préféré et vous proposez à votre ami de vous accompagner. Rédigez-lui un courriel en lui donnant toutes les informations nécessaires : la date, le tarif, le lieu, le nom de l’artiste et la durée du spectacle.' },
    { prompt: 'Les enseignants de l’école de votre quartier organisent une rencontre pour faire découvrir différents métiers aux élèves. Vous souhaitez y participer afin de présenter votre parcours. Écrivez-leur pour décrire votre profession, vos activités et vos collègues, puis expliquez ce qui rend ce travail intéressant à vos yeux.' },
    { prompt: T3('Location de courte durée : pour ou contre ?'), documents: ['Document 1 : Louer son logement ou une chambre à des voyageurs séduit de plus en plus de personnes. Cela permet de gagner un complément de revenu, mais aussi de faire des rencontres. Les visiteurs paient souvent moins qu’à l’hôtel et, s’ils sont autorisés à utiliser la cuisine, ils dépensent moins au restaurant. Le propriétaire peut aussi les conseiller sur les visites et les aider à découvrir la région.', 'Document 2 : L’an dernier, j’ai mis mon appartement à disposition d’un couple de touristes pendant une semaine à Marseille. J’en garde un très mauvais souvenir. Ils sont arrivés en retard, ont dérangé les voisins par le bruit et sont repartis sans laver leur vaisselle ni jeter leurs déchets. J’ai ensuite passé trois heures à tout nettoyer. Julien, 38 ans.'] },
  ] } },
  { id: '2026-05-117', theme: 'Le rôle de la télévision dans l’éducation des enfants', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous cherchez quelqu’un pour pratiquer une activité sportive avec vous. Rédigez une annonce à publier dans le journal de votre université. Vous écrivez entre 60 et 120 mots.' },
    { prompt: 'Rédigez un article de blog pour raconter votre arrivée dans un pays étranger. Décrivez vos premières impressions et expliquez ce qui vous a plu ainsi que ce qui vous a déplu. Votre texte doit compter entre 120 et 150 mots.' },
    { prompt: T3('Le rôle de la télévision dans l’éducation des enfants.'), documents: ['Document 1 : Dans notre société, la télévision reste un moyen de communication et de divertissement très présent. Elle diffuse des informations, propose des programmes variés et contribue à la circulation de la culture. Accessible dans de nombreux foyers, elle touche un large public et joue ainsi un rôle important dans la transmission des savoirs et la sensibilisation aux questions de société.', 'Document 2 : La télévision a aussi ses limites. Certaines émissions transmettent des stéréotypes, des idées reçues ou des valeurs discutables. De plus, passer trop de temps devant l’écran peut se faire au détriment de la lecture, du sport ou des relations sociales. Chez les enfants, il faut donc contrôler le temps d’exposition pour maintenir un bon équilibre entre apprentissage et loisirs.'] },
  ] } },
  { id: '2026-05-118', theme: 'Vie en colocation entre adultes', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Près de chez vous, un établissement de restauration a récemment commencé son activité. Écrivez à un(e) ami(e) pour lui suggérer d’y aller avec vous, en présentant le lieu : spécialités, budget, ambiance et décoration.' },
    { prompt: 'Vous avez découvert une ville que vous ne connaissiez pas encore et vous voulez partager cette expérience. Publiez un message sur un site de voyage pour raconter votre séjour et dire ce que vous avez aimé ou non dans cette ville.' },
    { prompt: T3('Vie en colocation entre adultes.'), documents: ['Document 1 : Vivre avec d’autres personnes exige de la tolérance et des règles claires. On ne peut pas toujours écouter sa musique très fort, inviter des amis pour faire la fête ou laisser de la vaisselle sale traîner dans la cuisine. Comme chacun a ses habitudes, des tensions peuvent vite apparaître. D’où l’importance de discuter dès qu’un problème surgit et de respecter les règles de la vie commune.', 'Document 2 : Pour un adulte, la colocation peut être une solution pratique et économique. Certes, il faut partager la cuisine, le salon et la salle de bain, et ne disposer que d’une chambre. Mais on peut aussi habiter un grand appartement ou une maison avec jardin. En plus, le loyer et les charges sont divisés, ce qui réduit nettement les dépenses par rapport à un logement individuel.'] },
  ] } },
  { id: '2026-05-119', theme: 'Les animaux de compagnie pour les enfants : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Rédigez un message à votre ami qui aimerait suivre des cours de langue dans votre école. Donnez-lui des informations précises pour l’aider à choisir : l’endroit, les prix, les types de cours proposés, et tout autre détail utile.' },
    { prompt: 'Vous intervenez dans une association au service des personnes âgées. Rédigez un article de blog pour partager votre vécu et motiver d’autres personnes à rejoindre cette association.' },
    { prompt: T3('Les animaux de compagnie pour les enfants : pour ou contre ?'), documents: ['Document 1 : Donner un animal de compagnie à un enfant apporte beaucoup d’avantages, comme le rappellent plusieurs psychologues. Pour un enfant sans frère ni sœur, l’animal devient un compagnon et chasse la solitude. Il développe aussi sa confiance en lui et apprend qu’un animal mérite soin et respect. Avec lui, l’enfant se sent rassuré et gagne en autonomie, sans dépendre en permanence de ses parents.', 'Document 2 : Beaucoup d’enfants réclament un chien ou un chat à leurs parents, mais il faut réfléchir avant d’acheter un animal. Il ne s’agit pas d’un jouet, mais d’un nouveau membre de la famille qui demande du temps, de l’argent et une vraie responsabilité pendant plusieurs années. On ne peut donc pas s’en débarrasser simplement quand l’enfant se lasse.'] },
  ] } },
  { id: '2026-05-120', theme: 'Limiter les voitures dans les centres-villes', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez réunir vos amis pour célébrer la fin de l’année. Rédigez un message pour les convier à cette soirée.' },
    { prompt: 'Après un séjour au Canada organisé par une agence de voyages, vous voulez partager ce que vous avez vécu. Rédigez un avis pour raconter votre expérience pendant ce voyage.' },
    { prompt: T3('Limiter les voitures dans les centres-villes.'), documents: ['Document 1 : Face à des niveaux de pollution très préoccupants, plusieurs villes ont décidé de bannir les voitures de certains espaces urbains. Oslo, en Norvège, a récemment fait ce choix et s’en réjouit, car la mesure profite à tous. Avec le temps, les accidents devraient diminuer, la dépendance au pétrole aussi, et l’air sera plus sain.', 'Document 2 : Beaucoup de villes interdisent la voiture en centre-ville sans préparer suffisamment cette transition. Réduire le trafic est utile, mais cela demande aussi de grands parkings, un réseau de transports en commun renforcé et des dérogations pour certains professionnels, comme les policiers, les secouristes ou les livreurs.'] },
  ] } },
  { id: '2026-05-121', theme: 'La lecture chez les enfants', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Un de vos amis veut se mettre au sport. Écrivez-lui un message pour lui conseiller un club de sport dans votre quartier, en donnant des informations utiles comme l’adresse, les prix et les activités disponibles.' },
    { prompt: 'Vous gardez un souvenir fort d’une célébration à laquelle vous avez assisté, comme un anniversaire ou un mariage. Racontez cet événement en expliquant ce qui vous a le plus impressionné.' },
    { prompt: T3('La lecture chez les enfants.'), documents: ['Document 1 : Avec les écrans et les loisirs numériques omniprésents, beaucoup d’enfants se détournent des livres au profit des jeux vidéo, des réseaux sociaux ou du sport. À quoi bon leur imposer la lecture ? Le plaisir de lire ne se commande pas : il vaut mieux laisser chacun choisir ses activités sans le forcer à ouvrir un livre.', 'Document 2 : L’habitude de lire se construit très tôt et se transmet souvent en famille. Lire régulièrement aide l’enfant à mieux maîtriser la langue, à rester attentif et à renforcer sa concentration. En plus, partager dix minutes de lecture chaque jour avec ses parents crée un vrai moment de complicité et de plaisir commun.'] },
  ] } },
  { id: '2026-05-122', theme: 'La sieste au bureau', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Proposez à vos amis de passer un week-end avec vous pour pratiquer une activité sportive. Rédigez-leur un message en leur donnant cette idée.' },
    { prompt: 'Sur un forum, rédigez un article de blog pour expliquer les raisons qui vous ont poussé à modifier votre alimentation.' },
    { prompt: T3('La sieste au bureau.'), documents: ['Document 1 : La sieste au travail peut être bénéfique pour tout le monde. Un repos court améliore la vigilance, la concentration et l’humeur, tout en diminuant le stress. Pour l’entreprise aussi, les effets sont positifs : moins de fatigue, moins d’accidents et donc moins de dépenses liées aux problèmes de santé ou de sécurité.', 'Document 2 : Même si les avantages sont réels, toutes les entreprises ne peuvent pas installer des espaces de repos. Le coût, l’organisation ou certaines règles internes compliquent sa mise en place. De plus, tous les salariés n’osent pas dormir sur leur lieu de travail. Il faut donc imaginer des solutions adaptées au contexte de chaque entreprise.'] },
  ] } },
  { id: '2026-05-123', theme: 'Diplôme ou expérience : que vaut le plus pour les jeunes ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous avez trouvé un appartement et vous comptez déménager. Informez un ami en lui donnant les informations essentielles sur ce logement : nombre de pièces, adresse et loyer.' },
    { prompt: 'Dans votre ville, un festival de musique gratuit a été annoncé, et vous y êtes allé(e) avec un ami. Écrivez un article de blog pour raconter ce moment et décrire l’expérience vécue pendant cette manifestation.' },
    { prompt: T3('Diplôme ou expérience : que vaut le plus pour les jeunes ?'), documents: ['Document 1 : Beaucoup de jeunes diplômés peinent à entrer sur le marché du travail. Malgré leurs études, ils se heurtent à des employeurs qui leur reprochent un manque d’expérience ou leur jeune âge. Plus de six diplômés sur dix n’ont toujours pas trouvé d’emploi un an après l’université, ce qui montre l’urgence de mieux valoriser les diplômes.', 'Document 2 : Des entrepreneurs connus ont réussi sans passer par l’université, ce qui fait croire que l’expérience et le talent suffisent. Certains chefs d’entreprise vont même jusqu’à dire que les études brident l’initiative et poussent au conformisme. Pour créer son activité, l’autoformation et la pratique seraient donc plus utiles qu’un parcours académique classique.'] },
  ] } },
  { id: '2026-05-124', theme: 'La campagne ou la ville', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous avez besoin d’un logement et vous demandez l’aide de votre ami francophone. Écrivez-lui un courriel en lui donnant les renseignements utiles pour cette recherche, par exemple le type d’habitation souhaité, la somme prévue et la date d’installation.' },
    { prompt: 'Vous devez préparer la journée d’accueil destinée aux nouveaux étudiants francophones de votre établissement. Rédigez un courriel à leur attention pour présenter le programme prévu et transmettre toutes les informations pratiques nécessaires.' },
    { prompt: T3('La campagne ou la ville.'), documents: ['Document 1 : Vivre en ville, c’est profiter facilement de nombreux loisirs : cinéma, théâtre, restaurants ou magasins sont à proximité. Les activités culturelles y sont aussi plus variées, avec des musées, des salles de concert, des opéras et des festivals. En ville, on trouve presque tout sans avoir à parcourir de longues distances.', 'Document 2 : J’ai choisi la campagne pour le calme, la nature et une vie plus agréable. Je remplace les sorties au restaurant par des repas entre amis sur la terrasse ou des barbecues dans le jardin. En plus, le logement y coûte moins cher : avec le budget d’un petit appartement en ville, j’ai une maison avec jardin. Youssef, 34 ans'] },
  ] } },
  { id: '2026-05-125', theme: 'La publicité destinée aux enfants : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous cherchez à partager votre grand logement avec une autre personne. Présentez la formule de colocation que vous offrez et décrivez votre appartement.' },
    { prompt: 'Une compagnie théâtrale est arrivée dans votre commune et vous êtes allé voir une représentation. Écrivez un billet de blog pour raconter ce moment et décrire ce que vous avez vécu.' },
    { prompt: T3('La publicité destinée aux enfants : pour ou contre ?'), documents: ['Document 1 : Les enfants sont exposés en permanence à la publicité, à la télévision, dans les magazines ou sur Internet. Ils sont souvent visés par des messages pour des aliments peu sains, des jouets ou des jeux vidéo. Cette pression publicitaire influence leurs envies et leurs demandes auprès de leurs parents.', 'Document 2 : Les enfants comprennent difficilement le message publicitaire et ne perçoivent pas toujours son but de persuasion. Cependant, leur comportement d’achat dépend davantage de l’éducation reçue, de l’entourage et du milieu social que de la publicité elle-même. D’autres facteurs pèsent donc plus lourd dans leurs choix.'] },
  ] } },
  { id: '2026-05-126', theme: 'La restauration rapide', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous préparez une fête d’anniversaire surprise pour votre meilleur ami. Rédigez un courriel à vos amis pour les convier en précisant les informations utiles comme l’endroit, le jour et l’heure.' },
    { prompt: 'Vous revenez d’une réunion familiale et vous voulez en parler à vos amis. Écrivez-leur un message pour raconter cette fête et dire ce que vous y avez préféré.' },
    { prompt: T3('La restauration rapide.'), documents: ['Document 1 : Les fast-foods posent un vrai problème pour la santé, car on y consomme souvent les mêmes plats riches en calories : hamburgers, frites et sodas. À cela s’ajoute l’impact écologique : une grande partie des aliments est emballée dans du plastique, ce qui multiplie les déchets et nuit à l’environnement.', 'Document 2 : Il ne faut pas juger la restauration rapide trop sévèrement. Elle permet de manger chaud en quelques minutes, ce qui est très pratique quand on manque de temps. Présents partout, les fast-foods offrent aussi un cadre hygiénique et une solution simple pour les personnes pressées.'] },
  ] } },
  { id: '2026-05-127', theme: 'Les jeux vidéo ont-ils un impact sur notre comportement ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Comme votre anniversaire approche, vos amis veulent savoir quels présents vous feraient plaisir. Vous souhaitez recevoir des habits : écrivez-leur un message pour expliquer quels vêtements vous aimeriez avoir.' },
    { prompt: 'Vous avez lu l’annonce du site « www.manger-international.com ». Rédigez un article pour les lecteurs et expliquez comment mangent les habitants de votre pays. Dites aussi quelles habitudes alimentaires vous plaisent ou vous déplaisent, en précisant pourquoi.' },
    { prompt: T3('Les jeux vidéo ont-ils un impact sur notre comportement ?'), documents: ['Document 1 : Contrairement à ce que certains pensent, les jeux vidéo ne rendent pas moins intelligents. Plusieurs études montrent qu’ils peuvent améliorer l’orientation, la mémoire, la précision des gestes, ainsi que la rapidité et la concentration. Certains jeux servent même à entraîner les personnes âgées. Le jeu vidéo peut donc stimuler l’esprit.', 'Document 2 : Les jeux vidéo peuvent devenir une véritable dépendance. Lorsqu’ils prennent toute la place, ils remplacent les activités scolaires, sociales, sportives ou professionnelles. Ce risque est particulièrement inquiétant à l’adolescence, car cette habitude peut alors nuire aux résultats à l’école.'] },
  ] } },
  { id: '2026-05-128', theme: 'Les publicités : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Installé depuis peu dans une autre ville, vous écrivez à un(e) ami(e). Décrivez-lui votre nouveau cadre de vie : le quartier, les habitants, les commerces, etc.' },
    { prompt: 'Vous avez participé à une action de nettoyage dans le cadre de la « Journée mondiale du nettoyage de notre planète ». Racontez cette expérience à vos amis et expliquez pourquoi ce type d’initiative est important.' },
    { prompt: T3('Les publicités : pour ou contre ?'), documents: ['Document 1 : La publicité n’est pas seulement agaçante, elle est aussi utile. Elle permet aux entreprises de faire connaître leurs produits, informe sur les nouveautés et les promotions, et peut même être divertissante. Elle aide aussi à comparer les offres et à économiser. Sans elle, certains services gratuits deviendraient payants.', 'Document 2 : La publicité envahit notre quotidien, que ce soit à la télévision, dans la presse, à la radio ou sur Internet. Elle interrompt les émissions et remplit les boîtes aux lettres de papier inutile. Il faudrait donc limiter ces messages par une loi, afin qu’ils soient plus discrets et moins gênants.'] },
  ] } },
  { id: '2026-05-129', theme: 'Les parcs zoologiques : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Installé depuis un mois dans une autre ville, vous écrivez un courriel à votre ami Léo pour lui raconter comment vous allez. Dans votre message, parlez de votre logement, de votre quartier, de la ville et des activités que vous avez découvertes.' },
    { prompt: 'Vous avez pris part à une célébration traditionnelle, dans votre pays ou ailleurs. Écrivez un billet de blog pour présenter cette fête et préciser les raisons pour lesquelles elle vous a plu.' },
    { prompt: T3('Les parcs zoologiques : pour ou contre ?'), documents: ['Document 1 : Les zoos ont un rôle positif, notamment pour les espèces menacées. Les animaux y sont soignés et protégés, et les programmes de reproduction mis en place ont permis d’augmenter les naissances. Ils participent ainsi à la sauvegarde de certaines espèces en danger.', 'Document 2 : Les animaux sauvages n’ont pas leur place dans des zoos, car ils devraient vivre dans leur milieu naturel. Ces lieux ressemblent à des prisons, comme le montre l’exemple d’ours polaires enfermés dans des espaces bien trop chauds. Les animaux ont besoin de liberté et d’un environnement adapté.'] },
  ] } },
  { id: '2026-05-130', theme: 'La restauration rapide', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez aller à un festival de cinéma dans votre ville. Écrivez à votre ami(e) pour lui proposer de vous accompagner et donnez-lui toutes les informations utiles : films, dates, horaires, prix, etc.' },
    { prompt: 'Vous avez hébergé un(e) étudiant(e) étranger(e) chez vous pendant une semaine. Rédigez un article pour votre blog afin de raconter cette expérience et d’expliquer pourquoi vous l’avez trouvée agréable.' },
    { prompt: T3('La restauration rapide.'), documents: ['Document 1 : Les fast-foods se distinguent par une offre variée de repas équilibrés et par le respect strict des règles d’hygiène. En laissant les clients choisir eux-mêmes leur menu, ils leur permettent d’adapter leur repas à leurs goûts tout en prenant leurs responsabilités alimentaires.', 'Document 2 : Manger souvent dans un fast-food présente des risques pour la santé. On y retrouve surtout des plats très caloriques, comme les hamburgers, les frites et les boissons sucrées. En plus, ces produits génèrent beaucoup d’emballages plastiques, ce qui aggrave la pollution de l’environnement.'] },
  ] } },
  { id: '2026-05-131', theme: 'La sévérité des parents : nécessaire ou excessive ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Un(e) de vos ami(e)s va bientôt célébrer son anniversaire. Écrivez à vos amis pour proposer d’acheter ensemble un présent.' },
    { prompt: 'La direction d’une école de musique recherche un lieu pour accueillir une fête réunissant 100 personnes. Écrivez un courriel pour présenter un local adapté et donner ses caractéristiques : emplacement, prix, services proposés, etc.' },
    { prompt: T3('La sévérité des parents : nécessaire ou excessive ?'), documents: ['Document 1 : Je vais bientôt avoir 22 ans et je vis encore chez mes parents. Même à mon âge, ils restent très stricts avec moi. Quand j’étais mineure, je n’avais pas le droit de dormir chez des amies ni de rentrer après 21 h. Aujourd’hui, la situation a peu changé : j’ai simplement le droit de sortir plus tard, mais ma mère m’appelle sans arrêt jusqu’à mon retour.', 'Document 2 : Certains parents redoutent d’être trop durs avec leurs enfants. Ils pensent qu’une autorité excessive peut freiner leur épanouissement et nuire à leur personnalité plus tard. Pourtant, même si l’amour pousse parfois les parents à tout accepter, cela peut avoir des conséquences négatives à l’âge adulte, car vivre en société implique de respecter des règles.'] },
  ] } },
  { id: '2026-05-132', theme: 'La gratuité des musées : bonne ou mauvaise idée ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous êtes locataire d’un appartement trop grand pour vous. Rédigez une annonce pour un journal afin de chercher un ou une colocataire en précisant la taille du logement, le profil souhaité, le loyer, etc.' },
    { prompt: 'Vous débutez un nouveau loisir, par exemple un sport ou la danse. Rédigez un article de blog pour raconter cette découverte.' },
    { prompt: T3('La gratuité des musées : bonne ou mauvaise idée ?'), documents: ['Document 1 : Rendre les musées gratuits risque d’attirer trop de visiteurs, ce qui dégrade l’expérience sur place. En plus, cette mesure ferait baisser les revenus des établissements, avec des conséquences sur l’entretien et la conservation des œuvres. Une entrée à tarif réduit me paraît plus équilibrée pour ouvrir la culture à tous tout en aidant les musées.', 'Document 2 : La gratuité des musées est une très bonne initiative. Elle donne accès à la culture à chacun, quelle que soit sa situation financière. J’ai visité plusieurs musées sans payer et cela m’a permis d’apprendre beaucoup sans penser au prix. À mes yeux, cette mesure favorise l’éducation et le partage du patrimoine.'] },
  ] } },
  { id: '2026-05-133', theme: 'Le livre papier ou le livre numérique ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Bernard va bientôt s’installer dans votre quartier et cherche un endroit agréable pour faire ses courses. Répondez-lui en lui parlant d’un marché que vous appréciez dans votre quartier, avec son emplacement, ses horaires et les produits qu’on y trouve.' },
    { prompt: 'Vous participez à une association de quartier qui organise des activités pour les enfants, comme de l’aide aux devoirs, des sorties ou des jeux. Rédigez un texte pour le site internet afin de raconter votre expérience et d’expliquer l’utilité de cette association.' },
    { prompt: T3('Le livre papier ou le livre numérique ?'), documents: ['Document 1 : Depuis quelques années, beaucoup de lecteurs ont délaissé la bibliothèque classique au profit des livres numériques. Ils y voient surtout un avantage financier : on économise du papier et les versions numériques coûtent souvent moins cher. Elles sont aussi utiles pour les personnes handicapées, car certaines fonctions, comme l’agrandissement des caractères, facilitent la lecture des personnes malvoyantes.', 'Document 2 : Le livre numérique va-t-il remplacer le livre papier ? Pour beaucoup, la réponse est non. Le format papier reste attachant : on aime l’offrir, le prêter ou y glisser un mot personnel. Son histoire, son odeur et son aspect matériel créent des émotions qu’un écran ne transmet pas. En plus, le numérique demande des compétences informatiques que tout le monde n’a pas.'] },
  ] } },
  { id: '2026-05-134', theme: 'Les cours de langues en ligne', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Votre ami Ali vous écrit : « Tu as commencé ton nouveau travail ! Comment ça se passe ? Tu es content(e) ? » Répondez-lui en décrivant votre poste, votre lieu de travail, vos collègues et vos impressions.' },
    { prompt: 'Le site « Infos Familles » lance un appel à témoignages sur la vie avec une personne âgée. Vous avez connu cette situation : racontez votre expérience.' },
    { prompt: T3('Les cours de langues en ligne.'), documents: ['Document 1 : Apprendre une langue en ligne grâce à Internet, c’est tout à fait possible et les résultats sont bons. Contrairement aux cours traditionnels, on peut se former à n’importe quel moment, puisque les leçons sont disponibles en permanence. Cela aide à mieux s’organiser, évite les déplacements et permet d’étudier chez soi, au bureau ou dans un café. C’est aussi une solution économique.', 'Document 2 : L’apprentissage d’une langue en ligne paraît simple, mais il ne convient pas à tout le monde. Il faut d’abord disposer d’une bonne connexion et du matériel adapté. Ensuite, il faut être très autonome, car étudier seul chez soi demande de la discipline. Sans professeur ni camarades pour soutenir la motivation, on peut vite se décourager et abandonner.'] },
  ] } },
  { id: '2026-05-135', theme: 'Les nouvelles technologies à l’école : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous rentrez d’un séjour de deux jours à la campagne. Écrivez un message à votre ami(e) pour lui raconter votre week-end et ce qui s’y est passé.' },
    { prompt: 'La direction cherche une salle pour la fête de fin d’année, pouvant accueillir 100 invités. Rédigez un message pour annoncer que vous avez trouvé un lieu parfait, en indiquant son emplacement, ses tarifs et ses services.' },
    { prompt: T3('Les nouvelles technologies à l’école : pour ou contre ?'), documents: ['Document 1 : Jean estime que l’intégration des nouvelles technologies à l’école est essentielle pour préparer les élèves au monde numérique de demain. Selon lui, les tablettes et les ordinateurs rendent les cours plus motivants et enrichissent l’apprentissage grâce à l’accès à de nombreuses ressources. Ils encouragent aussi la créativité et développent l’autonomie des élèves.', 'Document 2 : Sara reste réservée face à l’usage massif des technologies en classe. Elle pense que cela peut diminuer les échanges humains importants et créer une dépendance excessive aux écrans. À ses yeux, les méthodes traditionnelles et le contact direct entre professeurs et élèves demeurent indispensables pour un développement équilibré des jeunes.'] },
  ] } },
  { id: '2026-05-136', theme: 'Les devoirs à la maison : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous avez reçu un objet commandé sur Internet, mais à l’ouverture du colis vous constatez qu’il est endommagé. Écrivez un e-mail au service clientèle pour signaler le problème, décrire les dégâts et préciser la solution que vous attendez.' },
    { prompt: 'Vous êtes allé voir une exposition consacrée à votre artiste favori. Rédigez un article pour raconter votre visite, décrire les œuvres observées et donner vos impressions.' },
    { prompt: T3('Les devoirs à la maison : pour ou contre ?'), documents: ['Document 1 : D’après plusieurs associations de parents, les devoirs à la maison présentent un vrai intérêt : ils apprennent aux élèves à mieux gérer leur temps et à travailler seuls. Pour les familles, ils créent aussi un contact régulier avec l’école. Même quand cela demande un effort après une journée de travail, beaucoup de parents apprécient ce moment avec leurs enfants.', 'Document 2 : Nous sommes opposés aux devoirs à la maison. Leur efficacité n’a jamais été démontrée, et beaucoup de parents n’ont ni le temps ni les compétences pour aider leurs enfants. De plus, les élèves à l’aise en classe perdent du temps, tandis que ceux qui manquent d’aide à la maison restent en difficulté. Il faut donc les supprimer.'] },
  ] } },
  { id: '2026-05-137', theme: 'Les écoles privées ou publiques ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: '« France Télévision » prépare un sujet sur la pratique sportive non professionnelle. Quel type de sportif êtes-vous ? Donnez votre point de vue.' },
    { prompt: 'Vous avez séjourné dans une très jolie région de votre pays et vous souhaitez en parler à vos amis. Écrivez-leur un message pour décrire ce voyage et expliquer pourquoi vous avez tant aimé ce séjour.' },
    { prompt: T3('Les écoles privées ou publiques ?'), documents: ['Document 1 : La hausse des inscriptions dans le privé s’explique surtout par son image positive, plus que par les résultats scolaires. Beaucoup de parents pensent que les élèves y sont mieux encadrés, davantage surveillés et suivis par des enseignants plus présents. Ils apprécient aussi le fait que les classes regroupent souvent des jeunes de milieux favorisés.', 'Document 2 : Les établissements privés accueillent peu d’élèves issus de milieux modestes, car ils sont payants. Cette sélection limite la mixité sociale et empêche souvent les jeunes de se rencontrer au-delà de leurs différences. Au final, ce système entretient les inégalités et renforce le sentiment d’exclusion chez certains élèves.'] },
  ] } },
  { id: '2026-05-138', theme: 'L’aide aux personnes pauvres', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous venez d’obtenir un emploi et vous envoyez un message à votre amie francophone pour partager cette excellente nouvelle. Présentez les missions de votre poste, parlez des personnes avec qui vous travaillez et décrivez votre environnement professionnel.' },
    { prompt: 'Une étudiante de 19 ans souhaite partir à l’étranger pour ses études. Sur un forum, elle demande des retours d’expérience, et vous avez passé un an à l’étranger. Racontez-lui votre séjour, vos activités et ce que vous en avez retiré.' },
    { prompt: T3('L’aide aux personnes pauvres.'), documents: ['Document 1 : Marie, 58 ans : Depuis longtemps, je donne du temps et un peu d’argent pour aider les personnes en grande difficulté, notamment celles qui vivent dehors en hiver. À mes yeux, c’est une responsabilité d’aider les autres et de rendre leur vie aussi digne que possible. Soutenir des pauvres ou des associations permet aussi de se sentir utile dans une société de plus en plus dure.', 'Document 2 : Paul, 63 ans : Pour venir en aide aux personnes pauvres, il faut surtout s’impliquer dans des associations caritatives. C’est ce que je fais bénévolement dans mon quartier. L’objectif principal est d’aider les sans-abri à trouver un logement et un emploi, afin qu’ils deviennent autonomes. Cette aide est durable et plus efficace sur le long terme.'] },
  ] } },
  { id: '2026-05-139', theme: 'Vivre en colocation : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Votre ami Mehdi vient d’emménager dans votre ville et souhaite se renseigner sur les transports. Écrivez-lui un message pour lui donner les informations utiles : moyens de transport, abonnement, tarifs, et autres détails pratiques.' },
    { prompt: 'Rédigez un article de blog pour exprimer votre admiration pour une personnalité, célèbre ou non. Appuyez-vous sur ses actions concrètes pour expliquer ce qu’elle a fait de remarquable et pourquoi vous l’appréciez.' },
    { prompt: T3('Vivre en colocation : pour ou contre ?'), documents: ['Document 1 : La colocation peut aussi avoir ses inconvénients. Des différences de caractère ou d’habitudes peuvent créer des tensions entre les colocataires, et le partage des tâches ménagères provoque parfois des disputes. Elle réduit également l’espace personnel et l’intimité. Pour bien vivre ensemble, il faut une communication claire, du respect et des règles communes.', 'Document 2 : La vie en colocation offre plusieurs avantages. Elle permet d’abord de diminuer les dépenses, car le loyer, les factures et les frais du quotidien sont partagés. Elle favorise aussi les rencontres, les échanges et l’ouverture à d’autres cultures. C’est une bonne façon de se faire des amis et d’échanger des expériences enrichissantes.'] },
  ] } },
  { id: '2026-05-140', theme: 'Cuisinier amateur ou cuisinier professionnel ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Cédric a bien reçu votre invitation pour votre mariage au Château de Chombony, mais il ne situe pas cet endroit. Écrivez-lui pour lui présenter le château, préciser où il se trouve et indiquer comment on peut y aller.' },
    { prompt: 'Sur votre blog ou sur un forum, racontez votre expérience de l’apprentissage d’une langue étrangère.' },
    { prompt: T3('Cuisinier amateur ou cuisinier professionnel ?'), documents: ['Document 1 : Les cuisiniers amateurs peuvent réussir certaines recettes, mais cela ne suffit pas pour maîtriser le métier. Les compétences techniques et la pratique restent indispensables ; c’est pourquoi une formation solide et de l’expérience sont nécessaires pour devenir un véritable cuisinier.', 'Document 2 : Le document présente des cuisiniers autodidactes qui ont appris grâce à Internet et sont devenus populaires sur les réseaux sociaux. Il raconte aussi le parcours d’une amatrice devenue professionnelle, qui a ensuite publié plusieurs livres de cuisine destinés aux passionnés qui préparent leurs plats à la maison.'] },
  ] } },
  { id: '2026-05-141', theme: 'Les distributeurs automatiques à l’école : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous allez passer un week-end dans la ville d’Anna. Rédigez-lui un message pour lui indiquer quels moyens de transport elle pourra utiliser afin de visiter la ville.' },
    { prompt: 'Vous avez pris part à une soirée organisée entre habitants de votre quartier. Rédigez un billet de blog pour expliquer ce qui vous a plu lors de cette rencontre.' },
    { prompt: T3('Les distributeurs automatiques à l’école : pour ou contre ?'), documents: ['Document 1 : Je suis favorable aux distributeurs de boissons dans les lycées. Ils dépannent les élèves pressés qui n’ont pas le temps d’aller à la cafétéria. Bien gérés, ils peuvent proposer des boissons plus saines, comme de l’eau, des jus purs ou des boissons aux fruits sans sucre ajouté. Ils peuvent aussi rapporter de l’argent à l’établissement.', 'Document 2 : Je m’oppose aux distributeurs de boissons dans les lycées, surtout pour des raisons de santé. Beaucoup contiennent des sodas et des boissons trop sucrées, mauvais pour les élèves et liés à l’obésité ou au diabète. Même les jus de fruits ne sont pas toujours une bonne option, car ils peuvent contenir beaucoup de sucre.'] },
  ] } },
  { id: '2026-05-142', theme: 'Cuisinier amateur ou professionnel ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Votre ami Cédric ne connaît pas le Château de Chombony, où vous allez célébrer votre mariage. Présentez-lui ce lieu en précisant notamment où il se trouve et comment on peut s’y rendre.' },
    { prompt: 'Sur un forum ou dans un blog, racontez comment vous avez appris une langue étrangère et partagez votre expérience avec les internautes.' },
    { prompt: T3('Cuisinier amateur ou professionnel ?'), documents: ['Document 1 : Les cuisiniers amateurs peuvent réussir de bons plats, mais cela ne suffit pas pour maîtriser ce métier. Sans technique ni vraie expérience, on ne devient pas un véritable chef. C’est pourquoi une formation sérieuse et la pratique restent indispensables pour cuisiner comme un professionnel.', 'Document 2 : On voit aujourd’hui des passionnés de cuisine qui ont appris grâce à Internet et qui rencontrent un vrai succès sur les réseaux sociaux. Il existe aussi des amateurs devenus professionnels, qui ont ensuite écrit plusieurs ouvrages pour aider les personnes qui cuisinent à la maison.'] },
  ] } },
  { id: '2026-05-143', theme: 'Vivre en colocation', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Votre ami Mehdi vient d’arriver dans votre ville et souhaite obtenir des renseignements pratiques sur les transports. Envoyez-lui un message en lui donnant les informations essentielles : types de transport, abonnement, prix, etc.' },
    { prompt: 'Rédigez un article de blog pour parler d’une personnalité que vous admirez, connue ou non. Appuyez-vous sur ses actions précises pour expliquer ce qui fait votre admiration.' },
    { prompt: T3('Vivre en colocation.'), documents: ['Document 1 : Ceux qui n’aiment pas manger seuls trouvent souvent leur bonheur en colocation. On partage les repas, mais aussi des moments conviviaux, par exemple autour d’un jeu de société. La vie à plusieurs facilite aussi les tâches domestiques. Elle permet d’échanger, d’ouvrir son esprit, de découvrir d’autres modes de vie et de créer des liens forts.', 'Document 2 : La colocation peut aussi être difficile, surtout quand on veut rester tranquille après une journée chargée. Il faut accepter les amis des autres, respecter les règles pour le ménage et ne pas tout laisser reposer sur une seule personne. Elle demande donc beaucoup de tact, sauf si l’on tombe sur un colocataire idéal.'] },
  ] } },
  { id: '2026-05-144', theme: 'Les relations amicales au travail', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Matthias a obtenu son visa pour le Canada et arrive le 3 mars. Il vous demande de l’aider à trouver un hôtel pour sa première semaine. Répondez-lui par courriel en décrivant l’hôtel et en donnant toutes les informations utiles, notamment son emplacement et son prix.' },
    { prompt: 'Avec des amis, vous êtes allé assister à une représentation ou à un événement culturel, et cela vous a beaucoup plu. Sur votre blog, racontez le déroulement de la soirée et dites pour quelles raisons ce spectacle vous a séduit.' },
    { prompt: T3('Les relations amicales au travail.'), documents: ['Document 1 : Les amitiés entre collègues apportent beaucoup au quotidien. Elles créent une ambiance plus agréable et renforcent la cohésion de l’équipe. Quand les relations sont bonnes, la communication devient plus facile, la collaboration plus fluide et les problèmes se résolvent mieux. Sortir ensemble après le travail ou déjeuner entre collègues consolide encore ces liens.', 'Document 2 : Au travail, il faut garder un juste milieu entre relations amicales et professionnalisme. Des liens trop étroits peuvent provoquer des tensions au moment de prendre des décisions. De plus, des groupes fermés peuvent exclure certains collègues et nuire à l’esprit d’équipe. Il est donc important de fixer des limites claires.'] },
  ] } },
  { id: '2026-05-145', theme: 'L’organisation des événements sportifs', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous habitez depuis peu dans une nouvelle ville. Écrivez à votre ami(e) pour l’inviter à venir passer les vacances chez vous.' },
    { prompt: 'Rédigez un article de blog pour donner votre opinion sur la présence d’une télévision dans une chambre.' },
    { prompt: T3('L’organisation des événements sportifs.'), documents: ['Document 1 : L’État devrait prendre en charge l’organisation de grands rendez-vous sportifs, comme les Jeux olympiques, la Coupe du monde ou la Coupe d’Afrique. Ces compétitions font rayonner le pays, attirent l’attention internationale et valorisent la culture locale. Elles stimulent aussi l’économie en créant des emplois et en améliorant les infrastructures.', 'Document 2 : Organiser de tels événements coûte extrêmement cher à l’État. À mon avis, l’argent public devrait plutôt servir des priorités comme la santé et l’éducation. Beaucoup de pays hôtes ont d’ailleurs fini endettés, sans obtenir de bénéfices réels pour la population.'] },
  ] } },
  { id: '2026-05-146', theme: 'Le végétarisme en Europe', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous venez de découvrir un nouveau restaurant près de chez vous. Rédigez un courriel à un ami pour lui faire part de vos impressions sur l’endroit : décoration, accueil, prix, plats, et tout autre détail qui vous a marqué.' },
    { prompt: 'Vous avez suivi un cours de langue. Sur un forum, racontez cette expérience en précisant où elle s’est déroulée, comment elle s’est organisée, combien de temps elle a duré, puis donnez votre avis sur ce cours.' },
    { prompt: T3('Le végétarisme en Europe.'), documents: ['Document 1 : En France, les végétariens sont de plus en plus nombreux : ils seraient plus de 1,5 million. Pour Brigitte G., membre d’une association, ce choix traduit le refus d’exploiter les animaux et la volonté de les protéger. Il s’inscrit aussi souvent dans une démarche écologique, puisque l’élevage représenterait une part importante des émissions de CO2. Défense des animaux, conviction ou engagement écologique : ce sont les principales raisons avancées.', 'Document 2 : Selon une étude scientifique, le végétarisme ne serait pas forcément meilleur pour l’environnement. Des chercheurs de Carnegie-Mellon ont comparé l’empreinte carbone des fruits et légumes à celle de la viande. Leur conclusion surprend : produire et transporter une laitue pourrait générer plus d’émissions qu’un poulet. Cette recherche remet donc en question plusieurs idées largement répandues sur l’alimentation végétarienne.'] },
  ] } },
  { id: '2026-05-147', theme: 'La consommation de viande : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Votre ami Paul vous demande des nouvelles du centre de langues-cultures pour tous où vous avez suivi des cours. Répondez-lui en décrivant cet établissement : les classes, les équipements, les enseignants, etc.' },
    { prompt: 'Vous avez pris part à un pique-nique avec vos collègues. Pour le journal de l’entreprise, rédigez un article qui décrit le lieu, les plats, le temps qu’il faisait et l’ambiance générale de cette sortie.' },
    { prompt: T3('La consommation de viande : pour ou contre ?'), documents: ['Document 1 : Quentin, 45 ans : Je me suis longtemps demandé s’il était vraiment nécessaire de manger de la viande chaque jour. Finalement, j’ai réduit ma consommation de viande et de poisson. J’en mange seulement de temps en temps, au restaurant ou chez des amis, et jamais à la maison. Je me sens mieux ainsi : mon alimentation est plus équilibrée, je consomme moins de graisses et, à mon avis, c’est aussi un choix plus respectueux de la planète.', 'Document 2 : Vanessa, 24 ans : Le débat sur la viande est très actuel. Pour ma part, je ne pourrais pas m’en passer. J’aime beaucoup la cuisine de mes amis végétariens, mais chez moi, préparer des repas sans viande me paraît compliqué. Je me demande aussi si l’on peut vraiment supprimer la viande sans conséquence sur la santé : quand j’ai essayé d’en manger moins, j’étais plus fatiguée. À mon sens, il faut de tout pour rester en forme.'] },
  ] } },
  { id: '2026-05-148', theme: 'La colocation : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous aimeriez partager une journée avec votre ami(e). Écrivez-lui pour lui proposer cette sortie en précisant l’organisation prévue : l’heure, l’endroit où vous vous retrouvez et les activités envisagées.' },
    { prompt: 'À l’occasion de votre activité professionnelle, vous avez suivi une session de formation sur une journée. Votre entreprise vous demande de rédiger un texte pour vos collègues afin de raconter cette expérience. Présentez le programme et donnez votre avis sur cette journée.' },
    { prompt: T3('La colocation : pour ou contre ?'), documents: ['Document 1 : La colocation convient à ceux qui aiment partager les repas et discuter plutôt qu’être seuls devant la télévision. Elle crée de vrais moments d’échange, autour d’un dîner ou d’un jeu de société, et permet aussi de se répartir les tâches ménagères. Vivre avec d’autres ouvre l’esprit, fait découvrir d’autres modes de vie et aide à tisser des liens, tout en s’entraidant au quotidien.', 'Document 2 : La colocation n’est pas toujours facile, surtout quand on aspire à retrouver le calme après une longue journée. Il faut aussi accepter les invités de l’autre et respecter les règles du ménage, au lieu de tout faire soi-même ou de laisser tout reposer sur son colocataire. La vie à plusieurs demande donc beaucoup de tact, sauf si l’on tombe sur une perle rare.'] },
  ] } },
  { id: '2026-05-149', theme: 'Les devoirs à la maison', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous avez commandé un article sur Internet et, à la réception, vous avez constaté qu’il était abîmé. Rédigez un courriel au service clientèle pour expliquer le problème, décrire le dommage et indiquer la solution que vous souhaitez.' },
    { prompt: 'Vous êtes allé voir une exposition consacrée à l’artiste que vous aimez le plus. Rédigez un article pour raconter votre visite, en décrivant ce que vous avez découvert et les impressions que vous en avez gardées.' },
    { prompt: T3('Les devoirs à la maison.'), documents: ['Document 1 : Les devoirs à la maison aident l’enfant à devenir plus autonome, car il apprend à travailler seul après l’école. Ils peuvent aussi rapprocher parents et enfants : réciter une poésie ou faire un exercice devient souvent un vrai moment de partage. Toutefois, la journée scolaire étant déjà longue, il ne faudrait pas dépasser un quart d’heure de devoirs par soir.', 'Document 2 : J’enseigne à l’école primaire et je ne donne pas de devoirs. Pour moi, ils fatiguent et stressent les enfants. Tous les élèves n’ont pas les mêmes conditions à la maison : certaines familles manquent de temps ou de moyens pour les aider. Et si les devoirs devaient créer un lien avec l’école, bien souvent ils provoquent surtout des tensions. L’autonomie s’apprend en classe, pas à la maison.'] },
  ] } },
  { id: '2026-05-150', theme: 'Les produits faits maison', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Un(e) ami(e) vous écrit : « Je sais que tu vas dans une salle de sport. Qu’en penses-tu ? » Répondez-lui en décrivant la salle (ambiance, équipements, prix).' },
    { prompt: 'Vous avez suivi une formation, par exemple en langue ou en informatique. Sur un site Internet, racontez cette expérience en précisant le contenu des cours, les participants, les professeurs, puis dites ce que vous avez aimé ou non pendant cette formation.' },
    { prompt: T3('Les produits faits maison.'), documents: ['Document 1 : Aujourd’hui, on peut fabriquer chez soi de nombreux produits : shampooings, savons, crèmes, maquillage ou encore produits ménagers. C’est un vrai avantage, car on maîtrise mieux leur composition. Il vaut mieux choisir des ingrédients naturels, sans substances chimiques, et cette solution permet aussi de limiter les emballages et les déchets. Alors, pourquoi ne pas se lancer dans le fait maison ?', 'Document 2 : Fabriquer soi-même son savon peut sembler intéressant, mais cela comporte des risques si les ingrédients sont mal choisis ou si les règles d’hygiène ne sont pas respectées. Il faut donc bien se documenter et suivre des consignes de fabrication et de conservation très strictes. Certes, ces produits coûtent souvent moins cher, mais ils demandent aussi beaucoup de temps.'] },
  ] } },
  { id: '2026-05-151', theme: 'L’art urbain : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Un auteur va participer à une rencontre organisée par la bibliothèque de votre ville. Écrivez un message à votre ami(e) pour lui proposer de vous y accompagner.' },
    { prompt: 'Vous avez pris part à un événement appelé « La semaine du goût ». Rédigez un article de blog pour raconter cette expérience.' },
    { prompt: T3('L’art urbain : pour ou contre ?'), documents: ['Document 1 : L’art dans la rue éveille la curiosité des habitants et crée des échanges inattendus entre artistes, souvent inconnus, et passants. Dans des villes qui changent, le street art apporte de la couleur, valorise les espaces verts et participe à une meilleure qualité de vie, tout en restant attentif à l’environnement.', 'Document 2 : Pourtant, ces pratiques ne font pas l’unanimité. Les graffitis sont parfois vus comme une atteinte aux lieux publics, une nuisance visuelle, voire un signe de fracture sociale. Beaucoup les assimilent à du vandalisme, et les débats restent vifs entre artistes, autorités et riverains.'] },
  ] } },
  { id: '2026-05-152', theme: 'Les objets connectés', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous allez déménager et des amis ont proposé de vous aider. Envoyez-leur un message collectif pour leur expliquer comment l’opération va se dérouler : lieux, horaires, durée, trajet, tâches à accomplir, etc.' },
    { prompt: 'Vous participez à un concours qui offre un voyage pour deux personnes dans la ville choisie par le gagnant. Pour cela, vous rédigez un article sur « La vie de mon artiste préféré(e) ». Expliquez les raisons de votre choix et racontez le parcours de cet(te) artiste.' },
    { prompt: T3('Les objets connectés.'), documents: ['Document 1 : Les objets connectés simplifient le quotidien : ils peuvent être commandés à distance par téléphone ou via Internet, qu’il s’agisse du chauffage ou des portes. Montres et bracelets analysent aussi nos activités, comptent les pas et encouragent à bouger davantage. Ils servent même à suivre la santé et à rappeler des rendez-vous ou des médicaments.', 'Document 2 : Avec des dizaines de milliards d’objets connectés dans le monde, les risques ne sont pas négligeables. Un pirate peut prendre le contrôle d’un appareil en peu de temps. De plus, ces systèmes peuvent renseigner un voleur sur l’absence des occupants ou permettre le pilotage à distance d’une voiture.'] },
  ] } },
  { id: '2026-05-153', theme: 'La restauration rapide', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Pendant votre absence, Cédric s’occupe de votre logement et de l’extérieur. Écrivez-lui un message pour lui préciser les tâches à effectuer dans la maison et le jardin.' },
    { prompt: 'Après un voyage organisé par une agence, vous êtes mécontent(e) des services reçus. Rédigez un courriel de réclamation pour exprimer votre insatisfaction, décrire les problèmes rencontrés et demander une solution à l’agence.' },
    { prompt: T3('La restauration rapide.'), documents: ['Document 1 : Les restaurants rapides proposent des repas variés et équilibrés. Ils respectent aussi les règles d’hygiène. En plus, le client choisit lui-même les produits de son menu, ce qui lui laisse la responsabilité de ses choix.', 'Document 2 : Selon les spécialistes, fréquenter souvent un fast-food présente des risques pour la santé. On y consomme surtout des plats riches en calories, souvent les mêmes, comme les hamburgers, les frites et les boissons sucrées. L’emballage plastique génère aussi beaucoup de déchets nuisibles à l’environnement.'] },
  ] } },
  { id: '2026-05-154', theme: 'L’uniforme scolaire : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous avez envie de commencer une activité sportive et vous souhaitez le faire avec votre ami. Écrivez-lui pour lui suggérer de faire du sport ensemble.' },
    { prompt: 'Sur votre blog, racontez votre séjour d’études dans une université hors de votre pays. Présentez cette expérience et ce que vous en retenez.' },
    { prompt: T3('L’uniforme scolaire : pour ou contre ?'), documents: ['Document 1 : L’uniforme scolaire bride la personnalité des garçons, puisqu’ils ne peuvent plus choisir librement leurs vêtements. Ceux qui aiment affirmer leur style ou se distinguer par un détail vestimentaire peuvent alors se sentir frustrés, comme enfermés dans une tenue imposée.', 'Document 2 : L’uniforme renforce le sentiment d’appartenance à l’école et à la communauté des élèves. Il favorise aussi l’esprit collectif et limite les différences sociales, car il évite la comparaison des marques ou des habits coûteux. Pour les familles, cela représente souvent une économie importante.'] },
  ] } },
  { id: '2026-05-155', theme: 'Les jeux vidéo : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Envoyez un message à vos amis au sujet d’un hébergement que vous avez repéré pour vos vacances ensemble. Présentez cet hôtel en donnant des éléments comme son emplacement, son tarif et les services disponibles, puis suggérez de le retenir pour le séjour.' },
    { prompt: 'Vous venez d’occuper un poste à l’étranger. Écrivez à vos amis pour leur parler de cette découverte du monde du travail et dire ce qui vous a le plus plu.' },
    { prompt: T3('Les jeux vidéo : pour ou contre ?'), documents: ['Document 1 : Des recherches montrent que jouer aux jeux vidéo peut stimuler certaines zones du cerveau chez l’adulte. Cela peut notamment améliorer l’analyse, la prise de décision et la rapidité de réaction. Cet aspect est d’autant plus intéressant que la majorité des joueurs sont adultes, même si tous les jeux ne produisent pas les mêmes effets.', 'Document 2 : Une étude menée pendant trois ans auprès d’enfants de 8 à 17 ans montre que ceux qui jouent beaucoup aux jeux vidéo sont plus nerveux, plus stressés et parfois plus violents. Leurs résultats scolaires sont aussi moins bons. Les parents sont donc invités à surveiller et à limiter ce loisir.'] },
  ] } },
  { id: '2026-05-156', theme: 'Le bien-être au travail', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Votre ami Camille vous écrit pour vous parler de son envie de se mettre au sport. Répondez-lui en lui présentant l’activité que vous pratiquez. Précisez aussi où vous la faites, combien de temps elle dure et combien elle coûte.' },
    { prompt: 'Sur un forum, Paul et Naïma racontent qu’ils ont quitté leur vie parisienne pour ouvrir une boulangerie à Calgary. Dites ce que vous pensez de leur choix et expliquez ce que vous feriez si vous deviez vivre un changement aussi important, sur le plan personnel ou professionnel.' },
    { prompt: T3('Le bien-être au travail.'), documents: ['Document 1 : Dans mon entreprise, nous avons équipé les bureaux de tables réglables en hauteur. Chacun peut ainsi travailler debout ou assis selon ses besoins. Les salariés s’en disent ravis : ils gagnent en efficacité, notamment lors des appels téléphoniques, et l’ambiance entre collègues est devenue plus chaleureuse et plus ouverte.  Lorie, responsable', 'Document 2 : Les entreprises cherchent sans cesse à accroître la productivité, mais cela ne doit pas se faire au détriment des salariés. Personnellement, je veux accomplir mon travail pendant mes heures normales, sans être poussé à faire des heures supplémentaires. L’essentiel est de respecter le temps réel de chacun, pas seulement les objectifs de l’entreprise.  Florian, ingénieur'] },
  ] } },
  { id: '2026-05-157', theme: 'L’aide aux personnes pauvres', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Annoncez à votre ami(e) francophone que vous venez d’obtenir un nouvel emploi. Dans votre message, présentez vos missions, parlez de l’équipe avec laquelle vous travaillez et décrivez l’endroit où vous exercez.' },
    { prompt: 'Julie, 19 ans, va bientôt partir à l’étranger pour poursuivre ses études et souhaite recueillir des avis d’étudiants ayant vécu loin de chez eux. Vous avez étudié pendant un an dans un autre pays. Écrivez sur le forum pour raconter cette expérience, dire si vous l’avez appréciée et expliquer pourquoi.' },
    { prompt: T3('L’aide aux personnes pauvres.'), documents: ['Document 1 : Chaque hiver, je prends le temps de donner un peu d’argent et quelques heures aux personnes sans abri que je croise dans la rue. Pour moi, il est essentiel de ne pas rester indifférent face à la détresse. Même une petite contribution à une association ou à quelqu’un dans le besoin peut vraiment faire la différence et apporte le sentiment d’être utile.', 'Document 2 : Aider les personnes en difficulté ne se limite pas à leur donner quelques pièces. Je préfère m’investir régulièrement dans une association de quartier pour les accompagner de façon concrète. Les sans-abri ont surtout besoin d’un logement et d’un emploi afin de devenir autonomes. Donner de l’argent soulage peut-être, mais cela ne règle pas le problème de fond.'] },
  ] } },
  { id: '2026-05-158', theme: 'Vivre en colocation : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Votre ami Mehdi vient d’arriver dans votre ville et souhaite connaître les transports disponibles. Écrivez-lui un message avec les informations utiles sur les différents moyens de déplacement, les abonnements et les tarifs.' },
    { prompt: 'Rédigez un billet de blog dans lequel vous exprimez votre admiration pour une personnalité, célèbre ou non. Appuyez-vous sur des actions précises pour expliquer ce qui rend cette personne remarquable et pourquoi vous l’appréciez.' },
    { prompt: T3('Vivre en colocation : pour ou contre ?'), documents: ['Document 1 : La colocation a de vrais avantages pour ceux qui n’aiment pas vivre seuls. On partage les repas, on discute, on joue ensemble, et les tâches ménagères se répartissent entre plusieurs personnes. C’est aussi une manière de découvrir d’autres habitudes de vie, de s’ouvrir aux autres et de créer des liens solides au quotidien.', 'Document 2 : Vivre à plusieurs peut vite devenir compliqué quand on cherche le calme ou qu’on veut rester seul. Il faut aussi accepter les visites des amis des autres et respecter les règles pour le ménage. La colocation demande donc beaucoup de diplomatie, sauf si l’on tombe sur un colocataire vraiment idéal.'] },
  ] } },
  { id: '2026-05-159', theme: 'Cuisinier amateur ou cuisinier professionnel ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous avez invité votre ami Cédric à votre mariage au château de Chombony, mais il ne connaît pas ce lieu. Décrivez-lui le château, sa situation géographique et les moyens de transport pour s’y rendre.' },
    { prompt: 'Sur un forum, racontez votre parcours dans l’apprentissage d’une langue étrangère. Expliquez comment vous avez appris cette langue et ce que cette expérience vous a apporté.' },
    { prompt: T3('Cuisinier amateur ou cuisinier professionnel ?'), documents: ['Document 1 : Même si les cuisiniers amateurs peuvent réussir de très bonnes recettes, cela ne suffit pas pour devenir un vrai professionnel. Il faut maîtriser des techniques précises, avoir suivi une formation et accumulé de l’expérience. Sans ces bases, on ne peut pas prétendre exercer ce métier comme un spécialiste.', 'Document 2 : Certains passionnés de cuisine ont appris grâce à Internet et sont devenus célèbres sur les réseaux sociaux. On peut aussi citer une amatrice qui a franchi le cap du professionnalisme et qui a ensuite écrit plusieurs livres destinés aux personnes qui aiment cuisiner chez elles.'] },
  ] } },
  { id: '2026-05-160', theme: 'L’utilisation des distributeurs automatiques au sein des établissements scolaires : pour ou contre ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Votre amie Anna va passer un week-end dans votre ville. Écrivez-lui un message pour lui présenter les moyens de transport qui lui permettront de la découvrir.' },
    { prompt: 'Vous avez participé à une soirée organisée entre habitants de votre quartier. Rédigez un article de blog pour expliquer les raisons pour lesquelles cet événement vous a plu.' },
    { prompt: T3('L’utilisation des distributeurs automatiques au sein des établissements scolaires : pour ou contre ?'), documents: ['Document 1 : Je suis favorable aux distributeurs de boissons dans les lycées, car ils rendent la vie des élèves plus pratique, surtout pendant les pauses courtes. S’ils sont bien contrôlés, ils peuvent proposer des boissons plus saines, comme de l’eau ou des jus sans sucre ajouté. En plus, ils peuvent rapporter de l’argent à l’établissement pour améliorer les équipements ou les projets scolaires.', 'Document 2 : Je m’oppose à l’installation de distributeurs dans les lycées, car je crains leurs effets sur la santé des élèves. Ils proposent souvent des sodas et des boissons trop sucrées, qui favorisent l’obésité et d’autres maladies comme le diabète. Même certains jus contiennent beaucoup de sucre, alors que l’école devrait encourager de meilleures habitudes alimentaires.'] },
  ] } },
  { id: '2026-05-161', theme: 'Voyager seul ou accompagné ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Rédigez une lettre à votre ami pour lui proposer de venir à un festival de musique organisé dans votre ville. Indiquez les informations essentielles, par exemple l’endroit, le moment, les chanteurs ou groupes présents, ainsi que les aspects pratiques utiles.' },
    { prompt: 'Sur votre blog, racontez votre dernière sortie au restaurant : précisez l’endroit, les plats, le service et les autres détails marquants. Expliquez ce que vous avez vécu et ce qui vous a particulièrement plu.' },
    { prompt: T3('Voyager seul ou accompagné ?'), documents: ['Document 1 : Partir seul permet de vivre un voyage à sa manière. On choisit son itinéraire, ses activités et son rythme sans devoir s’adapter à un groupe. Cette liberté favorise aussi les échanges avec les habitants ou d’autres voyageurs, ce qui enrichit l’expérience et aide à mieux sortir de sa routine.', 'Document 2 : Le voyage en solitaire a ses atouts, mais il comporte aussi des limites. La solitude peut peser, et l’absence de compagnon rend plus difficile la gestion des imprévus. Pour certaines excursions, notamment dans des lieux isolés ou difficiles, être plusieurs est aussi plus rassurant. Partager le voyage reste un vrai plaisir.'] },
  ] } },
  { id: '2026-05-162', theme: 'Les animaux de compagnie pour les enfants', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous avez publié une annonce pour louer votre appartement à Montréal. Rédigez un courriel à une personne intéressée en lui donnant les informations essentielles sur le logement : caractéristiques, montant du loyer, quartier, etc.' },
    { prompt: 'Vous suivez depuis peu des cours à l’Université de Montréal. Écrivez à votre ami pour raconter vos premiers jours dans cet établissement et donner votre avis sur l’université ainsi que sur les enseignements.' },
    { prompt: T3('Les animaux de compagnie pour les enfants.'), documents: ['Document 1 : De nombreux spécialistes estiment qu’un animal de compagnie peut être très bénéfique pour un enfant. S’il est seul, il trouve en lui un véritable compagnon et se sent moins isolé. Il apprend aussi à prendre confiance en lui, à respecter un être vivant et à devenir plus autonome en sa présence.', 'Document 2 : Beaucoup d’enfants rêvent d’avoir un chien ou un chat, mais les parents doivent réfléchir avant de dire oui. Adopter un animal, c’est accueillir un nouveau membre dans la famille pour longtemps. Cela demande de l’argent, du temps et beaucoup de responsabilité : un animal n’est pas un jouet dont on se débarrasse.'] },
  ] } },
  { id: '2026-05-163', theme: 'Le vélo en ville', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Écrivez à votre ami(e) pour lui présenter l’organisation de vos prochaines vacances. Vous précisez où vous allez, à quel moment et ce que vous comptez faire sur place.' },
    { prompt: 'Rédigez un billet de blog consacré à une manifestation récente à laquelle vous avez pris part, comme un festival, une célébration ou une soirée.' },
    { prompt: T3('Le vélo en ville.'), documents: ['Document 1 : On associe souvent le vélo au sport ou aux loisirs, alors qu’il s’agit aussi d’un excellent moyen de transport. En ville, il permet de se déplacer rapidement tout en évitant les embouteillages. Aller travailler à bicyclette, c’est aussi faire de l’exercice au quotidien sans perdre de temps.', 'Document 2 : Se déplacer à vélo en ville peut être risqué. Entre la circulation dense, le non-respect du code de la route et le manque de pistes cyclables, les accidents sont possibles. À cela s’ajoutent les gaz d’échappement, qui peuvent nuire à la santé.'] },
  ] } },
  { id: '2026-05-164', theme: 'L’école à domicile', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Après un entretien pour un poste, vous écrivez à votre ami(e) pour lui raconter comment cela s’est passé. Donnez des détails sur l’entreprise, la rémunération et la nature du travail.' },
    { prompt: 'Sur le forum d’Air Tropiques, participez au concours « Gagnez deux billets pour la destination de votre choix ». Racontez le voyage qui vous a le plus marqué en donnant des précisions comme la période, le lieu et les activités, puis dites pourquoi ce séjour a eu une importance particulière pour vous.' },
    { prompt: T3('L’école à domicile.'), documents: ['Document 1 : L’école à la maison séduit de nombreux parents pour plusieurs raisons. Elle permet un accompagnement plus personnalisé, avec davantage de temps sur les difficultés de l’enfant ou des activités éducatives adaptées. L’élève avance à son rythme, approfondit ce qui l’intéresse et échappe à la pression du groupe comme aux notes démotivantes.', 'Document 2 : Faire le choix de l’instruction à domicile demande beaucoup d’efforts et comporte des contraintes. Cela exige du temps, de l’organisation et un budget important, car les familles doivent payer le matériel, les livres et les sorties. En plus, l’enfant voit moins ses camarades et interagit moins avec d’autres jeunes qu’à l’école.'] },
  ] } },
  { id: '2026-05-165', theme: 'Courses alimentaires : local ou supermarché ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous recevez un message d’un(e) ami(e) avant une journée au parc de loisirs : il ou elle a hâte de vous voir et vous demande quelles activités seront possibles. Répondez-lui.' },
    { prompt: 'Votre ville a accueilli un Salon du livre. Vous y êtes allé(e) et avez assisté à des conférences, des expositions et des rencontres avec des auteurs. Écrivez à vos amis pour raconter l’événement et donner vos impressions.' },
    { prompt: T3('Courses alimentaires : local ou supermarché ?'), documents: ['Document 1 : Je fais mes achats alimentaires tout près de chez moi, souvent directement chez les producteurs. J’aime rencontrer les personnes qui cultivent ou fabriquent ce que j’achète. C’est vrai que je paie un peu plus cher, mais la qualité est meilleure et je sais d’où viennent les produits. Pour moi, consommer local est essentiel.', 'Document 2 : Pour mes courses, je vais toujours au supermarché, car c’est le plus simple au quotidien. J’habite en centre-ville, donc je gagne du temps, surtout avec des enfants. Je trouve tout au même endroit et je profite souvent de réductions. J’aime acheter vite et dépenser moins pour garder de l’argent pour mes loisirs.'] },
  ] } },
  { id: '2026-05-166', theme: 'Vivre chez ses parents : avantage ou inconvénient ?', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous partez en voyage et un ami doit rester dans votre appartement pendant votre absence. Envoyez-lui un message pour lui présenter le logement : situation de l’immeuble, caractéristiques de l’appartement et modalités d’accès.' },
    { prompt: 'Rédigez un billet de blog consacré au souvenir de voyage qui vous a laissé la meilleure impression.' },
    { prompt: T3('Vivre chez ses parents : avantage ou inconvénient ?'), documents: ['Document 1 : Vivre chez ses parents pendant les études peut être très avantageux. Cela permet d’économiser le loyer et les dépenses alimentaires, tout en profitant de repas maison, d’un logement propre et d’un certain confort. Plusieurs jeunes témoignent aussi que cette solution aide à mettre de l’argent de côté pour l’avenir, surtout lorsque le coût du logement est trop élevé.', 'Document 2 : Cette vie en famille a aussi ses limites, car elle réduit l’autonomie. Quand on habite encore avec ses parents, on dépend souvent de leurs décisions et on manque d’intimité. Un homme de 25 ans explique qu’après avoir perdu son emploi, il a dû retourner chez ses parents et a eu l’impression de reculer dans sa vie.'] },
  ] } },
  { id: '2026-05-167', theme: 'La lecture chez les enfants', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Votre ami souhaite commencer une activité sportive. Envoyez-lui un message pour lui recommander une salle de sport de votre quartier, en précisant son emplacement, ses tarifs et les activités proposées.' },
    { prompt: 'Vous avez vécu un événement dont vous vous souvenez encore fortement, par exemple un anniversaire ou un mariage. Racontez ce moment marquant.' },
    { prompt: T3('La lecture chez les enfants.'), documents: ['Document 1 : Avec les écrans, beaucoup d’enfants se tournent davantage vers les jeux vidéo, les réseaux sociaux ou d’autres loisirs que vers les livres. Certains pensent donc qu’il ne faut pas les obliger à lire : le plaisir de lire ne se force pas, et chacun devrait pouvoir choisir ses lectures, sans contrainte.', 'Document 2 : La lecture se transmet souvent au sein de la famille. Même si les enfants passent plus de temps sur les tablettes et les smartphones, lire régulièrement enrichit leur vocabulaire, améliore leur concentration et leur écoute. Les parents peuvent aussi partager ce moment avec eux quelques minutes par jour, ce qui renforce leur complicité.'] },
  ] } },
  { id: '2026-05-168', theme: 'L’urbanisation des villes', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Membre d’un club sportif, vous avez gagné une épreuve importante. Dans un courriel à vos amis, racontez la compétition et annoncez cette victoire.' },
    { prompt: 'Le site « colocation.com » cherche des témoignages sur la vie en colocation. Vous avez déjà partagé un logement avec des amis. Racontez cette expérience aux lecteurs du site et donnez votre avis sur ce mode d’habitation.' },
    { prompt: T3('L’urbanisation des villes.'), documents: ['Document 1 : Aujourd’hui, les villes s’étendent sans cesse, et cette croissance pèse lourdement sur l’environnement. Plus elles grandissent, plus elles détruisent la nature, notamment par la déforestation. Or les arbres et les espaces verts jouent un rôle essentiel, car ils absorbent une grande quantité de carbone. Les supprimer pour construire routes et immeubles aggrave donc le problème.', 'Document 2 : La plupart des êtres humains vivent désormais en milieu urbain, ce qui fait de la ville un enjeu écologique majeur. On critique souvent son organisation, jugée peu respectueuse de l’environnement. Pourtant, il faut nuancer : un habitant des villes consomme souvent moins d’énergie qu’une personne vivant à la campagne.'] },
  ] } },
  { id: '2026-05-169', theme: 'Les nouvelles technologies et les enfants', created_at: '2026-05-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 5, source: 'candidats', tasks: [
    { prompt: 'Vous préparez votre anniversaire. Écrivez à vos amis pour les convier et expliquez-leur le programme prévu pour la fête.' },
    { prompt: 'Sous une publication Facebook consacrée aux études dans un autre pays, vous laissez un commentaire pour présenter les points positifs et les difficultés de cette expérience.' },
    { prompt: T3('Les nouvelles technologies et les enfants.'), documents: ['Document 1 : À l’école primaire, la technologie peut être utile aux enfants. Elle leur permet de regarder des vidéos en lien avec leurs cours ou de jouer à des jeux éducatifs qui renforcent leurs progrès en mathématiques, en lecture ou en écriture au clavier. Bien utilisée, elle peut donc soutenir leurs apprentissages de façon agréable.', 'Document 2 : Les nouvelles technologies poussent souvent les enfants à rester assis pendant de longues périodes, ce qui inquiète beaucoup de parents. Elles réduisent aussi les occasions de jouer librement, de parler avec d’autres enfants et de faire de l’exercice. Pour limiter cette dépendance aux écrans, il est possible de proposer des activités plus actives et plus ludiques.'] },
  ] } },
  { id: '2026-04-100', theme: 'Vivre chez ses parents : pour ou contre ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Vous allez partir en voyage et confiez votre appartement à un ami qui souhaite y séjourner pendant votre absence. Envoyez-lui un message pour lui décrire le logement : l’immeuble, l’appartement et les conditions d’accès.' },
    { prompt: 'Rédigez un article de blog dans lequel vous racontez le voyage dont vous gardez le meilleur souvenir.' },
    { prompt: T3('Vivre chez ses parents : pour ou contre ?'), documents: ['Document 1 : Habiter chez ses parents pendant les études présente plusieurs atouts : on économise le loyer et les repas, on profite de plats maison et on garde une certaine tranquillité. En plus, les jeunes peuvent mettre de côté leur argent pour leurs projets. Plusieurs témoignages soulignent aussi le confort du quotidien et l’absence de solitude.', 'Document 2 : Cette solution limite fortement l’autonomie. Quand on vit encore chez ses parents, ce sont eux qui décident et l’on perd une partie de son intimité. Un homme de 25 ans raconte qu’après un licenciement, il a dû rentrer chez lui et a eu l’impression de reculer dans sa vie.'] },
  ] } },
  { id: '2026-04-101', theme: 'La lecture pour les enfants', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Votre ami souhaite commencer une activité physique. Envoyez-lui un message pour lui suggérer une salle de sport de votre quartier, avec des informations sur son emplacement, ses tarifs et les activités proposées.' },
    { prompt: 'Vous avez assisté à un moment important dont vous gardez un souvenir fort, comme un anniversaire ou un mariage. Racontez cet événement.' },
    { prompt: T3('La lecture pour les enfants.'), documents: ['Document 1 : Avec les écrans et les loisirs numériques omniprésents, beaucoup d’enfants délaissent les livres au profit des jeux vidéo, du sport ou de la musique. Selon cette opinion, il ne sert à rien d’imposer la lecture : le plaisir de lire doit naître librement, sans contrainte, car on ne peut pas forcer un enfant à aimer un livre.', 'Document 2 : La lecture se transmet d’une génération à l’autre et reste essentielle, même si les enfants ont aujourd’hui surtout des smartphones et des tablettes. Lire régulièrement aide à enrichir le langage, à mieux se concentrer et à écouter davantage. Dix minutes de lecture partagée chaque jour peuvent aussi renforcer le lien entre parents et enfants.'] },
  ] } },
  { id: '2026-04-102', theme: 'Le grossissement des villes', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Membre d’un club sportif, vous avez gagné une épreuve importante. Dans un courriel à vos amis, racontez la compétition et annoncez cette victoire.' },
    { prompt: 'Le site « colocation.com » invite ses lecteurs à partager des récits personnels sur la vie en logement partagé. Vous avez vécu avec des amis dans le même appartement : racontez cette expérience aux utilisateurs du site et dites ce que vous pensez de cette façon d’habiter.' },
    { prompt: T3('Le grossissement des villes.'), documents: ['Document 1 : L’extension des villes a des conséquences graves sur l’environnement. Plus elles s’agrandissent, plus elles détruisent la nature et aggravent les effets sur l’homme. La déforestation en est un exemple majeur, puisqu’elle fait disparaître des espaces verts qui absorbent le carbone et permettaient de limiter la pollution.', 'Document 2 : Comme une grande partie de la population mondiale vit en milieu urbain, la question écologique des villes est centrale. On les accuse souvent d’être peu respectueuses de l’environnement, mais l’image est parfois trompeuse : un citadin consomme souvent moins d’énergie qu’un habitant de la campagne.'] },
  ] } },
  { id: '2026-04-103', theme: 'Les nouvelles technologies pour les enfants', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Envoyez à vos amis un message dans lequel vous les conviez à fêter votre anniversaire et où vous expliquez le programme prévu pour cette soirée.' },
    { prompt: 'Sous une publication Facebook qui parle des études hors de son pays, écrivez un commentaire en présentant les points positifs et les difficultés de cette aventure.' },
    { prompt: T3('Les nouvelles technologies pour les enfants.'), documents: ['Document 1 : À l’école primaire, la technologie peut aider les enfants à revoir des notions vues en classe grâce à des vidéos ou à des jeux éducatifs. Elle peut aussi améliorer leurs compétences en mathématiques, leur compréhension en lecture et leur rapidité en saisie au clavier.', 'Document 2 : Les nouvelles technologies encouragent les enfants à rester assis trop longtemps, ce qui inquiète de nombreux parents. Elles réduisent le jeu libre, les échanges en face à face et l’activité physique. Il existe pourtant des alternatives ludiques pour les inciter à ranger leurs appareils.'] },
  ] } },
  { id: '2026-04-104', theme: 'La sieste au travail', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Envoyez un message à vos amis pour leur suggérer de passer un week-end avec vous autour d’activités sportives.' },
    { prompt: 'Sur un forum, écrivez un billet de blog pour expliquer les raisons qui vous ont poussé à modifier votre alimentation.' },
    { prompt: T3('La sieste au travail.'), documents: ['Document 1 : La sieste au travail peut être bénéfique pour les salariés comme pour les entreprises. Un court repos améliore la concentration, la vigilance, l’humeur et la santé, tout en réduisant le stress. Elle peut aussi limiter la fatigue et les accidents, ce qui représente un avantage économique pour l’employeur.', 'Document 2 : Malgré ses bienfaits, la sieste n’est pas facile à organiser dans toutes les entreprises. Les contraintes de budget, d’espace ou de règlement intérieur peuvent freiner sa mise en place. Certains employés ne sont d’ailleurs pas à l’aise avec cette pratique, ce qui oblige les employeurs à chercher des solutions adaptées.'] },
  ] } },
  { id: '2026-04-105', theme: 'L’emploi des jeunes : diplôme ou expérience ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Vous êtes sur le point de changer de logement et avez repéré un appartement qui vous intéresse. Rédigez un message à un ami pour lui présenter le bien : combien il comprend de pièces, où il se situe et combien il coûte.' },
    { prompt: 'Un festival de musique gratuit a été organisé dans votre ville. Vous y êtes allé avec un ami et vous voulez raconter cet événement dans un article de blog, en décrivant ce que vous avez vu et vécu.' },
    { prompt: T3('L’emploi des jeunes : diplôme ou expérience ?'), documents: ['Document 1 : Beaucoup de jeunes sortant de l’université peinent à décrocher un poste. Sur le marché du travail, leurs diplômes sont souvent jugés insuffisants face au manque d’expérience, sans compter que leur âge peut jouer contre eux. Plus de six diplômés sur dix restent sans emploi un an après leurs études. Il devient donc nécessaire de mieux valoriser les parcours universitaires et de soutenir la croissance.', 'Document 2 : Certains exemples de grands entrepreneurs ayant réussi sans études supérieures font croire qu’un bon esprit suffit pour lancer une entreprise. D’après plusieurs dirigeants, l’université pousserait surtout à suivre des modèles établis et freinerait l’imagination. Pour créer son activité, mieux vaudrait apprendre seul et acquérir de l’expérience sur le terrain, plutôt que dépendre d’un cadre académique.'] },
  ] } },
  { id: '2026-04-106', theme: 'La ville ou la campagne ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Vous avez besoin d’aide pour trouver un logement et vous écrivez à un ami francophone. Indiquez-lui le type de logement recherché, votre budget et la date à laquelle vous devez emménager.' },
    { prompt: 'Votre établissement prépare une journée d’accueil pour les nouveaux étudiants francophones. Envoyez-leur un courriel avec toutes les indications utiles pour que cette journée se déroule correctement.' },
    { prompt: T3('La ville ou la campagne ?'), documents: ['Document 1 : Vivre en ville permet de se divertir facilement : cinéma, restaurants, boutiques, musées, théâtre ou opéra sont accessibles sans longs déplacements. Tout est proche, ce qui simplifie le quotidien et évite de perdre du temps en trajets. Pour ceux qui aiment les sorties et la vie culturelle, la ville offre une grande variété d’activités à portée de main.', 'Document 2 : J’ai choisi la campagne pour retrouver le calme et me rapprocher de la nature. Je reçois désormais mes amis chez moi, sur la terrasse, ou autour d’un barbecue dans le jardin. J’y ai aussi trouvé un vrai avantage financier : avec le même budget, j’ai pu acheter une grande maison avec jardin, alors qu’en ville je n’aurais eu qu’un petit appartement.'] },
  ] } },
  { id: '2026-04-107', theme: 'La publicité destinée aux enfants : utile ou dangereuse ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Vous cherchez une personne pour partager votre grand logement. Rédigez une annonce où vous présentez la colocation que vous offrez et les principales qualités de l’appartement.' },
    { prompt: 'Une compagnie théâtrale est venue jouer dans votre ville et vous avez vu une représentation. Écrivez un article de blog pour raconter et décrire cette sortie.' },
    { prompt: T3('La publicité destinée aux enfants : utile ou dangereuse ?'), documents: ['Document 1 : Les enfants sont exposés en permanence à la publicité, à la télévision, dans les magazines ou sur Internet, souvent à des endroits où ils sont particulièrement influençables. Les marques ciblent surtout les produits alimentaires, les jouets et les jeux vidéo. Résultat : leurs envies de consommation et leurs demandes auprès des parents peuvent être fortement orientées par ces messages.', 'Document 2 : Une étude scientifique montre que les enfants comprennent encore mal les procédés publicitaires et qu’ils identifient en général l’intention de convaincre. Cependant, l’éducation donnée à la maison ainsi que l’environnement social et culturel influencent davantage leurs achats que la publicité elle-même. Son rôle ne doit donc pas être surestimé.'] },
  ] } },
  { id: '2026-04-108', theme: 'Les vêtements de marque chez les jeunes', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Lucas vous écrit pour connaître les nouveaux locaux de votre entreprise. Répondez-lui en précisant l’emplacement, l’agencement des bureaux et les équipements disponibles.' },
    { prompt: 'Vous avez participé à une manifestation intitulée « Une semaine sans voiture ». Racontez le déroulement de l’événement, les lieux concernés, les activités proposées et donnez votre avis sur cette initiative.' },
    { prompt: T3('Les vêtements de marque chez les jeunes.'), documents: ['Document 1 : Les vêtements de marque occupent une place importante chez les enfants et les adolescents, car ils leur servent à affirmer leur personnalité et à se sentir intégrés à un groupe. Chez les jeunes, cette envie est très forte. Les plus petits aiment aussi porter des habits avec leurs personnages préférés ou des logos qu’ils apprécient.', 'Document 2 : Les enfants grandissent rapidement, ce qui rend les vêtements trop petits en peu de temps. À cela s’ajoute le fait qu’ils les abîment vite en courant dehors, en jouant avec leurs camarades ou en allant à l’aire de jeux. Les habits finissent donc souvent tachés, usés ou troués très rapidement.'] },
  ] } },
  { id: '2026-04-109', theme: 'L’uniforme scolaire : avantage ou contrainte ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez inviter un(e) ami(e) à pratiquer une activité sportive avec vous. Rédigez un message en présentant votre idée : type de sport, lieu, matériel nécessaire et autres détails utiles.' },
    { prompt: 'Après avoir passé six mois dans une université à l’étranger, vous envoyez un message à vos amis pour raconter ce séjour et expliquer ce que vous y avez particulièrement apprécié. Écrivez entre 120 et 150 mots.' },
    { prompt: T3('L’uniforme scolaire : avantage ou contrainte ?'), documents: ['Document 1 : Les goûts des enfants sont fortement influencés par la mode, ce qui oblige souvent les parents à acheter sans cesse de nouveaux vêtements. L’uniforme permettrait de réduire ces dépenses. Il renforcerait aussi le sentiment d’appartenance à l’école et atténuerait les différences sociales ainsi que les jugements liés à l’apparence. Pour ces raisons, il présente plusieurs avantages.', 'Document 2 : Au Québec, l’uniforme scolaire gagne du terrain, même dans des écoles publiques. Pourtant, beaucoup d’adolescents le contestent : ils le trouvent peu confortable, peu esthétique et trop chaud en été. Ils estiment aussi qu’une tenue identique pour tous empêche d’exprimer leur style et leur personnalité.'] },
  ] } },
  { id: '2026-04-110', theme: 'Les caméras de surveillance à l’école : une bonne idée ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Vous voulez organiser votre anniversaire dans un restaurant et inviter vos amis. Rédigez-leur un courriel pour leur donner toutes les informations utiles : lieu, date, heures, menu et prix. Demandez-leur aussi de vous répondre.' },
    { prompt: 'Vous avez quitté la ville pour vivre désormais à la campagne. Sur un forum, expliquez les raisons de ce déménagement et décrivez ce que cette nouvelle vie vous apporte.' },
    { prompt: T3('Les caméras de surveillance à l’école : une bonne idée ?'), documents: ['Document 1 : Dans l’école montréalaise où j’enseigne, des caméras ont été installées un peu partout. Elles rappellent aux élèves que tout comportement violent peut être sanctionné. Parents, enseignants et majorité des jeunes y sont favorables. Les familles se sentent plus tranquilles, et les professeurs peuvent travailler dans de meilleures conditions. Quelques élèves dénoncent toutefois une atteinte à leur vie privée.', 'Document 2 : Je suis opposé à l’installation de caméras dans les écoles de Montréal. Là où ce système existe, les résultats ne sont pas convaincants. Les appareils étant très visibles, des intrus peuvent contourner la surveillance. Pour améliorer la discipline, il vaut mieux renforcer le dialogue entre élèves, direction et enseignants, puis faire respecter clairement le règlement intérieur.'] },
  ] } },
  { id: '2026-04-111', theme: 'Les locations de courte durée', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez assister au concert de votre artiste préféré(e) et proposez à un(e) ami(e) de vous y accompagner. Écrivez-lui un courriel avec les renseignements nécessaires : date, prix, lieu, artiste et durée du spectacle.' },
    { prompt: 'Les professeurs de l’école de votre quartier veulent faire découvrir plusieurs métiers aux élèves. Vous souhaitez participer à cette initiative pour parler de votre travail. Écrivez-leur pour présenter votre profession, vos activités et vos collègues, puis expliquez ce qui rend ce métier intéressant pour vous.' },
    { prompt: T3('Les locations de courte durée.'), documents: ['Document 1 : De plus en plus de personnes louent une chambre ou leur logement à des voyageurs, afin d’obtenir un revenu complémentaire ou de faire de belles rencontres. Ce principe repose sur la confiance. Les visiteurs paient souvent moins cher qu’à l’hôtel, peuvent parfois cuisiner sur place et bénéficient aussi des conseils de l’hôte pour découvrir la ville.', 'Document 2 : L’an dernier, j’ai loué mon appartement à un couple de touristes pour une semaine à Marseille, et cela m’a laissé un très mauvais souvenir. Ils sont arrivés en retard, ont fait du bruit et ont dérangé le voisinage. En partant, ils ont laissé la vaisselle sale et des déchets partout. J’ai mis trois heures à tout nettoyer. Julien, 38 ans'] },
  ] } },
  { id: '2026-04-112', theme: 'Les vols à bas prix', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Envoyez un courriel à vos amis pour les convier à la fête surprise organisée pour votre meilleur(e) ami(e). Précisez l’endroit, le jour et l’heure.' },
    { prompt: 'Vous avez pris part à une brocante dans votre ville, pour acheter ou vendre des objets déjà utilisés. Sur votre blog personnel, racontez pourquoi cette expérience vous a plu.' },
    { prompt: T3('Les vols à bas prix.'), documents: ['Document 1 : Je voyage souvent avec des compagnies aériennes à bas prix. Leurs tarifs sont bien inférieurs à ceux des compagnies classiques, et il m’est arrivé de payer moins cher qu’en train ou en voiture. En contrepartie, il n’y a ni repas ni boissons à bord. À mon avis, ce type de vol n’est pas adapté aux longs trajets.', 'Document 2 : J’ai décidé d’abandonner les compagnies aériennes à bas prix. Après réflexion, plusieurs points m’ont convaincu : sièges inconfortables, conditions de travail difficiles pour le personnel et avions trop anciens, ce qui soulève des questions de sécurité. Pour certains déplacements, je préfère désormais la voiture ou le train, surtout pour admirer le paysage. Pour les longues distances, mieux vaut choisir une compagnie régulière.'] },
  ] } },
  { id: '2026-04-113', theme: 'Faire ses courses : petits commerces ou supermarchés ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez transformer l’ambiance de votre appartement en changeant la peinture, les meubles ou les objets de décoration. Écrivez à un(e) ami(e) pour présenter votre idée et lui demander un coup de main.' },
    { prompt: 'Vous avez participé à l’évènement « École de musique ! Cours gratuits, concerts, jeux. Rendez-vous vendredi à partir de 9 heures ». Écrivez à vos amis pour raconter cette journée et dire ce que vous en pensez.' },
    { prompt: T3('Faire ses courses : petits commerces ou supermarchés ?'), documents: ['Document 1 : Le supermarché est très pratique : on y trouve facilement une grande diversité de produits, tout au même endroit. Avec le parking et les allées bien organisées, on peut acheter fruits, légumes, fromages, viandes, boissons et bien plus encore. En plus, plusieurs marques sont proposées pour un même article, avec souvent des promotions intéressantes.', 'Document 2 : Le défi « Février sans supermarché » a été lancé pour freiner la domination des grandes surfaces et aider les petits commerces à survivre. Pendant un mois, il s’agit de faire ses achats dans les épiceries de quartier. Les clients y gagnent des produits plus frais, souvent de meilleure qualité, et profitent aussi d’un moment convivial avec les voisins.'] },
  ] } },
  { id: '2026-04-114', theme: 'La sévérité des parents envers les enfants', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Mathieu cherche un vélo peu coûteux et en bon état, et il demande qu’on le contacte par courriel à mathieu@gmail.com. Vous avez justement un vélo à vendre : écrivez-lui un message pour le décrire, indiquer votre prix et fixer un moment pour qu’il vienne l’essayer.' },
    { prompt: 'Vous avez passé une journée à la campagne avec vos amis. De retour chez vous, publiez un message sur votre forum pour raconter comment la journée s’est déroulée et ce que vous avez particulièrement apprécié : activités, lieu, animaux, etc.' },
    { prompt: T3('La sévérité des parents envers les enfants.'), documents: ['Document 1 : J’ai bientôt 22 ans et je vis encore chez mes parents, qui restent très stricts avec moi malgré mon âge. Quand j’étais mineure, je ne pouvais ni dormir dehors ni rentrer après 21 heures. Aujourd’hui, j’ai plus de liberté, mais ma mère continue de m’appeler sans cesse jusqu’à mon retour.', 'Document 2 : Certains parents redoutent d’être trop durs avec leurs enfants. Ils pensent qu’une autorité excessive peut freiner leur épanouissement et les empêcher de développer leur personnalité. Pourtant, tout accepter par amour n’est pas toujours bénéfique : à l’âge adulte, il faut apprendre à vivre avec des règles et à respecter la vie en société.'] },
  ] } },
  { id: '2026-04-115', theme: 'La chasse aux animaux : pour ou contre ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Écrivez à votre ami(e) pour l’inviter à venir passer ses congés dans votre ville, en indiquant les sites et lieux à découvrir.' },
    { prompt: 'Vous avez gagné un concours offrant un séjour de deux semaines dans votre ville préférée. Le thème est « Mon artiste préféré ». Rédigez un article de blog pour présenter cet artiste et expliquer pourquoi vous l’appréciez.' },
    { prompt: T3('La chasse aux animaux : pour ou contre ?'), documents: ['Document 1 : Je ne comprends pas qu’on puisse éprouver du plaisir à abattre des animaux. On ne peut pas se dire amoureux de la nature tout en participant à sa destruction, comme le souligne Gala, 29 ans.', 'Document 2 : La chasse répond à plusieurs objectifs : se nourrir, vendre, gérer la faune, protéger les biens, s’entraîner, se divertir ou encore rechercher du prestige, rappelle David, journaliste à la FRM.'] },
  ] } },
  { id: '2026-04-116', theme: 'Les produits faits maison : pour ou contre ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Un(e) ami(e) vous écrit qu’il ou elle va dans une salle de sport très agréable et vous demande des détails. Répondez-lui en lui donnant des informations sur cette salle.' },
    { prompt: 'Sur un forum, vous avez lu un débat sur les formations en ligne. Racontez votre expérience, qu’il s’agisse d’un cours de langue ou d’une formation professionnelle, et dites ce que vous avez aimé et moins aimé.' },
    { prompt: T3('Les produits faits maison : pour ou contre ?'), documents: ['Document 1 : Préparer soi-même des produits bio à la maison permet de choisir exactement les ingrédients et d’obtenir des solutions plus saines, adaptées à ses besoins. C’est aussi un moyen de limiter les déchets plastiques grâce à des contenants réutilisables. À long terme, cela peut faire économiser de l’argent et développer des compétences créatives.', 'Document 2 : En revanche, fabriquer ses produits biologiques chez soi n’est pas sans danger. Une mauvaise recette peut donner un résultat inefficace ou irritant, et la préparation demande du temps ainsi qu’un certain effort. Sans garantie de stabilité ni de sécurité, le risque de contamination augmente, tout comme le coût de départ des ingrédients de qualité.'] },
  ] } },
  { id: '2026-04-117', theme: 'Caméras de surveillance : pour ou contre ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Vous allez vous installer à Nice, en France. Écrivez un message à une agence immobilière pour préciser les critères de votre recherche : surface, budget, nombre de pièces, et autres informations utiles.' },
    { prompt: 'Vous venez de débuter dans une école de langues. Dans un message à vos amis, racontez votre première semaine et donnez votre avis sur l’établissement ainsi que sur les cours.' },
    { prompt: T3('Caméras de surveillance : pour ou contre ?'), documents: ['Document 1 : Dans les villes françaises, les caméras de surveillance se multiplient. Beaucoup de citoyens y voient un moyen rassurant de renforcer la sécurité : un sondage indique que 75 % des Français y sont favorables. Ils acceptent d’être filmés dans les lieux publics, comme la rue, les commerces ou les transports, mais refusent cette surveillance sur leur lieu de travail.', 'Document 2 : D’autres études montrent au contraire que la vidéosurveillance coûte cher et reste peu efficace. Comme les caméras sont visibles, elles n’empêchent pas vraiment les vols, la drogue ou les violences. En plus, il faut beaucoup de personnel pour exploiter les images : une étude allemande parle de sept personnes par caméra.'] },
  ] } },
  { id: '2026-04-118', theme: 'Livraison des repas au bureau : pour ou contre ?', created_at: '2026-04-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 4, source: 'candidats', tasks: [
    { prompt: 'Un(e) ami(e) souhaite explorer l’endroit où vous vivez. Écrivez-lui un message dans lequel vous lui suggérez plusieurs lieux intéressants à aller voir.' },
    { prompt: 'Rédigez pour votre blog un billet sur la séance de sport que vous avez suivie dans une salle. Vous y racontez votre expérience et vous donnez aussi votre avis sur cet établissement.' },
    { prompt: T3('Livraison des repas au bureau : pour ou contre ?'), documents: ['Document 1 : Faire livrer les repas au bureau fait gagner du temps aux employés, qui n’ont plus besoin de sortir loin pour manger. Cela leur permet aussi d’économiser de l’énergie et de rester plus efficaces. Le repas peut attendre la fin d’une réunion ou d’une conférence, ce qui en fait une solution adaptée aux entreprises très actives.', 'Document 2 : Cette pratique a aussi ses limites. Avec son succès, les livreurs peuvent être débordés, ce qui crée de l’attente et du stress. De leur côté, les salariés qui ne quittent pas leur bureau pour manger risquent la fatigue. Il est donc préférable de prévoir de vraies pauses pendant les journées de travail chargées.'] },
  ] } },
  { id: '2026-03-100', theme: 'Cuisinier amateur ou professionnel ?', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Vous avez invité votre ami Cédric à votre mariage au Château de Chombony, mais il ne connaît pas ce lieu. Décrivez-lui l’endroit, sa localisation et les moyens d’accès, afin qu’il puisse s’y rendre facilement.' },
    { prompt: 'Sur votre blog, racontez comment vous avez appris une langue étrangère. Expliquez votre parcours et les difficultés ou les progrès que vous avez rencontrés.' },
    { prompt: T3('Cuisinier amateur ou professionnel ?'), documents: ['Document 1 : Les cuisiniers amateurs réussissent parfois de belles recettes, mais cela ne suffit pas pour exercer ce métier. Pour devenir un véritable chef, il faut une solide formation, de la technique et surtout de l’expérience. Sans apprentissage sérieux, on reste au niveau du loisir, même avec du talent.', 'Document 2 : On voit aujourd’hui des cuisiniers formés grâce à internet qui rencontrent un grand succès sur les réseaux sociaux. Une ancienne passionnée, devenue professionnelle, a même publié plusieurs ouvrages destinés aux personnes qui aiment cuisiner chez elles. Son parcours montre qu’on peut partir de peu et aller très loin.'] },
  ] } },
  { id: '2026-03-101', theme: 'Vivre en colocation', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Votre ami Mehdi vient de s’installer dans votre ville et veut obtenir des informations sur les transports. Écrivez-lui un message en lui indiquant les principaux moyens de déplacement, les abonnements possibles et les tarifs.' },
    { prompt: 'Rédigez un article de blog pour parler d’une personne que vous admirez, célèbre ou non. Présentez ses actions marquantes et expliquez pourquoi elle vous inspire.' },
    { prompt: T3('Vivre en colocation.'), documents: ['Document 1 : La colocation présente de vrais atouts. Elle permet d’abord de diminuer les dépenses, qu’il s’agisse du loyer, des charges ou des autres frais du quotidien. Elle favorise aussi la vie sociale, les échanges et la découverte d’autres cultures. Partager son logement, c’est aussi créer des liens et vivre des expériences enrichissantes.', 'Document 2 : Vivre en colocation n’est pas toujours simple. Des personnalités ou des habitudes différentes peuvent provoquer des désaccords, notamment pour l’organisation des tâches ménagères. Le manque d’intimité et d’espace personnel peut également peser. Pour éviter les conflits, il faut dialoguer clairement et fixer des règles communes.'] },
  ] } },
  { id: '2026-03-102', theme: 'Le travail : favorable ou défavorable ?', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Le mois prochain, vous aimeriez organiser un week-end avec vos amis. Écrivez-leur un message pour présenter votre idée de séjour, en précisant la destination, le moyen de transport et ce que vous proposez de faire sur place.' },
    { prompt: 'Sur le site « voyage.internaute.fr », répondez à la question : partir voyager pendant un an en quittant tout, est-ce une bonne ou une mauvaise idée ? Appuyez votre avis sur des exemples tirés de votre vie personnelle.' },
    { prompt: T3('Le travail : favorable ou défavorable ?'), documents: ['Document 1 : Le travail occupe une place centrale dans nos vies. Pourtant, ce qui devrait apporter épanouissement et réussite rime souvent avec fatigue et sensation d’être enfermé. Beaucoup regrettent aussi le manque de temps pour leur famille et leurs proches. Pour certains, il faudrait réduire le temps de travail afin de mieux profiter de la vie.', 'Document 2 : Certains choisissent d’abandonner leur emploi pour changer de manière de vivre. Malgré cela, travailler reste essentiel pour beaucoup, car cela participe à l’identité de chacun. Lors d’une rencontre, on demande souvent ce que l’autre fait dans la vie. Comme le souligne Jean-Daniel Remond, l’entreprise apporte des relations, un sentiment d’utilité et forge la personnalité.'] },
  ] } },
  { id: '2026-03-103', theme: 'Les relations amicales au travail', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Matthias vous a écrit pour vous dire qu’il a obtenu son visa pour le Canada et qu’il arrivera le 3 mars. Il vous demande de l’aider à trouver un hôtel pour sa première semaine. Répondez-lui en décrivant l’hôtel et en donnant toutes les informations utiles, notamment son emplacement et son prix.' },
    { prompt: 'Avec des amis, vous êtes allé voir un spectacle, par exemple un film, une pièce ou un concert, et cette sortie vous a beaucoup plu. Sur votre blog, racontez cette soirée et dites pour quelles raisons vous avez apprécié ce spectacle.' },
    { prompt: T3('Les relations amicales au travail.'), documents: ['Document 1 : Les amitiés entre collègues peuvent améliorer l’ambiance au bureau. Elles rendent l’atmosphère plus agréable, renforcent la solidarité et facilitent le travail d’équipe. Elles encouragent aussi une meilleure communication et une coopération plus efficace. Même en dehors du bureau, partager un repas ou une activité aide à consolider ces liens.', 'Document 2 : Au travail, il faut savoir garder un juste milieu entre amitié et professionnalisme. Des liens trop étroits peuvent provoquer des tensions ou gêner certaines décisions. De plus, des groupes fermés risquent d’isoler d’autres collègues. Pour préserver la cohésion, il est nécessaire de fixer des limites et de respecter la hiérarchie.'] },
  ] } },
  { id: '2026-03-104', theme: 'Utilisation des nouvelles technologies', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Vous revenez d’un séjour de deux jours à la campagne. Écrivez à votre ami(e) pour raconter ce week-end et décrire ce que vous avez vécu. (60 mots minimum/120 mots maximum)' },
    { prompt: 'Votre direction cherche une salle pouvant accueillir 100 personnes pour la fête de fin d’année. Rédigez un message pour lui signaler que vous avez trouvé un lieu adapté et précisez son emplacement, ses tarifs et ses services.' },
    { prompt: T3('Utilisation des nouvelles technologies.'), documents: ['Document 1 : Jean pense que l’école doit intégrer les nouvelles technologies pour préparer les élèves au monde numérique. Selon lui, tablettes et ordinateurs motivent davantage les jeunes et enrichissent leurs apprentissages. Ils donnent aussi accès à de nombreuses ressources et développent la créativité ainsi que l’autonomie.', 'Document 2 : Sara se méfie d’un usage trop important des technologies à l’école. Elle estime que cela réduit les échanges humains et crée une dépendance aux écrans. À ses yeux, les méthodes traditionnelles et la relation directe entre enseignants et élèves restent indispensables pour former les jeunes de façon équilibrée.'] },
  ] } },
  { id: '2026-03-105', theme: 'Les devoirs à la maison : utiles ou inutiles ?', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Vous venez de recevoir un colis commandé sur Internet et l’objet est arrivé abîmé. Rédigez un courriel au service client pour expliquer le problème, décrire précisément les dégâts constatés et indiquer la solution que vous souhaitez obtenir.' },
    { prompt: 'Vous avez visité une exposition consacrée à votre artiste préféré. Rédigez un article pour raconter cette visite, présenter ce que vous y avez découvert et expliquer les impressions que cette expérience a laissées sur vous.' },
    { prompt: T3('Les devoirs à la maison : utiles ou inutiles ?'), documents: ['Document 1 : D’après des associations de parents d’élèves, les devoirs à la maison sont bénéfiques : ils apprennent aux enfants à gérer leur temps seuls. Ils créent aussi un contact régulier avec l’école. Même après une journée fatigante, beaucoup de parents apprécient ce moment avec leurs enfants, heureux de sentir l’intérêt de leurs proches.', 'Document 2 : Nous nous opposons aux devoirs à la maison depuis longtemps. Leur utilité n’a jamais été démontrée pour améliorer les résultats. De nombreux parents manquent de temps, ou ne peuvent pas aider leurs enfants. À la maison, certains élèves perdent leur temps, tandis que d’autres restent en difficulté. Il faut donc les supprimer.'] },
  ] } },
  { id: '2026-03-106', theme: 'Écoles privées ou écoles publiques : quel choix ?', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'France Télévision prépare un sujet sur la pratique sportive non professionnelle. Présentez le type de sportif que vous êtes en envoyant votre témoignage sur francetelevision.fr. (60 mots minimum / 120 mots maximum)' },
    { prompt: 'Vous avez passé des vacances dans une belle région de votre pays. Écrivez à vos amis pour leur raconter ce séjour, décrire ce que vous y avez vécu et expliquer pourquoi vous l’avez particulièrement apprécié.' },
    { prompt: T3('Écoles privées ou écoles publiques : quel choix ?'), documents: ['Document 1 : À la rentrée, les inscriptions dans le privé ont augmenté en France. Ce succès ne tient pas seulement aux résultats scolaires, mais surtout à l’image de ces établissements. Beaucoup de parents les jugent plus encadrés, plus surveillés, avec des enseignants davantage présents. Ils apprécient aussi des classes homogènes, fréquentées surtout par des élèves de milieux favorisés, alors que ces écoles sont payantes.', 'Document 2 : Dans les collèges privés, les élèves issus de milieux modestes sont peu nombreux, car la scolarité y est payante. Ce fonctionnement limite la mixité sociale et éloigne les jeunes les uns des autres. Le privé et le public restent ainsi séparés, ce qui entretient les inégalités et renforce chez certains adolescents un sentiment d’exclusion.'] },
  ] } },
  { id: '2026-03-107', theme: 'Les produits faits maison : pour ou contre ?', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Votre amie Joanna vous demande votre avis sur la salle de sport que vous fréquentez. Répondez-lui en la décrivant (ambiance, équipements, prix).' },
    { prompt: 'Vous avez suivi une formation, par exemple en langue ou en informatique. Sur un site Internet, racontez cette expérience en présentant le contenu des cours, les participants, les professeurs et ce que vous avez aimé ou moins aimé pendant cette formation.' },
    { prompt: T3('Les produits faits maison : pour ou contre ?'), documents: ['Document 1 : Aujourd’hui, on peut préparer chez soi toutes sortes de produits : shampoings, savons, crèmes, maquillage ou encore produits ménagers. C’est intéressant, car cela permet de maîtriser la composition et de choisir des ingrédients naturels, sans substances chimiques. En plus, fabriquer soi-même réduit les emballages et limite les déchets. Alors, pourquoi ne pas se lancer ?', 'Document 2 : Faire son propre savon peut sembler séduisant, mais cela comporte des risques pour la santé si les ingrédients sont mal choisis ou si l’hygiène n’est pas respectée. Il faut donc bien se renseigner et suivre des règles strictes de fabrication et de conservation. Même si c’est économique, cette activité demande souvent beaucoup de temps.'] },
  ] } },
  { id: '2026-03-108', theme: 'La lecture chez les enfants', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Un de vos amis veut se lancer dans une activité sportive. Écrivez-lui un message pour lui conseiller une salle de sport de votre quartier, en indiquant où elle se trouve, combien elle coûte et quelles activités on peut y pratiquer.' },
    { prompt: 'Vous avez pris part à une célébration ou à une occasion importante, comme un anniversaire ou un mariage, qui vous a laissé un souvenir fort. Racontez cet événement en expliquant ce qui vous a le plus impressionné.' },
    { prompt: T3('La lecture chez les enfants.'), documents: ['Document 1 : Avec les technologies et les objets connectés qui prennent de plus en plus de place dans la vie quotidienne, les enfants se détournent souvent des livres. Ils préfèrent les jeux vidéo, les réseaux sociaux, la musique ou le sport. Dans ces conditions, pourquoi les obliger à lire ? Le goût de la lecture ne se force pas : il faut laisser chaque enfant choisir ses lectures.', 'Document 2 : L’amour des livres se transmet souvent au sein de la famille, même si les écrans ont aujourd’hui remplacé les ouvrages entre les mains des enfants. Lire régulièrement aide à enrichir le langage, à développer l’attention et à améliorer la concentration. En outre, partager chaque jour un court moment de lecture renforce la complicité entre parents et enfants.'] },
  ] } },
  { id: '2026-03-109', theme: 'Les animaux de compagnie pour les enfants : pour ou contre ?', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Vous devez écrire à un ami qui souhaite suivre des cours de langue dans votre établissement. Donnez-lui toutes les informations utiles pour l’aider à choisir : adresse, prix, types de cours proposés et autres détails importants.' },
    { prompt: 'Vous travaillez dans une association qui accompagne les personnes âgées. Rédigez un article de blog pour raconter ce que vous vivez au sein de cette association et convaincre d’autres personnes de vous rejoindre.' },
    { prompt: T3('Les animaux de compagnie pour les enfants : pour ou contre ?'), documents: ['Document 1 : Donner un animal de compagnie à un enfant présente plusieurs avantages, selon de nombreux psychologues. S’il n’a ni frère ni sœur, l’animal devient un compagnon et évite la solitude. Il aide aussi l’enfant à gagner en confiance, à comprendre qu’un être vivant mérite soin et respect, et à se sentir rassuré tout en devenant plus autonome.', 'Document 2 : Beaucoup d’enfants réclament un chien ou un chat à leurs parents, mais il faut réfléchir avant d’en adopter un. Un animal devient un membre de la famille pour longtemps et demande un véritable engagement. Son coût peut être élevé, et c’est une grande responsabilité. On ne peut pas s’en débarrasser comme d’un jouet lorsqu’il n’intéresse plus l’enfant.'] },
  ] } },
  { id: '2026-03-110', theme: 'Les vêtements de grandes marques', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Vous devez répondre au courriel de votre ami Lucas et lui présenter les nouveaux locaux de votre entreprise. Indiquez où ils se trouvent, comment les pièces sont agencées et quels équipements on y trouve.' },
    { prompt: 'Vous avez pris part à l’événement « Une semaine sans voiture ». Décrivez ce que vous avez vécu, racontez le déroulement de cette initiative, puis dites ce que vous en avez pensé. Précisez les dates, le lieu et les activités proposées.' },
    { prompt: T3('Les vêtements de grandes marques.'), documents: ['Document 1 : Les enfants et les adolescents accordent beaucoup d’importance aux marques. Porter un vêtement connu leur permet d’affirmer leur personnalité et de se sentir intégrés à un groupe. Chez les plus jeunes, on retrouve aussi le plaisir d’afficher des logos ou des personnages de dessins animés appréciés.', 'Document 2 : Les vêtements pour enfants s’abîment et deviennent trop petits très rapidement, car ils ne durent pas longtemps. De plus, les enfants les salissent ou les détériorent vite en jouant dehors, dans l’herbe ou sur les aires de jeux. Ils finissent donc souvent troués ou tachés.'] },
  ] } },
  { id: '2026-03-111', theme: 'Les devoirs à la maison', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Vous avez envie d’organiser une sortie culturelle avec vos amis. Écrivez-leur un message pour leur présenter cette idée, en donnant des informations sur la date, le lieu et le programme prévu.' },
    { prompt: 'Dans votre université, vous avez participé à une soirée sur l’écologie consacrée à la protection de la planète. Sur votre blog, racontez cet événement et expliquez pourquoi il vous a plu.' },
    { prompt: T3('Les devoirs à la maison.'), documents: ['Document 1 : Pour Valérie, mère de famille, les devoirs aident l’enfant à gagner en autonomie, puisqu’il travaille seul après l’école. Ils peuvent aussi créer des moments de complicité entre parents et enfants, par exemple lorsqu’on récite une poésie ou qu’on fait des maths ensemble. En revanche, elle estime qu’ils ne devraient pas durer plus de quinze minutes par soir.', 'Document 2 : Isabelle, enseignante en primaire, refuse de donner des devoirs. Selon elle, ils fatiguent et stressent les enfants. Comme toutes les familles ne disposent pas des mêmes ressources, l’aide à la maison n’est pas équitable. Pour elle, l’autonomie doit se construire à l’école, pas à domicile, et les devoirs provoquent surtout des tensions.'] },
  ] } },
  { id: '2026-03-112', theme: 'Les objets connectés', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Vous devez écrire à votre ami(e) pour lui annoncer votre déménagement dans votre nouveau logement. Indiquez la date, le lieu et le programme prévu, et demandez-lui de vous aider.' },
    { prompt: 'Vous avez pris part à un concours permettant de gagner deux semaines de séjour dans votre ville favorite. Le sujet proposé est « Mon artiste préféré ». Rédigez un article de blog pour présenter l’artiste que vous admirez le plus.' },
    { prompt: T3('Les objets connectés.'), documents: ['Document 1 : Les objets connectés simplifient la vie de tous les jours. Grâce à un téléphone ou à Internet, on peut commander à distance le chauffage, les portes ou d’autres appareils. Montres et bracelets suivent aussi nos activités, comptent nos pas et encouragent à bouger davantage. Ils servent même à rappeler des rendez-vous médicaux ou la prise de médicaments.', 'Document 2 : Il existerait aujourd’hui environ 50 milliards d’objets connectés dans le monde, ce qui soulève un vrai problème de sécurité. Un pirate peut en prendre le contrôle très vite. Un cambrioleur peut aussi observer une maison à distance grâce aux caméras, voire détourner le système d’une voiture et en prendre les commandes.'] },
  ] } },
  { id: '2026-03-113', theme: 'Le grossissement des villes', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Étudiez cette consigne d’examen : vous pratiquez un sport dans un club et vous venez de gagner une compétition. Vous devez écrire un courriel à vos amis pour raconter cet événement sportif et leur annoncer votre succès.' },
    { prompt: 'Le site « colocation.com » recherche des témoignages sur la vie en colocation. Vous avez déjà partagé un logement avec des amis : racontez votre expérience aux internautes et donnez votre avis sur ce mode d’habitation.' },
    { prompt: T3('Le grossissement des villes.'), documents: ['Document 1 : L’agrandissement des villes a de lourdes conséquences sur l’environnement. Plus elles s’étendent, plus elles abîment la nature et, indirectement, l’homme. La déforestation est l’effet le plus évident : en supprimant les espaces verts pour construire routes et immeubles, on réduit aussi les végétaux capables de stocker le carbone.', 'Document 2 : Plus de la moitié de la population mondiale vit en ville, et même huit personnes sur dix dans les pays riches. La question écologique urbaine est donc essentielle. On reproche souvent aux villes d’être peu respectueuses de l’environnement, mais il faut nuancer : par exemple, un citadin consomme généralement moins d’énergie qu’un habitant de la campagne.'] },
  ] } },
  { id: '2026-03-114', theme: 'Le travail des jeunes pendant les vacances', created_at: '2026-03-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 3, source: 'candidats', tasks: [
    { prompt: 'Vous allez célébrer votre anniversaire. Rédigez un message à vos amis pour les inviter, leur présenter le déroulement de la soirée et leur demander un coup de main pour l’organisation. Votre texte doit compter entre 60 et 120 mots.' },
    { prompt: 'Vous avez pris part à un concours de cuisine. Publiez un court article sur votre site pour raconter cette journée et expliquer si vous avez aimé ou non cette expérience. Votre texte doit compter entre 120 et 150 mots.' },
    { prompt: T3('Le travail des jeunes pendant les vacances.'), documents: ['Document 1 : Pour beaucoup d’étudiants, les vacances servent d’abord à se reposer après des mois d’université, à voyager et à profiter de l’été. Pourtant, certains choisissent de travailler comme baby-sitters, serveurs ou cueilleurs. Ce choix présente des avantages, mais il réduit aussi le temps libre : moins de repos, moins de loisirs et moins de moments avec les proches. En plus, ces emplois sont parfois pénibles, répétitifs ou mal rémunérés.', 'Document 2 : De nombreux étudiants travaillent l’été pour plusieurs raisons. D’abord, c’est une première expérience professionnelle qui leur apprend à être plus responsables et à découvrir un métier. Ensuite, le salaire est motivant. Ce travail peut aussi leur permettre de gagner en autonomie financière, de voyager ou de se faire plaisir. Pour d’autres, il s’agit même d’une nécessité pour payer leurs études ou leur logement.'] },
  ] } },
  { id: '2026-02-100', theme: 'La télévision et l’éducation des enfants', created_at: '2026-02-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 2, source: 'candidats', tasks: [
    { prompt: 'Rédigez une annonce pour le journal de l’université afin de trouver quelqu’un avec qui pratiquer une activité physique.' },
    { prompt: 'Sur votre blog, racontez vos premiers moments dans un pays étranger et décrivez les impressions que vous avez ressenties à votre arrivée.' },
    { prompt: T3('La télévision et l’éducation des enfants.'), documents: ['Document 1 : La télévision est aujourd’hui un média très présent dans les foyers. Elle informe, divertit et transmet aussi des éléments culturels à un très large public. Par son influence, elle participe à la sensibilisation aux questions de société et reste un outil accessible pour diffuser des connaissances et des contenus variés.', 'Document 2 : Malgré ses atouts, la télévision peut aussi poser problème. Certains programmes renforcent des clichés ou diffusent des idées discutables. De plus, passer trop de temps devant l’écran réduit celui consacré à la lecture, aux échanges avec les autres ou au sport. Chez les enfants, il faut donc limiter l’exposition et maintenir un bon équilibre.'] },
  ] } },
  { id: '2026-02-101', theme: 'La vie en colocation entre adultes', created_at: '2026-02-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 2, source: 'candidats', tasks: [
    { prompt: 'Écrivez à un(e) ami(e) pour lui proposer d’aller avec vous dans un nouveau restaurant ouvert près de chez vous. Présentez la cuisine, les prix, l’ambiance et la décoration.' },
    { prompt: 'Vous avez découvert une ville inconnue lors d’un voyage. Partagez cette visite sur un site consacré au tourisme en racontant ce que vous avez aimé et ce qui vous a moins plu.' },
    { prompt: T3('La vie en colocation entre adultes.'), documents: ['Document 1 : Partager un logement exige de la tolérance et des règles claires. On ne peut pas toujours mettre la musique trop fort, recevoir ses amis pour faire la fête ou laisser la vaisselle s’accumuler. Comme chacun a ses habitudes, il est indispensable de dialoguer avec ses colocataires et de respecter des consignes communes pour vivre ensemble sereinement.', 'Document 2 : La colocation à l’âge adulte peut être une solution pratique et économique. Elle permet d’habiter un logement plus grand, parfois en centre-ville ou avec jardin, tout en partageant le loyer et les charges. Même si l’on dispose seulement d’une chambre et d’espaces communs, les économies réalisées rendent ce mode de vie très avantageux.'] },
  ] } },
  { id: '2026-02-102', theme: 'Les animaux de compagnie pour les enfants : pour ou contre ?', created_at: '2026-02-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 2, source: 'candidats', tasks: [
    { prompt: 'Un(e) ami(e) veut apprendre une langue dans votre établissement. Écrivez-lui un message pour l’aider à choisir en donnant des informations précises sur l’école, les prix et les différentes formules de cours.' },
    { prompt: 'Vous êtes bénévole dans une structure d’aide aux seniors. Écrivez un billet de blog pour parler de ce que vous vivez dans cette association et encourager d’autres personnes à s’y engager.' },
    { prompt: T3('Les animaux de compagnie pour les enfants : pour ou contre ?'), documents: ['Document 1 : Donner un animal à un enfant peut être très bénéfique. Pour un enfant seul, il devient un compagnon rassurant qui l’aide à moins se sentir isolé. Il développe aussi sa confiance en lui et apprend à respecter un être vivant qui a besoin d’attention. La présence de l’animal favorise enfin l’autonomie.', 'Document 2 : Beaucoup d’enfants réclament un chien ou un chat, mais il faut réfléchir avant d’en adopter un. Un animal n’est pas un simple cadeau : il s’intègre à la famille pour longtemps, coûte cher et demande beaucoup de responsabilités. On ne peut pas s’en débarrasser comme d’un jouet quand l’enfant perd de l’intérêt.'] },
  ] } },
  { id: '2026-02-103', theme: 'Faut-il limiter les voitures dans les centres-villes ?', created_at: '2026-02-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 2, source: 'candidats', tasks: [
    { prompt: 'Rédigez un message destiné à vos amis pour les convier à votre soirée de fin d’année.' },
    { prompt: 'Après un séjour au Canada organisé par une agence, publiez un avis pour raconter ce que vous avez vécu pendant ce voyage.' },
    { prompt: T3('Faut-il limiter les voitures dans les centres-villes ?'), documents: ['Document 1 : Face à une pollution devenue très préoccupante, certaines villes ont décidé de bannir les voitures de leurs centres. Oslo, en Norvège, a adopté cette mesure et s’en réjouit. À terme, cette politique devrait réduire les accidents, diminuer la dépendance au pétrole et améliorer nettement la qualité de l’air.', 'Document 2 : Interdire les voitures en ville ne suffit pas si les aménagements nécessaires ne suivent pas. Pour réussir cette transition, il faut prévoir des parkings adaptés, renforcer les transports publics et accorder des dérogations à certains professionnels comme les policiers, les secours ou les livreurs. Sans ces solutions, la mesure risque d’être inefficace.'] },
  ] } },
  { id: '2026-02-104', theme: 'La sévérité des parents envers les enfants', created_at: '2026-02-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 2, source: 'candidats', tasks: [
    { prompt: 'Vous possédez un vélo en bon état et à petit prix. Rédigez un courriel pour le proposer à la personne qui a publié une annonce. Décrivez-le et indiquez un prix ainsi qu’un rendez-vous pour l’essayer.' },
    { prompt: 'Vous avez passé une journée à la campagne avec vos amis. À votre retour, publiez un message sur votre forum pour raconter comment cette sortie s’est déroulée et ce que vous avez particulièrement apprécié.' },
    { prompt: T3('La sévérité des parents envers les enfants.'), documents: ['Document 1 : J’ai presque 22 ans et je vis encore chez mes parents, qui restent très stricts avec moi. Quand j’étais mineure, je n’avais pas le droit de dormir dehors ni de rentrer après 21 heures. Aujourd’hui, c’est un peu plus souple, mais ma mère m’appelle sans arrêt jusqu’à ce que je sois rentrée.', 'Document 2 : Certains parents craignent d’être trop durs avec leurs enfants. Ils redoutent qu’une éducation trop stricte freine leur épanouissement et nuise à leur personnalité plus tard. Pourtant, même avec beaucoup d’amour, tout permettre à un enfant peut avoir des conséquences négatives lorsqu’il devra vivre avec les autres et respecter des règles.'] },
  ] } },
  { id: '2026-02-105', theme: 'Faire ses courses : petits commerces ou supermarchés ?', created_at: '2026-02-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 2, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez refaire la décoration de votre appartement : meubles, couleur des murs, objets décoratifs, etc. Rédigez un message à un(e) ami(e) pour lui présenter votre projet et lui demander de vous donner un coup de main.' },
    { prompt: 'Lisez l’annonce suivante : « École de musique ! Cours offerts, concerts, jeux. Rendez-vous vendredi dès 9 h. » Vous êtes allé(e) à cet événement. Écrivez à vos amis pour leur raconter cette journée et leur dire ce que vous en avez pensé.' },
    { prompt: T3('Faire ses courses : petits commerces ou supermarchés ?'), documents: ['Document 1 : Le supermarché est très pratique pour faire ses achats en un seul endroit. On y trouve un large choix de produits, des fruits et légumes aux boissons, en passant par les fromages et la viande. Avec le parking à disposition, les courses sont rapides, et les nombreuses promotions permettent souvent de faire de bonnes économies.', 'Document 2 : L’association qui défend les petits commerces soutient le défi « Février sans supermarché ». L’idée est de boycotter les grandes surfaces pendant un mois pour aider les boutiques de quartier à se maintenir. En plus de produits plus frais, on y gagne aussi des échanges agréables avec les voisins.'] },
  ] } },
  { id: '2026-02-106', theme: 'Les vols à bas prix', created_at: '2026-02-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 2, source: 'candidats', tasks: [
    { prompt: 'Vous écrivez à vos amis pour leur proposer de participer à une fête organisée en secret pour votre meilleur(e) ami(e). Dans votre courriel, précisez où et quand elle aura lieu, à quelle heure commenceront les festivités, ainsi que les informations utiles.' },
    { prompt: 'Vous avez assisté à une brocante dans votre ville, où l’on vendait et achetait des objets d’occasion. Sur votre blog personnel, expliquez pourquoi cette sortie vous a plu.' },
    { prompt: T3('Les vols à bas prix.'), documents: ['Document 1 : Je prends souvent l’avion avec des compagnies à bas prix. Leurs billets coûtent nettement moins cher que ceux des compagnies classiques, parfois même moins qu’un trajet en voiture ou en train. En revanche, il faut accepter l’absence de services à bord : pas de repas, pas de boissons, et ce type de vol convient mal aux longs courriers.', 'Document 2 : J’ai décidé d’abandonner les compagnies low cost. Après réflexion, les sièges trop peu confortables, les conditions de travail difficiles et surtout l’état des avions m’inquiètent pour la sécurité. Pour certains déplacements, je choisirai donc la voiture ou le train, qui permet en plus de profiter du paysage. Pour les longues distances, mieux vaut réserver un vol régulier.'] },
  ] } },
  { id: '2026-02-107', theme: 'La lecture pour les enfants', created_at: '2026-02-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 2, source: 'candidats', tasks: [
    { prompt: 'Votre ami veut se mettre à une activité physique. Écrivez-lui un message pour lui conseiller une salle de sport près de chez vous en présentant son emplacement, le prix des abonnements et les activités proposées.' },
    { prompt: 'Vous prenez la plume pour raconter un événement auquel vous avez assisté et qui vous a particulièrement marqué, comme un anniversaire ou un mariage. Décrivez ce moment et expliquez ce dont vous vous souvenez le plus.' },
    { prompt: T3('La lecture pour les enfants.'), documents: ['Document 1 : Avec la technologie et les objets connectés, les enfants s’éloignent de plus en plus des livres et passent leur temps entre jeux vidéo, réseaux sociaux, musique ou sport. Dans ces conditions, pourquoi faudrait-il les pousser à lire ? Le goût des livres ne s’impose pas : mieux vaut les laisser choisir et ne pas les obliger quand ils n’en ont pas envie.', 'Document 2 : L’habitude de lire se transmet au fil des générations. Même si les livres ont laissé place aux smartphones et aux tablettes, la lecture régulière aide l’enfant à enrichir son langage, à mieux écouter et à se concentrer. Lire dix minutes par jour avec ses parents est aussi un excellent moyen de partager un moment complice.'] },
  ] } },
  { id: '2026-01-100', theme: 'Photo sur le CV : pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Écrivez un message à Alex pour lui parler de votre nouvelle université. Décrivez l’ambiance, les professeurs, les autres étudiants et les activités proposées sur place.' },
    { prompt: 'Vous avez choisi d’abandonner votre réseau social habituel, comme Instagram ou Facebook. Racontez cette expérience à vos amis et expliquez les raisons de votre choix.' },
    { prompt: T3('Photo sur le CV : pour ou contre ?'), documents: ['Document 1 : Aujourd’hui, la photo sur un CV reste très contestée. Beaucoup pensent qu’elle devrait être supprimée afin d’éviter les jugements injustes. D’après une étude sur le recrutement, les employeurs accordent surtout de l’importance à l’expérience et aux diplômes. En réalité, très peu d’entre eux commencent par regarder le visage du candidat.', 'Document 2 : La photo sur le CV ne fait pas l’unanimité. Certains recruteurs estiment qu’elle aide à associer un visage à un dossier et à retenir un candidat, surtout lorsqu’ils reçoivent beaucoup de candidatures. D’autres jugent qu’elle peut être utile pour certains emplois, notamment dans l’accueil, à condition qu’elle soit sobre et professionnelle.'] },
  ] } },
  { id: '2026-01-101', theme: 'L’aide aux personnes pauvres', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous venez de décrocher un nouveau poste. Dans un message adressé à votre ami(e) francophone, annoncez cette nouvelle et présentez votre travail, les personnes avec qui vous travaillez et l’endroit où vous exercez.' },
    { prompt: '« Chère communauté, j’ai 19 ans et je vais bientôt étudier à l’étranger. Je voudrais lire des avis d’étudiants qui ont déjà vécu loin de leur pays. Merci pour vos réponses. Julie » Vous avez passé un an à l’étranger pour vos études. Répondez sur le forum en racontant votre expérience, en disant si vous l’avez aimée et en expliquant pourquoi.' },
    { prompt: T3('L’aide aux personnes pauvres.'), documents: ['Document 1 : Chaque hiver, je réserve un peu de temps et d’argent pour venir en aide aux personnes sans abri qui souffrent du froid. Je crois qu’il est essentiel de penser à celles et ceux qui traversent des difficultés. Donner quelques euros à une personne dans le besoin ou à une association me semble un geste simple, mais utile, accessible à tous.', 'Document 2 : À mon avis, donner de l’argent aux personnes pauvres ne suffit pas. Je préfère agir régulièrement dans une association de mon quartier, comme bénévole. Les personnes sans logement ont surtout besoin d’un toit et d’un emploi pour retrouver leur autonomie. Aider à trouver du travail est plus constructif que de donner seulement de l’argent.'] },
  ] } },
  { id: '2026-01-102', theme: 'Vie en colocation entre adultes', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Rédigez un courriel à votre ami pour lui proposer de passer une journée avec vous. Précisez où et quand vous souhaitez le voir, ainsi que ce que vous aimeriez faire ensemble.' },
    { prompt: 'Écrivez un courriel à vos collègues pour raconter la journée de formation à laquelle vous avez participé dans votre entreprise et dire ce que vous avez apprécié.' },
    { prompt: T3('Vie en colocation entre adultes.'), documents: ['Document 1 : La colocation convient bien à ceux qui n’aiment pas manger seuls ou passer leurs soirées sans compagnie. Elle offre de vrais moments d’échange, autour des repas ou de jeux de société par exemple. En plus, les tâches ménagères se répartissent à plusieurs. Vivre avec d’autres personnes permet aussi de s’ouvrir, de découvrir d’autres habitudes et de créer de vrais liens.', 'Document 2 : La colocation n’est pas toujours simple, surtout quand on veut rester tranquille après une longue journée. Il faut accepter les invités de l’autre et respecter les règles de ménage, ce qui demande de la diplomatie. Sinon, les tensions apparaissent vite, sauf si l’on tombe sur un colocataire vraiment idéal.'] },
  ] } },
  { id: '2026-01-103', theme: 'La restauration rapide', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Cédric va s’occuper de votre maison et de votre jardin pendant votre absence. Écrivez-lui un message pour lui expliquer les tâches à faire.' },
    { prompt: 'Après un voyage récent organisé par une agence, vous n’êtes pas satisfait(e) du service reçu. Écrivez un courriel de réclamation pour exprimer votre mécontentement, exposer les difficultés rencontrées et demander une réponse de l’agence.' },
    { prompt: T3('La restauration rapide.'), documents: ['Document 1 : Les restaurants rapides offrent aujourd’hui des repas variés et équilibrés, tout en respectant les règles d’hygiène. Les aliments sont de bonne qualité et chacun choisit son menu, ce qui le rend responsable de ses choix. Pour leurs défenseurs, ces établissements peuvent donc être pratiques sans être forcément nocifs.', 'Document 2 : D’après les spécialistes, la restauration rapide est mauvaise pour la santé lorsqu’on en mange souvent. Les menus se ressemblent presque toujours et sont très riches en calories. En plus, les emballages en plastique génèrent beaucoup de déchets, ce qui aggrave la pollution et nuit à l’environnement.'] },
  ] } },
  { id: '2026-01-104', theme: 'L’uniforme scolaire : pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous avez envie de commencer une activité sportive et vous souhaitez le faire avec votre ami. Écrivez-lui pour lui proposer de pratiquer un sport ensemble.' },
    { prompt: 'Sur votre blog, racontez en détail un séjour d’études que vous avez effectué dans une université hors de votre pays.' },
    { prompt: T3('L’uniforme scolaire : pour ou contre ?'), documents: ['Document 1 : L’uniforme scolaire peut donner aux garçons l’impression de perdre leur personnalité, puisqu’ils ne choisissent plus leurs vêtements. Certains parents, au contraire, préfèrent que leurs enfants puissent s’exprimer par leur style vestimentaire. Pour les jeunes qui aiment se distinguer par la mode ou un accessoire, l’uniforme peut donc sembler frustrant et limitant.', 'Document 2 : Porter un uniforme renforce le sentiment d’appartenir à son école et au groupe des élèves. Il encourage aussi l’esprit collectif et peut créer une certaine fierté. En outre, il réduit les différences liées au style ou au milieu social, tout en aidant les familles à dépenser moins pour les vêtements.'] },
  ] } },
  { id: '2026-01-105', theme: 'Les jeux vidéo : pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous partez en vacances avec vos amis et vous avez repéré un hôtel. Rédigez un message pour leur en présenter les atouts : emplacement, tarif, services et équipements. Proposez-leur ensuite de réserver cet établissement.' },
    { prompt: 'Vous avez commencé un emploi dans un autre pays. Écrivez à vos amis pour leur parler de cette découverte du monde du travail et dire ce qui vous a le plus plu.' },
    { prompt: T3('Les jeux vidéo : pour ou contre ?'), documents: ['Document 1 : Des recherches montrent que jouer aux jeux vidéo peut stimuler certaines zones du cerveau chez l’adulte. Cela peut donc aider à développer l’analyse, la prise de décision et la vitesse de réaction. C’est d’autant plus intéressant que la majorité des joueurs sont des adultes. Il faut toutefois rester prudent, car tous les jeux n’ont pas les mêmes effets.', 'Document 2 : Une étude menée pendant trois ans auprès d’enfants de 8 à 17 ans révèle que les grands joueurs sont plus irritables, plus stressés et davantage exposés à la violence. Leurs résultats scolaires sont aussi moins bons. Les parents devraient donc surveiller de près le temps passé devant ces jeux et en limiter l’usage.'] },
  ] } },
  { id: '2026-01-106', theme: 'Le rôle de la télévision dans l’éducation des enfants', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Publiez une annonce dans le journal de votre université afin de trouver une personne pour pratiquer une activité sportive avec vous.' },
    { prompt: 'Rédigez un article de blog dans lequel vous racontez vos premiers moments dans un pays étranger et les impressions que cette arrivée vous a laissées.' },
    { prompt: T3('Le rôle de la télévision dans l’éducation des enfants.'), documents: ['Document 1 : Très présente dans les foyers, la télévision est à la fois un moyen d’information et de divertissement. Elle diffuse l’actualité, ouvre l’accès à la culture et touche un public très large. Grâce à son influence, elle participe aussi à la transmission de connaissances et à la sensibilisation à des questions de société.', 'Document 2 : La télévision a aussi ses limites. Certains programmes transmettent des clichés ou des idées contestables, et le temps passé devant l’écran empiète souvent sur la lecture, les échanges avec les autres ou le sport. Il est donc essentiel de l’utiliser avec modération, surtout chez les enfants, pour garder un bon équilibre.'] },
  ] } },
  { id: '2026-01-107', theme: 'Les animaux de compagnie pour les enfants : pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Écrivez à votre ami(e), qui veut suivre des cours de langue dans votre école, pour lui donner toutes les informations utiles afin de l’aider à choisir : endroit, prix, formules proposées, et autres détails.' },
    { prompt: 'Vous êtes engagé(e) dans une association au service des personnes âgées. Écrivez un article de blog pour présenter ce que vous vivez dans cette activité et donner envie à d’autres de rejoindre l’association.' },
    { prompt: T3('Les animaux de compagnie pour les enfants : pour ou contre ?'), documents: ['Document 1 : D’après de nombreux psychologues, offrir un animal à un enfant présente plusieurs bénéfices. Il peut rompre la solitude, notamment lorsqu’il n’a pas de frère ou de sœur. L’enfant gagne en confiance, apprend le respect d’un être vivant et se sent rassuré. Avec un animal, il devient aussi plus autonome, sans dépendre constamment de ses parents.', 'Document 2 : Un enfant demande souvent un chien ou un chat, mais adopter un animal ne doit pas se faire à la légère. C’est un engagement de longue durée qui concerne toute la famille. Un animal coûte cher et demande beaucoup de responsabilités. Il ne doit surtout pas être considéré comme un jouet dont on se débarrasse quand l’enfant se lasse.'] },
  ] } },
  { id: '2026-01-108', theme: 'Limiter les voitures dans les centres-villes', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Écrivez à vos amis pour les convier à une fête de fin d’année.' },
    { prompt: 'Après un séjour au Canada organisé par une agence de voyage, publiez un commentaire pour raconter l’expérience que vous avez vécue pendant ce voyage.' },
    { prompt: T3('Limiter les voitures dans les centres-villes.'), documents: ['Document 1 : Face à des niveaux de pollution très inquiétants, plusieurs villes ont décidé de bannir les voitures de leur centre. Oslo, en Norvège, a fait ce choix et s’en réjouit. À terme, cette mesure devrait réduire les accidents, diminuer la dépendance au pétrole et améliorer nettement la qualité de l’air.', 'Document 2 : Certaines villes interdisent la voiture en centre urbain sans prévoir les aménagements nécessaires. Réduire la circulation est utile, mais il faut aussi organiser de grands parkings, renforcer les transports publics et autoriser certains véhicules indispensables, comme ceux de la police, des secours ou des livreurs.'] },
  ] } },
  { id: '2026-01-109', theme: 'Le travail des jeunes pendant les vacances', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Bientôt, vous célébrerez votre anniversaire. Écrivez un message à vos amis pour les convier, présenter le déroulement prévu pour la soirée et solliciter leur participation à l’organisation. « 60 mots minimum / 120 mots maximum »' },
    { prompt: 'Vous avez pris part à une compétition culinaire. Sur votre site Internet, rédigez un petit article pour raconter cette journée et préciser les raisons pour lesquelles cette expérience vous a plu ou non. « 120 mots minimum / 150 mots maximum »' },
    { prompt: T3('Le travail des jeunes pendant les vacances.'), documents: ['Document 1 : Les vacances sont normalement un moment de repos après l’année universitaire, mais certains jeunes choisissent de travailler à cette période. Ils font du baby-sitting, servent dans des restaurants ou cueillent des fruits. Même si ces emplois ont des avantages, ils leur laissent peu de temps pour se détendre, profiter de leurs loisirs ou voir leurs proches. En plus, ils sont parfois épuisants, peu intéressants et mal rémunérés.', 'Document 2 : Beaucoup d’étudiants travaillent pendant l’été pour découvrir le monde professionnel et apprendre à être plus responsables. Le salaire les motive et leur permet soit de gagner en autonomie, soit de financer un voyage ou des plaisirs personnels. Pour d’autres, ce travail est indispensable pour payer les études ou le logement.'] },
  ] } },
  { id: '2026-01-110', theme: 'Le travail : plutôt un atout ou une contrainte ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous envisagez de partir en week-end avec vos amis le mois prochain. Rédigez-leur un message pour présenter votre idée : destination, moyen de transport, activités prévues, et tout autre détail utile.' },
    { prompt: '« Tout quitter pour voyager pendant un an : bonne ou mauvaise idée ? » Sur le site « voyage.internaute.fr », publiez un message pour répondre à cette question en vous appuyant sur des exemples tirés de votre expérience personnelle.' },
    { prompt: T3('Le travail : plutôt un atout ou une contrainte ?'), documents: ['Document 1 : Le travail occupe une place centrale dans nos vies. Dès l’enfance, on demande ce que l’on fera plus tard. Pourtant, il n’évoque pas toujours la réussite : il peut aussi rimer avec fatigue et sentiment d’être enfermé. Beaucoup estiment qu’il faudrait réduire le temps de travail pour retrouver davantage de temps pour sa famille, ses proches et une vie plus équilibrée.', 'Document 2 : Certains choisissent d’abandonner leur emploi pour changer complètement de vie. Pourtant, le travail reste une manière d’exister socialement. Lors d’une première rencontre, on demande souvent ce que l’on fait dans la vie. L’emploi forge aussi l’identité : relations, réseau, sentiment d’utilité, mais aussi difficultés quotidiennes participent à la construction de la personnalité.'] },
  ] } },
  { id: '2026-01-111', theme: 'Vivre chez ses parents : une bonne solution ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous partez en voyage et vous confiez votre appartement à un ami qui viendra y séjourner pendant vos vacances. Envoyez-lui un message pour lui décrire le logement : immeuble, appartement, accès et autres informations pratiques.' },
    { prompt: 'Racontez, sous forme d’article de blog, le voyage qui vous a laissé le meilleur souvenir.' },
    { prompt: T3('Vivre chez ses parents : une bonne solution ?'), documents: ['Document 1 : Vivre chez ses parents pendant ses études a plusieurs avantages : cela permet d’économiser le loyer et les repas, de profiter de plats faits maison et de garder une certaine stabilité. Beaucoup de jeunes peuvent ainsi mettre de l’argent de côté pour leurs projets. Des témoignages soulignent aussi le confort, le linge propre et l’absence de solitude. Mme Léa, 22 ans, ajoute qu’étudier loin de chez soi coûte très cher.', 'Document 2 : Cette solution a aussi des limites, surtout le manque d’autonomie. Quand on reste chez ses parents, on dépend souvent de leurs décisions et l’on peut se sentir moins libre. Un homme de 25 ans, obligé de retourner chez ses parents après avoir perdu son emploi, explique qu’il a perdu son intimité. Pour d’autres jeunes, revenir vivre à la maison donne l’impression de faire un pas en arrière.'] },
  ] } },
  { id: '2026-01-112', theme: 'La croissance des villes : menace ou progrès ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous pratiquez un sport dans un club et vous venez de gagner une compétition. Écrivez un courriel à vos amis pour raconter cette épreuve sportive et leur annoncer votre victoire.' },
    { prompt: '« Le site colocation.com recherche des témoignages sur vos expériences de colocation. Écrivez-nous ! » Vous avez déjà partagé un logement avec des amis : racontez cette expérience aux internautes et donnez votre avis sur ce mode de vie.' },
    { prompt: T3('La croissance des villes : menace ou progrès ?'), documents: ['Document 1 : Les villes ne cessent de s’étendre, et cette croissance pèse lourdement sur l’environnement. Plus elles s’agrandissent, plus elles détruisent la nature et fragilisent l’homme. Le problème le plus évident reste la déforestation : en supprimant des espaces verts pour bâtir des routes ou des immeubles, on retire aussi des végétaux capables d’absorber d’énormes quantités de carbone.', 'Document 2 : Plus de la moitié de la population mondiale habite en ville, et dans les pays développés, c’est même la grande majorité. La question écologique urbaine est donc essentielle. On critique souvent les villes, jugées peu respectueuses de l’environnement. Pourtant, il faut nuancer : un citadin consomme parfois moins d’énergie qu’un habitant de la campagne.'] },
  ] } },
  { id: '2026-01-113', theme: 'Les nouvelles technologies : utiles ou dangereuses pour les enfants ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Envoyez un message à vos amis pour les inviter à célébrer votre anniversaire et expliquez comment la fête est prévue.' },
    { prompt: 'Réagissez en commentaire à une publication Facebook sur les études à l’étranger en présentant les points positifs et les difficultés de cette expérience.' },
    { prompt: T3('Les nouvelles technologies : utiles ou dangereuses pour les enfants ?'), documents: ['Document 1 : À l’école primaire, les enfants peuvent utiliser les technologies pour revoir des vidéos sur les thèmes étudiés en classe ou pour jouer à des jeux éducatifs. Ces outils peuvent aussi renforcer leurs compétences en mathématiques, en lecture et même en dactylographie. Bien employés, ils deviennent donc un soutien intéressant pour les apprentissages.', 'Document 2 : Les nouvelles technologies risquent aussi d’encourager les enfants à rester trop longtemps assis, ce qui inquiète beaucoup les parents. Elles ne favorisent ni le jeu libre et créatif, ni les échanges en face à face, ni l’activité physique. Il vaut mieux proposer d’autres occupations amusantes pour les aider à délaisser leurs écrans.'] },
  ] } },
  { id: '2026-01-114', theme: 'L’égalité femmes-hommes au travail', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Sur un forum, vous publiez une réponse pour présenter votre pays ainsi que certains aspects de sa culture. Votre objectif est de donner aux lecteurs l’envie de venir le découvrir. Écrivez entre 60 et 120 mots.' },
    { prompt: 'Vous venez d’obtenir un nouveau poste. Écrivez à vos amis pour raconter le déroulement de vos premiers jours de travail et donner votre opinion sur cet emploi. « 120 mots minimum / 150 mots maximum »' },
    { prompt: T3('L’égalité femmes-hommes au travail.'), documents: ['Document 1 : Au Québec, l’égalité entre les femmes et les hommes est une valeur essentielle. Ils disposent des mêmes droits et des mêmes devoirs. Les femmes peuvent exercer librement le métier de leur choix et occupent aussi des postes à responsabilités : députées, mairesse, conseillères, administratrices ou dirigeantes d’entreprise. Beaucoup travaillent également dans des domaines longtemps réservés aux hommes.', 'Document 2 : Pour Louis, 27 ans, la rentrée en cours marque une étape importante : il est le seul homme de sa promotion. Diplômé, il deviendra bientôt le premier sage-femme homme au Québec. Son parcours a commencé lorsqu’il travaillait comme masseur auprès de femmes enceintes. Même si cette présence masculine peut encore surprendre certaines patientes, elle est accueillie favorablement.'] },
  ] } },
  { id: '2026-01-115', theme: 'La sieste au travail', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous écrivez à vos amis pour leur suggérer de venir passer un week-end avec vous autour d’activités sportives.' },
    { prompt: 'Sur un forum, rédigez un billet de blog où vous expliquez les raisons qui vous ont poussé à modifier votre manière de manger.' },
    { prompt: T3('La sieste au travail.'), documents: ['Document 1 : La sieste au travail peut être bénéfique autant pour les salariés que pour l’entreprise. Un court repos en journée améliore la vigilance, la concentration et l’humeur, tout en réduisant le stress. Elle peut aussi soutenir la santé générale et limiter certains coûts liés à la fatigue et aux accidents.', 'Document 2 : Même si l’idée paraît intéressante, toutes les entreprises ne peuvent pas installer des espaces de repos ou des lits. Le budget, l’organisation ou les règles internes compliquent souvent sa mise en place. Certains employés ne se sentent pas non plus à l’aise avec cette pratique, d’où la nécessité de solutions adaptées.'] },
  ] } },
  { id: '2026-01-116', theme: 'L’emploi des jeunes : diplôme ou expérience', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous voulez prévenir un ami que vous pensez bientôt changer de logement. Écrivez-lui un message pour présenter l’appartement trouvé, en précisant combien de pièces il y a, où il se situe et combien il coûte.' },
    { prompt: 'Un festival de musique gratuit a eu lieu dans votre ville. Vous y êtes allé avec un ami et vous racontez cette sortie dans un article de blog.' },
    { prompt: T3('L’emploi des jeunes : diplôme ou expérience.'), documents: ['Document 1 : Beaucoup de jeunes diplômés restent sans emploi après leurs études. Sur le marché du travail, on leur reproche souvent de manquer d’expérience, ou bien d’être trop jeunes. Plus de 60 % d’entre eux n’ont toujours pas trouvé de poste un an après l’université, ce qui montre l’urgence de mieux valoriser les diplômes.', 'Document 2 : Certains exemples de grands entrepreneurs sans études universitaires font croire qu’on peut réussir sans passer par l’université. D’après plusieurs dirigeants, l’enseignement supérieur favorise surtout des parcours trop classiques et bride l’imagination. Pour créer une entreprise, l’autoformation et l’expérience seraient donc plus utiles qu’un cursus académique.'] },
  ] } },
  { id: '2026-01-117', theme: 'La vie à la campagne ou en ville', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Rédigez un mail à votre ami francophone pour lui demander un coup de main dans votre recherche de logement. Donnez-lui les renseignements utiles, notamment le type d’habitation souhaité, votre budget et la date prévue.' },
    { prompt: 'Votre école vous confie l’organisation d’une journée d’accueil pour les nouveaux étudiants francophones. Rédigez un courriel à leur intention en donnant toutes les informations nécessaires au bon déroulement de cette journée.' },
    { prompt: T3('La vie à la campagne ou en ville.'), documents: ['Document 1 : Vivre en ville offre une grande variété de loisirs : cinéma, restaurants, magasins et nombreuses activités culturelles. Tout est proche, ce qui évite de longs déplacements ou de devoir prendre un taxi. Les musées, théâtres et opéras sont facilement accessibles, ce qui plaît particulièrement aux amateurs de sorties.', 'Document 2 : J’ai quitté la ville pour la campagne afin de retrouver le calme et me rapprocher de la nature. Je reçois maintenant mes amis sur la terrasse ou autour d’un barbecue dans le jardin. Les logements y sont aussi beaucoup moins chers : avec mon budget, j’ai pu choisir une grande maison avec jardin, bien mieux qu’un petit appartement en ville.'] },
  ] } },
  { id: '2026-01-118', theme: 'Influence de la publicité sur les enfants : pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous cherchez une personne pour partager votre grand appartement. Écrivez un texte pour présenter la colocation que vous proposez et décrire votre logement.' },
    { prompt: 'Sur votre blog, vous racontez la venue d’une compagnie théâtrale dans votre ville après avoir vu l’un de ses spectacles. Décrivez ce moment dans un article.' },
    { prompt: T3('Influence de la publicité sur les enfants : pour ou contre ?'), documents: ['Document 1 : Les enfants sont exposés en permanence à la publicité, à la télévision, dans les magazines et sur Internet. Ils sont souvent visés par des messages pour des aliments peu sains, des jouets ou des jeux vidéo. Cette exposition fréquente peut influencer leurs envies et orienter leurs demandes auprès de leurs parents.', 'Document 2 : Des chercheurs rappellent que les enfants comprennent mal les mécanismes de la publicité et ne perçoivent pas toujours son but persuasif. Cependant, leurs choix de consommation dépendent aussi davantage de l’éducation familiale et du milieu social que des messages publicitaires eux-mêmes.'] },
  ] } },
  { id: '2026-01-119', theme: 'Le livre papier ou le livre numérique ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Répondez à votre ami Bernard, qui va bientôt s’installer dans votre quartier, et recommandez-lui un marché agréable pour faire ses achats. Décrivez son emplacement, ses horaires et les produits qu’on y trouve.' },
    { prompt: 'Vous faites partie d’une association de quartier qui organise des activités pour les enfants. Sur le site de l’association, racontez votre expérience et expliquez en quoi ce type d’initiative est utile.' },
    { prompt: T3('Le livre papier ou le livre numérique ?'), documents: ['Document 1 : Depuis quelques années, beaucoup de lecteurs ont abandonné la bibliothèque classique au profit du livre numérique. Ils y voient surtout un avantage financier, car il coûte souvent moins cher et évite de consommer du papier. Ce format est aussi très utile pour les personnes en situation de handicap, grâce à des options comme l’agrandissement des caractères.', 'Document 2 : Pour de nombreux lecteurs, le livre papier reste irremplaçable. On aime l’offrir, le prêter, y ajouter un mot, mais aussi son aspect concret, son odeur et l’émotion qu’il procure. Le numérique paraît plus froid, et il exige en plus des connaissances de base en informatique, ce qui peut gêner certains lecteurs.'] },
  ] } },
  { id: '2026-01-120', theme: 'La livraison des repas', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Votre ami(e) vous écrit : « Je viens bientôt en vacances dans ta région. Tu peux me conseiller une visite ? » Répondez-lui pour lui recommander un lieu et expliquer pourquoi il vaut le détour.' },
    { prompt: 'Vous avez suivi des cours dans une salle de sport. La salle demande l’avis de ses clients sur son site Internet : racontez votre expérience et donnez votre avis.' },
    { prompt: T3('La livraison des repas.'), documents: ['Document 1 : La livraison de repas fait gagner un temps précieux, surtout au travail. On peut commander au bureau sans se déplacer et reprendre plus vite sa journée. Elle offre aussi davantage de choix : chacun peut choisir son plat. Autre atout, ce service fonctionne à toute heure, grâce à des restaurants ouverts tard ou même 24 heures sur 24.', 'Document 2 : Ce service séduit beaucoup de personnes pressées, mais il a un coût pour l’environnement. Les livraisons se font souvent en voiture ou en scooter, donc avec des véhicules polluants. En plus, manger chez soi ou au bureau pousse à rester enfermé et à voir toujours les mêmes personnes, alors qu’il est important de sortir et de rencontrer d’autres gens.'] },
  ] } },
  { id: '2026-01-121', theme: 'Le plastique : pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Votre amie Barbara vous écrit : « Je cherche un endroit pour déjeuner en plein air ce week-end. Tu as une idée ? » Répondez-lui en lui proposant un lieu (situation, ambiance, accès).' },
    { prompt: 'Pendant vos vacances, vous avez découvert un nouveau pays. Sur un site internet, racontez ce voyage et donnez votre avis sur cette destination.' },
    { prompt: T3('Le plastique : pour ou contre ?'), documents: ['Document 1 : Franck défend un usage raisonné du plastique. Selon lui, ce matériau est indispensable dans plusieurs domaines, notamment la santé et l’alimentation. Il permet de conserver les produits et de stériliser le matériel médical. Il ne prône pas l’excès, mais une consommation contrôlée, avec recyclage, car certains usages restent essentiels dans la vie moderne.', 'Document 2 : Amicha rejette l’usage du plastique à cause de ses effets désastreux sur la nature. Elle rappelle que les déchets plastiques abîment les océans et les écosystèmes. Pour elle, il faut vite adopter des solutions plus durables afin de préserver l’environnement et la santé de tous.'] },
  ] } },
  { id: '2026-01-122', theme: 'Les jeux vidéo : pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Le journal « Bienvenue » prépare un article sur les habitants de notre ville. Rédigez un message à publier dans ce numéro : présentez-vous d’abord, puis décrivez les endroits de la ville que vous préférez.' },
    { prompt: 'Après avoir assisté au spectacle de votre chanteur ou chanteuse préféré(e), vous publiez un article sur votre blog pour raconter ce moment et donner envie à vos amis ainsi qu’aux autres lecteurs d’aller au prochain concert.' },
    { prompt: T3('Les jeux vidéo : pour ou contre ?'), documents: ['Document 1 : Les enfants et les adolescents jouent souvent aux jeux vidéo, et cette habitude peut entraîner des pensées négatives ainsi qu’un comportement plus agressif. Une étude menée auprès de jeunes de 9 à 18 ans a montré que les jeux violents favorisent l’agressivité. D’après Diego Gentil, ce phénomène reste difficile à éviter, même lorsque les parents sont très attentifs.', 'Document 2 : On insiste souvent sur les effets néfastes des jeux vidéo, mais ils peuvent aussi être bénéfiques pour le cerveau et la santé. Ils améliorent certaines capacités comme la concentration, la créativité et l’analyse. Cela s’explique facilement : pour jouer, il faut sans cesse réfléchir et trouver des solutions.'] },
  ] } },
  { id: '2026-01-123', theme: 'Apprendre le français', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous avez trouvé sur Internet une annonce d’aide pour les personnes qui veulent apprendre le français et trouver des partenaires de pratique. Répondez par courriel en vous présentant et en expliquant vos raisons d’apprendre cette langue.' },
    { prompt: 'Après avoir participé à une célébration en famille, vous envoyez un message à vos amis pour la raconter et dire ce que vous avez préféré.' },
    { prompt: T3('Apprendre le français.'), documents: ['Document 1 : Plusieurs villes dans le monde ont réussi à interdire la circulation des voitures en centre urbain malgré une forte pollution. Oslo, la capitale norvégienne, a choisi cette voie et s’en dit satisfaite. Avec le temps, les accidents devraient diminuer, la dépendance au pétrole aussi, et l’air deviendra plus sain pour tous.', 'Document 2 : Certaines villes veulent bannir les voitures du centre, mais elles ne prévoient pas toujours les infrastructures nécessaires. Bien sûr, cela réduira les embouteillages et la pollution. En revanche, il faudra des parkings adaptés, davantage de transports publics et des autorisations spéciales pour certains professionnels comme les policiers, les secours ou les livreurs.'] },
  ] } },
  { id: '2026-01-124', theme: 'Les transports en commun gratuits : pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous lisez cette annonce : « Je cherche un vélo en bon état et pas cher. Contactez-moi : mathieu@courriel.com. » Vous vendez un vélo : écrivez à Mathieu pour le présenter, donner votre prix et proposer un essai.' },
    { prompt: 'Vous écrivez à vos amis pour raconter un emploi saisonnier que vous avez fait pendant les vacances d’été et partager ce que vous avez vécu.' },
    { prompt: T3('Les transports en commun gratuits : pour ou contre ?'), documents: ['Document 1 : La gratuité des transports en commun est une excellente mesure. Elle réduit le nombre de voitures en ville, limite les embouteillages et diminue la pollution, ce qui peut aussi faire baisser les risques de maladies respiratoires. Dans ma ville, on l’a mise en place et l’on constate que les habitants prennent davantage les transports publics. Les commerçants en profitent également, car les gens reviennent faire leurs achats au centre-ville.', 'Document 2 : Cette idée coûterait trop cher aux villes, qui ont selon moi d’autres priorités, comme l’aménagement des espaces verts à Toulouse. Mieux vaudrait améliorer l’organisation du réseau que le rendre gratuit. Dans certains quartiers éloignés, l’offre est insuffisante, ce qui pousse les habitants à prendre leur voiture. Enfin, un titre payant incite davantage à respecter les équipements.'] },
  ] } },
  { id: '2026-01-125', theme: 'La vie à la campagne : pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous voulez faire découvrir à vos amis un site touristique que vous aimez tout particulièrement. Dans un message chaleureux, présentez-le, dites ce qui vous plaît tant dans cet endroit et indiquez une date, une heure ainsi qu’un hébergement pour organiser la visite.' },
    { prompt: 'Vous êtes allé à un festival, qu’il soit musical, cinématographique, gastronomique ou autre, et l’expérience vous a déçu. Rédigez un billet pour votre blog afin d’expliquer clairement ce qui ne vous a pas satisfait.' },
    { prompt: T3('La vie à la campagne : pour ou contre ?'), documents: ['Document 1 : Pour moi, la ville reste idéale pour sortir et se divertir. On y trouve facilement un cinéma, des restaurants ou des boutiques, sans avoir à parcourir de longues distances. En plus, l’offre culturelle est très riche : musées, spectacles, opéras… Chacun peut y trouver une activité à son goût.', 'Document 2 : J’ai récemment quitté la ville pour m’installer à la campagne, car j’avais besoin de calme et de nature. Aujourd’hui, je préfère recevoir mes amis sur ma terrasse ou autour d’un barbecue dans mon jardin. Le prix du logement a aussi compté : ici, j’ai pu acheter une grande maison avec jardin, bien plus abordable qu’en ville.'] },
  ] } },
  { id: '2026-01-126', theme: 'Les caméras de surveillance à l’école', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous voulez célébrer votre anniversaire dans un restaurant. Vous adressez un courriel à vos amis pour les inviter et leur communiquer toutes les informations utiles : adresse, date, horaires, menu et tarif. Pensez aussi à leur demander de vous répondre.' },
    { prompt: 'Sur un forum en ligne, expliquez pourquoi vous avez choisi de quitter la ville pour vivre à la campagne, puis présentez les aspects positifs de cette nouvelle vie. Vous écrirez un texte de 120 mots minimum et de 150 mots maximum.' },
    { prompt: T3('Les caméras de surveillance à l’école.'), documents: ['Document 1 : Dans l’école de Montréal où j’enseigne, des caméras ont été installées presque partout. Elles rappellent aux élèves que tout acte violent aura des conséquences. Parents, professeurs et majorité des élèves approuvent cette mesure, car elle renforce le sentiment de sécurité. Quelques jeunes, en revanche, dénoncent une atteinte à leur vie privée.', 'Document 2 : Je suis opposé aux caméras de surveillance dans les écoles de Montréal. Là où elles ont été adoptées, leurs effets restent peu convaincants. Comme elles sont visibles, un intrus peut contourner le dispositif par des zones non filmées. Pour améliorer la discipline, mieux vaut renforcer le dialogue et faire respecter clairement le règlement intérieur.'] },
  ] } },
  { id: '2026-01-127', theme: 'Locations de logement de courte durée', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez assister au concert de votre artiste préféré. Proposez à votre ami de vous y accompagner en lui envoyant un courriel avec les renseignements essentiels : date, prix, lieu, nom de l’artiste et durée du spectacle.' },
    { prompt: 'Les enseignants de l’école de votre quartier veulent faire découvrir divers métiers aux élèves. Vous souhaitez participer à ce projet pour parler de votre expérience professionnelle. Écrivez-leur pour présenter votre métier, vos tâches et vos collègues, puis expliquez pourquoi vous le trouvez passionnant.' },
    { prompt: T3('Locations de logement de courte durée.'), documents: ['Document 1 : De plus en plus de particuliers louent un logement ou une chambre à des voyageurs. Cela leur permet de gagner un revenu complémentaire tout en faisant des rencontres. Les visiteurs paient moins cher qu’à l’hôtel et, s’ils le souhaitent, peuvent cuisiner sur place. En échange, l’hôte conseille souvent les sorties et joue le rôle de guide.', 'Document 2 : L’an dernier, j’ai loué mon appartement à un couple de touristes venus passer une semaine de vacances à Marseille. Cette expérience a été très décevante. Ils sont arrivés en retard, ont fait du bruit, ont gêné les voisins et sont repartis en laissant vaisselle et déchets. J’ai ensuite passé des heures à tout nettoyer. Julien, 38 ans.'] },
  ] } },
  { id: '2026-01-128', theme: 'Les vêtements de grande marque', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Votre ami Lucas vous a écrit au sujet des nouveaux bureaux de votre entreprise. Répondez à son message en décrivant l’endroit, l’organisation des espaces et les équipements disponibles.' },
    { prompt: 'Vous avez participé à une manifestation appelée « Une semaine sans voiture ». Racontez comment s’est déroulée cette expérience et donnez votre avis sur cette initiative, en précisant les dates, le lieu et les activités proposées.' },
    { prompt: T3('Les vêtements de grande marque.'), documents: ['Document 1 : Les vêtements de marque comptent beaucoup pour les enfants et les adolescents. Ils servent à affirmer leur identité et à se sentir appartenir à un groupe. Chez les jeunes, surtout à l’adolescence, cette attirance est forte. Les plus petits aiment aussi porter des habits ornés de logos ou de personnages qu’ils apprécient.', 'Document 2 : Les enfants grandissent rapidement, donc leurs vêtements ne leur vont pas longtemps. En plus, ils les abîment vite en jouant dehors avec leurs amis, dans l’herbe ou sur les aires de jeux. Résultat : les habits se tachent, s’usent et se déchirent très facilement.'] },
  ] } },
  { id: '2026-01-129', theme: 'La sévérité des parents envers les enfants', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Un lecteur cherche un vélo en bon état et à petit prix. Répondez-lui par courriel pour présenter le vôtre, en donner le prix et convenir d’un rendez-vous afin qu’il puisse l’essayer.' },
    { prompt: 'Vous avez passé une journée à la campagne avec des amis. À votre retour, publiez un message sur votre forum pour raconter cette sortie et dire ce que vous avez particulièrement apprécié : activités, paysage, animaux et autres moments marquants.' },
    { prompt: T3('La sévérité des parents envers les enfants.'), documents: ['Document 1 : J’ai bientôt 22 ans et je vis encore chez mes parents, qui restent très stricts avec moi malgré ma majorité. Quand j’étais mineure, je n’avais pas le droit de dormir ailleurs ni de rentrer après 21 heures. Aujourd’hui, les règles ont peu changé : je peux sortir plus tard, mais ma mère m’appelle sans cesse jusqu’à mon retour.', 'Document 2 : Certains parents redoutent d’être trop durs avec leurs enfants. Ils pensent qu’un excès d’autorité peut empêcher leur épanouissement et nuire à la construction de leur personnalité. Pourtant, tout leur accorder par amour peut aussi poser problème plus tard, car la vie en société impose des règles à respecter.'] },
  ] } },
  { id: '2026-01-130', theme: 'Faire ses courses : petits magasins ou supermarchés ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous souhaitez refaire la décoration de votre appartement, avec de nouveaux meubles, une autre couleur de peinture et quelques objets décoratifs. Rédigez un message à un(e) ami(e) pour lui présenter votre idée et lui demander de l’aide.' },
    { prompt: '« École de musique : cours gratuits, concerts, jeux. Rendez-vous vendredi à partir de 9 heures. » Vous avez assisté à cette journée. Écrivez à vos amis pour leur raconter ce que vous avez vécu et leur dire ce que vous avez pensé de l’événement.' },
    { prompt: T3('Faire ses courses : petits magasins ou supermarchés ?'), documents: ['Le supermarché reste très pratique : tout y est réuni au même endroit. On peut venir en voiture, se garer facilement, puis parcourir les rayons pour acheter fruits, légumes, viandes, fromages, boissons et bien d’autres produits. En plus, le choix est large, avec plusieurs marques pour un même article, ainsi que des promotions régulières et des réductions intéressantes.', 'Document 2 : Depuis plusieurs années, l’Association pour la sauvegarde des petits commerces encourage le défi « Février sans supermarché ». L’idée est de freiner la domination des grandes surfaces et d’aider les boutiques de quartier à continuer d’exister. Pendant un mois, on achète dans les épiceries locales et l’on profite de produits frais, souvent meilleurs, tout en échangeant davantage avec ses voisins.'] },
  ] } },
  { id: '2026-01-131', theme: 'Les vols à bas prix', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous envoyez un courriel à vos amis pour les convier à la fête d’anniversaire surprise de votre meilleur(e) ami(e), en précisant le lieu, la date, l’heure, etc.' },
    { prompt: 'Vous avez participé à une brocante dans votre ville, où l’on pouvait acheter et vendre des objets d’occasion. Sur votre blog personnel, expliquez pourquoi cette expérience vous a plu.' },
    { prompt: T3('Les vols à bas prix.'), documents: ['Document 1 : Je prends souvent l’avion avec des compagnies à bas prix. Leurs billets coûtent nettement moins cher que ceux des compagnies classiques, parfois même moins qu’un trajet en train ou en voiture. En revanche, il faut accepter un service minimal à bord : pas de repas, pas de boissons. À mon avis, ce type de vol convient surtout pour les trajets courts.', 'Document 2 : J’ai décidé d’abandonner les compagnies aériennes low-cost. Après réflexion, j’ai compris que les sièges sont inconfortables, que les conditions de travail y sont difficiles et que certains avions semblent trop anciens pour inspirer confiance. Pour certains déplacements, je privilégierai désormais la voiture ou le train ; pour les longues distances, je choisirai plutôt une compagnie régulière.'] },
  ] } },
  { id: '2026-01-132', theme: 'Vivre chez ses parents', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Votre meilleur(e) ami(e) va bientôt fêter son anniversaire. Écrivez un message à votre groupe d’amis pour proposer un cadeau commun, préciser ce que vous aimeriez offrir et expliquer comment chacun peut contribuer.' },
    { prompt: 'Vous cherchez un lieu pour organiser la fête de fin d’année de l’école de musique de Louviers, avec un accueil pour 100 personnes. Vous avez trouvé une salle qui semble convenir. Écrivez à la direction pour décrire votre visite et défendre votre proposition en parlant du prix, des services et de l’emplacement.' },
    { prompt: T3('Vivre chez ses parents.'), documents: ['Document 1 : J’ai 19 ans et je vis encore chez mes parents. Je suis majeure, pourtant ils restent stricts avec moi. Avant mes 18 ans, je devais rentrer avant 20 heures et je n’avais pas le droit de dormir chez mes amies. Aujourd’hui, j’ai un peu plus de liberté, mais ma mère continue de s’inquiéter, m’appelle souvent et n’arrive pas à se coucher tant que je ne suis pas rentrée.', 'Document 2 : Certains parents, pour ne pas paraître trop durs, laissent leurs enfants décider de presque tout. Ils redoutent qu’un manque de liberté les rende malheureux ou sans caractère. Cette souplesse a peu d’effets pendant l’enfance, mais plus tard, elle peut poser problème : devenus adultes, ces jeunes ont souvent du mal à respecter les règles de la vie en société.'] },
  ] } },
  { id: '2026-01-133', theme: 'Les objets connectés', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous allez bientôt déménager dans votre nouveau logement. Écrivez à votre ami(e) pour lui présenter votre programme de déménagement et lui demander de vous aider. Précisez la date, le lieu et l’organisation prévue.' },
    { prompt: 'Vous avez pris part à un concours permettant de gagner deux semaines de vacances dans votre ville favorite. Le sujet proposé est « Mon artiste préféré ». Écrivez un article de blog consacré à cet artiste.' },
    { prompt: T3('Les objets connectés.'), documents: ['Document 1 : Les objets connectés simplifient le quotidien. Pilotés à distance par téléphone ou par Internet, ils permettent par exemple de contrôler le chauffage ou de fermer les portes. Avec une montre ou un bracelet connecté, on peut aussi suivre ses activités. Certains appareils servent même de carnet de santé et rappellent les rendez-vous médicaux ou la prise de médicaments.', 'Document 2 : On compterait déjà 50 milliards d’objets connectés dans le monde : alarmes, téléviseurs, caméras, volets, détecteurs de fumée… Mais cette évolution soulève un problème majeur : la sécurité. Un pirate peut prendre le contrôle d’un appareil en quelques minutes. Un cambrioleur peut aussi surveiller une maison à distance, ou encore accéder au système d’une voiture et la piloter de loin.'] },
  ] } },
  { id: '2026-01-134', theme: 'Les distributeurs de boissons dans les lycées', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Anna vous écrit pour préparer son week-end dans votre ville et vous demander quels moyens de transport elle pourra utiliser pour s’y déplacer. Répondez-lui en présentant les différents transports disponibles, comme le métro, le tramway ou le vélo.' },
    { prompt: 'Dans un article de blog, vous revenez sur la fête des voisins à laquelle vous avez pris part dans votre quartier. Vous racontez comment cela s’est passé et vous expliquez les raisons de votre enthousiasme.' },
    { prompt: T3('Les distributeurs de boissons dans les lycées.'), documents: ['Document 1 : De plus en plus de collèges et de lycées suppriment les distributeurs de snacks et de boissons sucrées. L’objectif est de protéger la santé des élèves, car l’obésité chez les adolescents progresse. L’école doit aussi jouer un rôle éducatif. Une canette de soda de 33 centilitres contient, par exemple, 7 ou 8 morceaux de sucre. Il faut donc bannir ces machines qui encouragent la consommation de produits trop sucrés.', 'Document 2 : Tout le monde n’est pas favorable à l’interdiction des distributeurs dans les établissements scolaires. Les fabricants rappellent qu’ils ont aussi des avantages. Les boissons chaudes aident les élèves à se réchauffer pendant l’hiver. Comme les machines sont dans le lycée, les jeunes n’ont pas besoin de sortir pour acheter à manger. Elles sont aussi utiles à ceux qui ne prennent pas de petit déjeuner chez eux.'] },
  ] } },
  { id: '2026-01-135', theme: 'Les devoirs à la maison', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous avez reçu un colis commandé en ligne, mais l’objet est arrivé abîmé. Rédigez un e-mail au service client pour expliquer le problème, décrire les dégâts et indiquer la solution que vous souhaitez obtenir.' },
    { prompt: 'Vous rédigez un article de blog après avoir vu une exposition consacrée à votre artiste favori. Vous y décrivez ce que vous avez observé et les sentiments que cette visite vous a inspirés.' },
    { prompt: T3('Les devoirs à la maison.'), documents: ['Document 1 : Pour de nombreuses associations de parents, les devoirs à faire à la maison sont utiles : ils apprennent aux élèves à gérer leur temps seuls. Ils gardent aussi un lien régulier avec l’école. Même après une journée chargée, beaucoup de parents apprécient ce moment avec leurs enfants, qui sont heureux de voir leur intérêt. Cela renforce les liens familiaux.', 'Document 2 : Nous nous opposons aux devoirs à la maison depuis longtemps. Leur efficacité n’a jamais été démontrée. Beaucoup de parents n’ont ni le temps ni les compétences pour aider leurs enfants. En plus, les élèves qui travaillent déjà bien en classe perdent du temps, et ceux qui n’ont pas d’aide à la maison restent en difficulté. Il faut donc les supprimer.'] },
  ] } },
  { id: '2026-01-136', theme: 'Les écoles privées ou publiques ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'France Télévisions réalise un reportage sur le sport amateur. Racontez votre pratique sportive et expliquez aux téléspectateurs quel type de sportif vous êtes.' },
    { prompt: 'Vous revenez d’un séjour dans une magnifique région de votre pays. Écrivez un message à vos amis pour raconter vos vacances et expliquer ce qui vous a particulièrement plu.' },
    { prompt: T3('Les écoles privées ou publiques ?'), documents: ['Document 1 : La hausse des inscriptions dans le privé ne s’explique pas seulement par les résultats scolaires. Beaucoup de parents sont attirés par la réputation de ces établissements : ils pensent que les élèves y sont mieux suivis, davantage encadrés et que les enseignants sont plus disponibles. Les classes, souvent composées d’élèves de milieux favorisés, les rassurent aussi. Contrairement au public, ces écoles sont payantes.', 'Document 2 : Dans les collèges privés, les élèves issus de milieux défavorisés sont peu nombreux, car les frais d’inscription excluent certaines familles. Cette séparation entre privé et public limite la mixité sociale. Les jeunes se croisent rarement entre milieux différents, ce qui entretient les inégalités et accentue le sentiment d’exclusion chez certains élèves.'] },
  ] } },
  { id: '2026-01-137', theme: 'Les produits faits maison', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Un(e) ami(e) vous écrit : « Je sais que tu vas dans une salle de sport. Tu peux m’en parler ? » Répondez-lui en décrivant la salle (ambiance, équipements, prix).' },
    { prompt: 'Vous avez suivi une formation, par exemple en langue ou en informatique. Sur un site Internet, racontez cette expérience en décrivant les cours, les participants, les enseignants, ainsi que ce que vous avez aimé ou moins aimé.' },
    { prompt: T3('Les produits faits maison.'), documents: ['Document 1 : Aujourd’hui, on peut fabriquer chez soi presque tous les produits du quotidien : shampooings, savons, crèmes, maquillage ou encore produits ménagers. C’est un vrai avantage, car on maîtrise leur composition. En choisissant des ingrédients naturels et des parfums sans substances chimiques, on limite aussi les emballages et les déchets. Il n’y a plus à hésiter : à vos fabrications maison !', 'Document 2 : Fabriquer son savon chez soi peut sembler séduisant, mais cela comporte des risques pour la santé si les ingrédients sont mal choisis ou si les règles d’hygiène ne sont pas respectées. Il faut donc se documenter sérieusement et suivre des consignes strictes de fabrication et de conservation. Même si cela revient moins cher, ce type de préparation demande souvent beaucoup de temps.'] },
  ] } },
  { id: '2026-01-138', theme: 'Les maisons de retraite, pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous aimeriez aller à un festival de cinéma organisé dans votre ville et vous proposez à votre ami(e) de vous accompagner. Écrivez-lui un message en présentant l’événement et en donnant les renseignements utiles : programme des films, jours, heures, prix des places, etc.' },
    { prompt: 'Après avoir participé récemment à un festival de cinéma, un film vous a vraiment impressionné(e). Rédigez un message à vos amis pour raconter comment s’est passée cette sortie et expliquer pourquoi ce film vous a tant plu.' },
    { prompt: T3('Les maisons de retraite, pour ou contre ?'), documents: ['Document 1 : Les maisons de retraite représentent souvent une solution adaptée pour les personnes âgées. Elles y bénéficient de soins appropriés et de l’accompagnement de professionnels. Elles peuvent aussi participer à des activités qui maintiennent le lien social et évitent l’isolement. Dans certains cas, c’est préférable à la vie seule à domicile. Sophie, infirmière.', 'Document 2 : Les maisons de retraite risquent d’éloigner les personnes âgées de leur entourage et de provoquer un sentiment d’abandon. En outre, la qualité de vie n’y est pas toujours satisfaisante et certains établissements manquent de personnel compétent. Je pense qu’un accompagnement à domicile permet de vieillir en restant entouré de sa famille. Jean, retraité.'] },
  ] } },
  { id: '2026-01-139', theme: 'Faire ses courses alimentaires : chez les producteurs locaux ou au supermarché ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Demain, nous allons passer la journée ensemble dans un parc de loisirs et j’attends ce moment avec impatience. Écrivez à votre ami(e) pour présenter l’organisation de cette sortie, puis demandez-lui ce qu’il/elle préfère savoir (heure de départ, moyen de transport, activités prévues, repas sur place).' },
    { prompt: 'Racontez à vos amis, dans un message, votre visite à un salon du livre. Parlez de ce que vous avez découvert sur place, comme les conférences, les expositions ou les échanges avec des auteurs.' },
    { prompt: T3('Faire ses courses alimentaires : chez les producteurs locaux ou au supermarché ?'), documents: ['Document 1 : Jean, installé en zone rurale, préfère se procurer sa nourriture chez les producteurs. Selon lui, ces aliments offrent une meilleure qualité, même si cela implique un prix légèrement supérieur.', 'Document 2 :   Camille habite en milieu urbain et choisit surtout le supermarché pour faire ses achats, car on y trouve un grand choix de produits. De plus, les tarifs y sont intéressants, ce qui rend cette solution pratique et économique pour elle au quotidien.'] },
  ] } },
  { id: '2026-01-140', theme: 'La chasse aux animaux : pour ou contre ?', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous voulez proposer à votre ami(e) de venir passer les vacances dans votre ville. Écrivez-lui un message pour l’inviter et lui indiquer les sites et lieux intéressants à découvrir.' },
    { prompt: 'Vous avez gagné la possibilité de séjourner deux semaines dans votre ville préférée grâce à un concours dont le thème est « Mon artiste préféré ». Rédigez un billet de blog pour présenter l’artiste que vous aimez le plus.' },
    { prompt: T3('La chasse aux animaux : pour ou contre ?'), documents: ['Document 1 : Je ne comprends pas qu’on puisse tirer sur des animaux pour le plaisir. Pour moi, on ne peut pas dire qu’on aime la nature tout en participant à sa destruction. Gala, 29 ans.', 'Document 2 : La chasse répond à plusieurs objectifs : se nourrir, vendre, protéger la faune, préserver les propriétés, s’entraîner, se divertir ou encore rechercher une certaine reconnaissance. David, journaliste à la FRM.'] },
  ] } },
  { id: '2026-01-141', theme: 'L’art urbain', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Un(e) auteur(e) va bientôt rencontrer les lecteurs à la bibliothèque de votre quartier, et vous souhaitez y assister avec un(e) ami(e). Écrivez-lui un message pour présenter cette rencontre et l’inviter à venir avec vous. (60 mots minimum / 120 mots maximum)' },
    { prompt: 'À l’occasion de la Semaine du goût, vous avez pris part à une activité sur les cuisines du monde. Rédigez un article pour le site web de votre ville afin de raconter cette expérience et d’expliquer ce que vous avez préféré.' },
    { prompt: T3('L’art urbain.'), documents: ['Document 1 : Dans les villes, les murs se couvrent de plus en plus de fresques et de dessins. Cet art dans l’espace public donne une vraie place à la culture, et certaines municipalités proposent des lieux légaux aux artistes. En plus, ces œuvres attirent des visiteurs grâce à des parcours dédiés et font découvrir des quartiers moins connus.', 'Document 2 : Beaucoup de villes dépensent de fortes sommes pour effacer les graffitis, souvent difficiles à nettoyer et parfois confiés à des entreprises spécialisées. Ces peintures dégradent l’image de certains quartiers et irritent les propriétaires. Malgré les interdictions et les amendes, elles continuent pourtant de fleurir sur les murs.'] },
  ] } },
  { id: '2026-01-142', theme: 'La gratuité des musées.', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Vous venez d’emménager et vous cherchez un colocataire. Publiez une annonce en donnant les renseignements essentiels sur le logement, puis décrivez le type de personne avec qui vous aimeriez vivre.' },
    { prompt: 'Vous pratiquez depuis peu un nouveau loisir, par exemple la danse, la peinture ou un sport. Écrivez un message à vos amis pour raconter vos débuts et donner votre avis sur cette activité. (120 mots minimum / 150 mots maximum)' },
    { prompt: T3('La gratuité des musées..'), documents: ['Document 1 : La gratuité fait partie des principes essentiels du musée, car elle va dans le sens du partage culturel. Pour favoriser l’accès du plus grand nombre, les acteurs du secteur soutiennent une démocratisation de la culture. D’ailleurs, les musées nationaux sont gratuits un dimanche par mois afin d’attirer de nouveaux publics et d’affirmer leur rôle éducatif.', 'Document 2 : Rendre les musées entièrement gratuits n’est pas une bonne solution, car cela donne l’impression que la culture n’a pas de coût. Or, ces établissements ont besoin de ressources pour conserver et enrichir leurs collections. Des tarifs réduits ciblés, associés à des activités adaptées pour certains publics, seraient bien plus efficaces pour créer un vrai lien avec les visiteurs.'] },
  ] } },
  { id: '2026-01-143', theme: 'Les jeux vidéo', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Votre amie Carole va bientôt visiter votre ville avec sa famille. Écrivez-lui un message pour leur proposer un programme de visite.' },
    { prompt: 'Rédigez un article de blog sur votre expérience d’apprentissage d’une langue étrangère, comme le français ou une autre langue. Parlez des difficultés rencontrées, des progrès obtenus et des méthodes qui vous ont aidé.' },
    { prompt: T3('Les jeux vidéo.'), documents: ['Document 1 : Les jeux vidéo sont souvent critiqués, mais plusieurs études montrent qu’ils peuvent aussi développer certaines capacités chez les adultes, notamment la rapidité de réaction. C’est un avantage non négligeable, surtout quand on sait que la grande majorité des joueurs sont des personnes majeures. Il faut toutefois rester prudent, car certains jeux encouragent la violence et la dépendance.', 'Document 2 : Les jeux vidéo génèrent des revenus considérables et font l’objet de nombreuses recherches. Une étude menée pendant trois ans auprès d’enfants de 8 à 17 ans a montré que les plus accros deviennent souvent agressifs, nerveux et stressés. Leur scolarité peut même en souffrir, d’où l’importance pour les parents de fixer des limites claires.'] },
  ] } },
  { id: '2026-01-144', theme: 'Le bien-être au travail.', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Répondez à Camille, qui s’intéresse à votre sport depuis peu. Décrivez cette activité et donnez des informations pratiques, comme le lieu, la durée et le prix.' },
    { prompt: 'Vous avez lu sur un forum le message de Paul et Naïma, qui ont tout quitté pour ouvrir une boulangerie à Calgary. Donnez votre avis sur leur décision et expliquez ce que vous feriez à leur place.' },
    { prompt: T3('Le bien-être au travail..'), documents: ['Document 1 : Dans votre entreprise, des bureaux réglables ont été installés pour que chacun puisse travailler dans la position la plus confortable. Les employés disent se sentir mieux, être plus efficaces et mieux concentrés, notamment au téléphone. L’ambiance s’est aussi améliorée, avec davantage d’échanges et une communication plus naturelle entre collègues. Lorie, responsable.', 'Document 2 : Aujourd’hui, les entreprises cherchent toujours à gagner en productivité et en efficacité, parfois au détriment du temps des salariés. Elles multiplient les initiatives pour donner l’impression de veiller à leur santé, mais je veux surtout travailler pendant mes heures réelles, sans devoir rester au-delà avec des heures supplémentaires. Florian, ingénieur.'] },
  ] } },
  { id: '2026-01-145', theme: 'La réduction du temps de travail', created_at: '2026-01-01T00:00:00Z', content: { kind: 'combinaison', year: 2026, month: 1, source: 'candidats', tasks: [
    { prompt: 'Votre ami fête bientôt son anniversaire et vous avez choisi de lui offrir un voyage. Écrivez-lui pour lui expliquer ce que vous avez organisé : la destination, les dates et les différents préparatifs.' },
    { prompt: 'Un internaute écrit : « Je vais partir étudier un an à l’étranger et cela m’inquiète ». Rédigez une réponse pour raconter une expérience personnelle similaire. Présentez les difficultés que vous avez connues, les solutions que vous avez mises en place et ce que cette aventure vous a apporté.' },
    { prompt: T3('La réduction du temps de travail.'), documents: ['Document 1 : Réduire le temps de travail aide les salariés à mieux concilier vie privée et vie professionnelle. Ils disposent ainsi de davantage de temps pour leur famille, leurs loisirs et leur santé. Ce rythme plus léger peut aussi diminuer le stress, augmenter le bien-être au travail et, au final, renforcer la productivité.', 'Document 2 : Pour les entreprises, cette organisation peut limiter l’absentéisme et favoriser la fidélité des salariés. Des horaires aménagés rendent souvent les équipes plus impliquées. En revanche, ce choix demande une gestion rigoureuse et des ajustements internes pour préserver l’efficacité et répondre aux exigences de l’activité.'] },
  ] } },
];
